SELECT 'moj-all-verified-judgments-review-002-chunk-085' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3d612890-9d0d-5caa-b947-0509fe28d663","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -ثمن مبيع -املطالبة بباقي ثمن سيارة -غياب املدعى عليه وتبلغه لشخصه -عدم وجود بينة للمدعي -تبلغ املدعى عليه","document_number":"3446843","case_number":"33381494","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة تبوك على املعاملة الواردة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/25","year":"1434","subject":"بيع -ثمن مبيع -املطالبة بباقي ثمن سيارة -غياب املدعى عليه وتبلغه لشخصه -عدم وجود بينة للمدعي -تبلغ املدعى عليه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/25 :‬هـ‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪3446843 :‬‬\n                  ‫َر ْق ُم الدعوى‪33381494 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34215742‬تاريخه‪1434/5/19 :‬هـ‬\n\n\n‫بيــع ‪ -‬ثمــن مبيــع ‪ -‬املطالبــة بباقــي ثمــن ســيارة ‪ -‬غيــاب املدعــى عليــه‬\n‫وتبلغــه لشــخصه ‪ -‬عــدم وجــود بينــة للمدعــي ‪ -‬تبلــغ املدعــى عليــه‬\n‫ال عــن‬\n      ‫بتوجــه اليمــن عليــه‪ -‬عــدم حضــور املدعــى عليــه يجعلــه نــاك ً‬\n‫أداء اليمــن ‪ -‬احلكــم علــى املدعــى عليــه بدفــع باقــي ثمــن الســيارة ‪-‬‬\n                                     ‫يعــد احلكــم حضوري ـ ًا يف مواجهتــه ‪.‬‬\n\n\n\n\n‫الالئحــة األولــى والرابعــة مــن املــادة (‪ )55‬والالئحــة الرابعــة مــن املــادة‬\n                                     ‫(‪ )109‬مــن نظــام املرافعــات الشــرعية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم‬\n‫واملتبلــغ لشــخصه أنــه اشــترى مــن موكلــه ســيارة مببلــغ أربعــة وعشــرين‬\n‫ألــف ريــال تســلم علــى أقســاط شــهرية مقــدار كل قســط ألــف ريــال ‪،‬‬\n‫وأن املدعــى عليــه ســدد مــن املبلــغ أربعــة عشــر ألــف ريــال وبقــي عشــرة‬\n‫آالف ريــال وطلــب إلزامــه بتســليمها ‪ ،‬بســؤال املدعــي عــن بينتــه علــى‬\n‫دعــواه‪ ،‬قــرر أنــه ال بينــة لديــه‪ ،‬وطلــب ميــن املدعــى عليــه علــى نفــي‬\n‫دعــواه‪ ،‬رفعــت اجللســة لتبليــغ املدعــى عليــه بتوجــه اليمــن عليــه وأنــه يف‬\n‫ال ‪ ،‬لــم يحضــر املدعــى عليــه وقــد تبلــغ‬\n                                            ‫حالــة عــدم حضــوره يعــد نــاك ً‬\n\n                                                                                      ‫‪68‬‬\n\f     ‫لشــخصه مبوعــد اجللســة‪ ،‬وأفهــم بتوجــه اليمــن عليــه بالدعــوى وذلــك‬\n     ‫مبوجــب إفــادة قســم احملضريــن ‪ ،‬عــدم وجــود بينــة للمدعــي وطلبــه‬\n     ‫ميــن خصمــه‪ ،‬وتبلــغ املدعــى عليــه بتوجــه اليمــن عليــه وعــدم حضــوره‬\n     ‫ألدائهــا وبنــاء علــى الالئحــة الرابعــة مــن املــادة (‪ )55‬واملــادة (‪ )109‬مــن‬\n     ‫ال عــن أداء اليمــن‪،‬‬  ‫نظــام املرافعــات الشــرعية يعــد املدعــى عليــه نــاك ً‬\n     ‫ثبــت أن بذمــة املدعــى عليــه للمدعــي أصالــة مبلــغ عشــرة آالف ريــال ومت‬\n     ‫احلكــم بإلزامــه بدفعهــا ‪ ،‬يعــد احلكــم حضوريـ ًا بحــق املدعــى عليــه ‪،‬‬\n                ‫بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫بتبــوك بنــاء علــى املعاملــة احملالــة إلـ َّـي مــن فضيلــة الرئيــس املســاعد‬\n     ‫برقم ‪ 33381494‬يف ‪1433/6/4‬هـ عليه حضر ‪ .........‬ســعودي اجلنســية‬\n     ‫ا عــن املدعــي ‪.........‬‬   ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬بصفتــه وكي ـ ً‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).............‬وذلــك مبوجــب‬\n     ‫وكالتــه الصــادرة مــن كتابــة العــدل الثانيــة بتبــوك برقــم ‪33159319‬‬\n     ‫وتاريــخ ‪1433/7/7‬ه ـ ولــم يحضــر املدعــى عليــه ‪ .................‬وقــد تبلــغ‬\n     ‫لشــخصه مبوعــد هــذه اجللســة وذلــك مبوجــب إفــادة مديــر قســم شــرطة‬\n     ‫احلمــراء برقــم ‪ 56/43/28‬وتاريــخ ‪1434/1/5‬ه ـ فلــذا وبنــاء علــى‬\n     ‫الالئحــة األولــى مــن املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n     ‫الشــرعية جــرى إفهــام املدعــي بــأن لــه أن تســمع دعــواه غيابيـ ًا ففهم ذلك‬\n     ‫ا لقــد بــاع موكلــي للمدعــى عليــه بتاريــخ ‪1429/4/21‬ه ـ‬          ‫وادعــى قائـ ً‬\n     ‫ســيارة نــوع ‪ ...‬صنــع عــام ‪2001‬م مببلــغ أربعــة وعشــرين ألــف ريــال‬\n\n‫‪69‬‬\n\f‫تســدد علــى أقســاط شــهرية مقــدار كل قســط ألــف ريــال تبــدأ بتاريــخ‬\n‫‪1429/4/25‬ه ـ وقــد ســدد املدعــى عليــه مبلــغ أربعــة عشــر ألــف ريــال‬\n‫وتبقــى مبلــغ عشــرة أالف ريــال لــم يســدد منهــا أي شــيء حتــى اآلن أطلــب‬\n‫إلزامــه بســدادها هــذه دعــواي وبســؤال املدعــي وكالــة إن كان لديــه‬\n‫ـدي وأطلــب ميــن املدعــى عليــه‬   ‫بينــة علــى دعــواه أجــاب بقولــه ال بينــة لـ ّ‬\n‫علــى نفــي الدعــوى هكــذا أجــاب وألجلــه رفعــت اجللســة وتأجلــت إلعادة‬\n‫تبليــغ املدعــى عليــه باحلضــور مــع إفهامــه بتوجيــه اليمــن عليــه بالدعــوى‬\n‫ال ويف جلســة أخــرى حضــر‬         ‫وأنــه يف حالــة عــدم حضــوره يعــد نــاك ً‬\n‫املدعــي وكالــة ولــم يحضــر املدعــى عليــه ‪ ...........‬وقــد تبلــغ لشــخصه‬\n‫مبوعــد هــذه اجللســة كمــا أفهــم بتوجــه اليمــن عليــه بالدعــوى وذلــك‬\n‫مبوجــب إفــادة قســم احملضريــن باحملكمــة برقــم ‪ 331053622‬يف‬\n‫‪1434/1/11‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى وعــدم وجــود بينــة‬\n‫للمدعــي وطلبــه ميــن خصمــه وملــا تبلــغ املدعــى عليــه بتوجــه اليمــن عليــه‬\n‫ولــم يحضــر ألدائهــا وبنــاء علــى الالئحــة الرابعــة مــن املــادة (‪ )55‬واملــادة‬\n‫ال عن‬ ‫(‪ )109‬مــن نظــام املرافعــات الشــرعية فــإن املدعــى عليــه يعــد ناك ً‬\n‫ـدي أن بذمــة املدعــى عليــه للمدعــي أصالــة‬     ‫أداء اليمــن لــذا فقــد ثبــت لـ َّ‬\n‫مبلــغ عشــرة آالف ريــال وألزمتــه بدفعهــا وبذلــك حكمــت ويعــد احلكــم‬\n‫حضوري ـ ًا بحــق املدعــى عليــه وســيتم نظــم صــك بذلــك وبعــث نســخة‬\n‫منــه للمدعــى عليــه لتمكينــه مــن االعتــراض مــع إفهامــه بــأن لــه مــدة‬\n‫ثالثــن يومـ ًا مــن تاريــخ اســتالم صــورة إعــام احلكــم لتقــدمي اعتراضــه‬\n‫فــإذا لــم يقــدم اعتراضــه خــال املــدة املقــررة ســقط حقــه يف االعتــراض‬\n‫واكتســب احلكــم الصفــة القطعيــة وللبيــان حــرر يف ‪1434/2/25‬ه ـ‬\n              ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n                                                                                          ‫‪70‬‬\n\f     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬فقــد اطلعن ــا نحــن‬\n     ‫قـض ــاة الدائ ــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة تبوك‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك‬\n     ‫املكلــف برقــم ‪ 331053622‬وتاريــخ ‪1434/4/14‬ه ـ املرفــق بهــا الصك‬\n     ‫الصــادر مــن فضيلــة الشــيخ ‪ .........‬وفقــه اهلل برقــم ‪3446843‬وتاريــخ‬\n     ‫‪1434/2/25‬ه ـ اخلــاص بدعــوى ‪ ...........‬ضــد ‪ .............‬وبدراســة الصــك‬\n     ‫وصــورة ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى احلكــم وبــاهلل‬\n                 ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪71‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":68,"source_page_end":71,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7324b680aee8eb8613cfcd9221b1196409aca573b079a60d6c91cc0e7f73e16d","normalized_text_hash":"95d390cc9cc7b6da2c387fe659f320dfa80bdd37867ddab8320d18455e00084b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p68-3446843"},{"id":"515e1346-3210-5b21-b4e9-0a0512e485cc","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع باآلجل لوحدة سكنية -طلب إلغاء البيع للعجز عن سداد باقي الثمن -معنى اللزوم يف العقود -عدم اتفاق إرادة املتعاقدين يف مجلس واحد -اختاف املتعاقدين يف تفسير بعض شروط العقد -مخالفه الشرط ملقصود العقد -وجوب رضا املتعاقدين يف اثبات العقد أو فسخه .","document_number":"33388994","case_number":"4520","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/21","year":"1434","subject":"بيع -بيع باآلجل لوحدة سكنية -طلب إلغاء البيع للعجز عن سداد باقي الثمن -معنى اللزوم يف العقود -عدم اتفاق إرادة املتعاقدين يف مجلس واحد -اختاف املتعاقدين يف تفسير بعض شروط العقد -مخالفه الشرط ملقصود العقد -وجوب رضا املتعاقدين يف اثبات العقد أو فسخه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/8/21 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33388994 :‬‬\n                        ‫َر ْق ُم الدعوى‪4520 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 33468477‬تاريخه‪1433/11/29 :‬هـ‬\n\n\n‫بيع ‪ -‬بيع باآلجل لوحدة ســكنية ‪ -‬طلب إلغاء البيع للعجز عن ســداد‬\n‫باقــي الثمــن ‪ -‬معنــى اللــزوم يف العقــود ‪ -‬عدم اتفاق إرادة املتعاقدين يف‬\n‫مجلــس واحــد ‪ -‬اختــاف املتعاقديــن يف تفســير بعــض شــروط العقــد‬\n‫‪ -‬مخالفــه الشــرط ملقصــود العقــد ‪ -‬وجــوب رضــا املتعاقديــن يف اثبــات‬\n                                                         ‫العقــد أو فســخه ‪.‬‬\n\n\n\n\n‫‪ -1‬العقــد الــازم هــو الــذي ال يقبــل الفســخ إال برضــا الطرفــن ‪.‬انظــر‪:‬‬\n                        ‫بدائــع الصنائــع للكاســاني رحمــه اهلل (‪.)299/5‬‬\n‫‪ -2‬قال الزركشي رحمه اهلل يف املنثور يف القواعد (‪( :)304/2‬الالزم‪:‬ما‬\n         ‫ال يقبل الفسخ ‪ ،‬أو ال ميكن للغير إبطاله ‪،‬و اجلائز عكسه ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى وكالــة بــأن املدعــى عليــه اشــترى مــن موكلــه وحــده‬\n‫ســكنيه مــن عمارتــه اململوكــة لــه مبوجــب صــك صــادر مــن كتابــة‬\n‫العــدل مببلــغ أربعمائــة وخمســن ألــف ريــال ‪ ،‬و أن املدعــى عليــه ســدد‬\n‫مائتــي ألــف ريــال وتبقــى مائتــان وخمســون ألــف ريــال تدفــع بعــد ســته‬\n‫أشــهر مــن تاريــخ العقــد ‪ ،‬حــل األجــل ولــم يســدد املدعــى عليــه هــذا املبلغ‬\n‫املتبقــي ملوكلــه ‪ ،‬أقــر املدعــى عليــه بالدعــوى ‪ ،‬قــرر املدعــى عليــه أنــه‬\n\n                                                                                       ‫‪72‬‬\n\f     ‫غيــر قــادر علــى الوفــاء يف الوقــت احلاضــر ورغــب يف إلغــاء البيــع وتســليم‬\n     ‫الوحــدة الســكنية للمدعــي بعــد تقديــر اجرتهــا للمــدة التــي بقــى فيهــا‬\n     ‫وحســمها مــن املبلــغ الــذي اســتلمه ‪ ،‬طلــب املدعــي وكالــة الرجــوع‬\n     ‫ملوكلــه ‪ ،‬يف جلســة أخــرى طلــب املدعــى عليــه امضــاء العقــد ‪ ،‬حضــر‬\n     ‫املدعــي أصالــه وطلــب فســخ العقــد ‪ ،‬جــرى االطــاع علــى صــك امللــك ‪،‬‬\n     ‫كمــا جــرى االطــاع علــى عقــد البيــع ورصــد مضمونــه ‪ ،‬حضــر احــد‬\n     ‫شــهود العقــد ورصــدت شــهادته ‪ ،‬اختلــف الطرفــان يف تفســير بعــض‬\n     ‫بنــود العقــد ‪ ،‬قــررت احملكمــة أن شــرط بقــاء املبيــع يف ملــك البائــع‬\n     ‫حلــن ســداد كامــل الثمــن شــرط فاســد ملخالفتــه ملقصــود البيــع ‪ ،‬صــدر‬\n     ‫احلكــم بــرد دعــوى املدعــي يف مطالبتــه بفســخ عقــد البيــع‪ ،‬احلكــم‬\n     ‫بصحــة عقــد البيــع ولزومــه ‪ ،‬جــرى افهــام املدعــي بــأن لــه مطالبــة‬\n     ‫املدعــى عليــه بدفــع مــا تبقــى مــن قيمــه املبيــع ‪ ،‬اعتــرض املدعــي علــى‬\n                           ‫احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .......‬القاضــي باحملكمــة العامة بالدمام‬\n     ‫ـاء علــى االوراق الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬    ‫بنـ ً‬\n     ‫بالدمــام برقــم ‪4520‬يف ‪1431/6/16‬ه ـ املقيــدة بهــذه احملكمــة برقــم‬\n     ‫‪ 31/18041‬يف ‪1431/6/16‬ه ـ حضــر ‪ .......‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪...‬بالوكالــة عــن ‪ .......‬مبوجــب الوكالــة الصــادرة‬\n     ‫مــن كتابــة عــدل محافظــة بلقرن برقــم ‪16‬يف‪1431/9/5‬هـ مجلد‪1642‬‬\n     ‫وحضــر حلضــوره ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقم‪.......‬‬\n     ‫وادعــى األول بقولــه‪ :‬بتاريــخ ‪2008/3/26‬م بــاع موكلــي علــى املدعــى‬\n\n‫‪73‬‬\n\f‫عليــه ‪...‬هــذا احلاضــر كامــل الوحــدة الســكنية رقــم(‪ )12‬مــن العمــارة‬\n‫املقامــة علــى قطعــة األرض رقــم(‪ )70‬مــن املخطــط رقــم ‪ 1/197‬بحــي‬\n‫املنــار بالدمــام العائــدة ملوكلــي مبوجــب الصــك الصــادر مــن كتابــة‬\n‫عــدل الدمــام االولــى برقــم‪339100401033‬يف ‪1426/11/26‬ه ـ بقيمــة‬\n‫قدرهــا اربعمائــة وخمســون الــف ريــال ســدد منهــا املدعــى عليــه عنــد‬\n‫العقــد مبلــغ وقــدره مائتــا ألــف ريــال علــى أن يســدد الباقــي وقــدره مائتان‬\n‫وخمســون ألــف ريــال بعــد مضــي ســتة أشــهر اعتبــار ًا مــن تاريــخ البيــع‬\n‫وقــد حــل موعــد الســداد ولــم يســدد املدعــى عليــه ملوكلــي مــن املتبقــي‬\n‫شــيئ ًا حتــى اآلن لــذا أطلــب إلــزام املدعــى عليــه بدفــع مائتــن وخمســن‬\n‫ألــف ريــال ملوكلــي هــذه دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه ‪:‬‬\n‫ا وأنــا‬‫مــا ذكــر املدعــي وكالــه يف دعــواه كلــه صحيــح جملـ ًة وتفصيـ ً‬\n‫غيــر قــادر علــى الوفــاء يف الوقــت احلاضــر وأرغــب يف إلغــاء البيــع وتســليم‬\n‫الوحــدة الســكنية ملــوكل املدعــي بعــد تقديــر اجرتهــا للمــدة التــي‬\n‫بقيــت فيهــا وحســمها مــن املبلــغ الــذي ملوكلــه وتســليمي املتبقــي هكــذا‬\n‫أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال أطلــب إمهالــي للرجــوع‬\n‫ملوكلــي لعــرض ذلــك عليــه وإفادتكــم هكــذا قــرر فأجيــب لطلبــه‬\n‫ورفعــت اجللســة لذلــك ثــم يف جلســة أخــرى حضــر املدعــي أصالــة ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر حلضــوره ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬بالوكالــة عــن ‪.......‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام الثانيــة برقــم‬\n‫‪ 60822‬يف ‪1431/2 1/30‬ه ـ جلــد ‪ 9149‬املخــول للوكيــل فيهــا حــق‬\n‫املطالبــة واملداعــاة واملخاصمــة وســماع الدعــاوي والــرد عليهــا وإقامــة‬\n‫البينــة والدفــع وقبــول احلكــم واالعتــراض عليــه يف أي دعــوى تقــام منــه‬\n\n\n                                                                                      ‫‪74‬‬\n\f     ‫أو ضــده وليــس فيهــا حــق اإلقــرار وقــد أعيــدت لنــا املعاملــة بخطــاب‬\n     ‫مأمــور قســم احملفوظــات باحملكمــة رقــم‪31 /18041‬يف‬\n     ‫‪1431/11/26‬ه ـ وقــال املدعــى أصالــة لقــد أخبرنــي وكيلــي الشــرعي‬\n     ‫‪ ...‬بــأن املدعــى عليــه ال يســتطيع ســداد باقــي القيمــة وأنــه يرغــب الغــاء‬\n     ‫ـاء عليــه وألنــه قــد تأخــر عــن ســداد الدفعــة الثانيــة عــن املوعــد‬\n                                                                             ‫البيــع وبنـ ً‬\n     ‫احملــدد وألن العقــد الــذي بيننــا قــد نــص علــى أن يتــم تســديد الدفعــة‬\n     ‫الثانيــة مــن القيمــة وقدرهــا مائتــان وخمســون ألــف ريــال بحــد أقصــى‬\n     ‫ســتة أشــهر مــن تاريــخ العقــد املبــرم يف ‪2008/6/8‬م لــذا أطلــب إلغــاء‬\n     ‫هــذا البيــع وإلــزام مــوكل املدعــى عليــه بتســليمي الشــقة املباعــة هكذا‬\n     ‫قــرر ثــم يف جلســة أخــرى حضــر املدعــي أصالــة ‪ .......‬وأبــرز صــك‬\n     ‫امللكية الصادر من كتابة عدل الدمام األولى برقم ‪630102010282‬‬\n     ‫يف ‪1430/7/13‬ه ـ املتضمــن متلكــه لقطعــة األرض رقــم (‪ )70‬مــن‬\n     ‫املخطــط رقــم (‪)1/791‬الواقــع بحــي الفــردوس بالدمــام واملذكــورة‬\n     ‫حدودهــا وأطوالهــا فيــه ومظهــر هــذا الصــك بتهميشــات تتضمــن انتقــال‬\n     ‫بعــض الشــقق آلخريــن كمــا أبــرز املدعــي العقــد الصادر من ‪...‬للتســويق‬\n     ‫العقــاري بتاريــخ ‪2008/3/26‬م املتضمــن بيــع ‪...‬الوحــدة الســكنية رقــم‬\n     ‫(‪ )12‬يف الــدور الرابــع مــن املبنــى املقــام علــى قطعــة األرض رقــم (‪)70‬‬\n     ‫مــن املخطــط رقــم ‪ 1/791‬بحــي املنــار بالدمــام علــى املدعــو ‪...‬بقيمــة‬\n     ‫قدرهــا أربعمائــة وخمســون الــف ريــال عنــد توقيــع العقــد والثانيــة متثــل‬\n     ‫مائتــان وخمســون الــف ريــال تدفــع بحــد أقصــى ســتة أشــهر مــن تاريــخ‬\n     ‫العقــد وقــد مت تســديد الدفعــة األولــى واإلفــراغ بعــد تكملــة املبلــغ وهــذا‬\n     ‫العقــد وفــق ســتة بنــود ومذيــل بتوقيــع كل مــن البائــع واملشــتري وتوقيــع‬\n     ‫الشــاهد ‪ .......‬وتوقيــع الشــاهد ‪ .......‬كمــا أحضــر املدعــي معــه ‪.......‬‬\n\n\n‫‪75‬‬\n\f‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬مــن مواليــد عــام ‪1399‬‬\n‫وبســؤاله عمــا لديــه قــال ‪:‬ال تربطنــي قرابــة باملدعــي ‪...‬وأشــهد هلل تعالــى‬\n‫أنــه بتاريــخ ‪2008/3/26‬م مت إبــرام عقــد بي ــع عقـ ــار مــن ‪ .......‬و‪ .......‬لدى‬\n‫مكتــب ‪...‬العقــاري باخلبــر حيــث بــاع ‪...‬املذكــور علــى ‪...‬املذكــور علــى‬\n‫‪ .......‬املذكــور كامــل الوحــدة الســكنية رقــم (‪ )12‬مــن الــدور الرابــع‬\n‫مــن املبنــى املقــام علــى قطعــة األرض رقم (‪ )70‬مــن املخطط رقم ‪1/197‬‬\n‫بحــي املنــار العائــدة ل‪ .......‬املذكــور مبوجــب الصــك الصــادر من كتابة‬\n‫الدمــام األولــى برقـ ــم ‪ 330104001933‬يف ‪1426/11/26‬ه ـ بقيمــة‬\n‫قدرهــا أربعمائــة وخمســون ألــف ريــال تســدد علــى دفعتني األولــى قدرها‬\n‫مائتــا ألــف ريــال وقــد ســددت عنــد العقــد والثانيــة قدرهــا مائتــان‬\n‫وخمســون ألــف ريــال تســدد بحــد أقصــى ســتة شــهور مــن تاريــخ العقــد‬\n‫وقــد مت حتريــر عقــد بذلــك ووقعــت عليــه بصفتــي شــاهد هــذا مــا لــدي‬\n‫وعليــه أوقــع هكــذا شــهد ثــم ســألت املدعــي عــن الشــاهد الثانــي يف‬\n‫العقــد فقــال أطلــب إمهالــي إلحضــاره يف اجللســة القادمــة ثــم يف جلســة‬\n‫أخــرى حضــر املدعــي أصالــة ‪ .......‬وســألته عــن الشــاهد الثانــي فقــال لــم‬\n‫أحضــره يف هــذه اجللســة وأطلــب إمهالــي ألمتكــن مــن إحضــاره وســماع‬\n‫مــا لديــه هكــذا قــرر وأجيــب لطلبــه ثــم يف جلســة أخــرى احلمــد هلل‬\n‫وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة بالدمــام‬\n‫حضــر املدعــي أصالــة ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪...‬وحضــر املدعــى عليــه وكالــة ‪ .......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫الدمــام الثانيــة الوكيــل عــن ‪ .......‬برقــم ‪ 27612‬وتاريــخ ‪1432/6/4‬ه ـ‬\n‫واملخــول لــه فيهــا حــق املطالبــة واملخاصمــة واملداعــاة وســماع الدعــاوي‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫والــرد عليهــا وإقامــة البينــة واإلقــرار والدفــع وقبــول احلكــم واالعتــراض‬\n     ‫عليــه وذلــك يف أي قضيــة تقــام منــي أو ضــدي أمــام أي محكمــة ويف أي‬\n     ‫جهــة وإنهــاء كافــة اإلجــراءات الشــرعية وجــرى تــاوة مــا ســبق ضبطــه‬\n     ‫مــن الدعــوى ومــا مت بعــد ذلــك فســألت املتداعيــن مبــا دون فصادقــا‬\n     ‫عليــه وطلبــا إكمــال الــازم والنظــر علــى ضوئــه ثــم يف جلســة أخــرى‬\n     ‫حضــر الطرفــان ويف هــذه اجللســة جــرى عــرض العقــد املوصــوف يف‬\n     ‫جلســة ســابقة لــدى القاضــي الســلف فقــرر بقولــه هــذا العقــد املتفــق‬\n     ‫عليــه بــن موكلــي وهــذا احلاضــر وهــي اتفاقيــة مــن ســبعة بنــود مــع‬\n     ‫متهيــد ســابق لهــا ثــم قــرر بقولــه إن موكلــي مســتعد بدفــع كامــل املبلــغ‬\n     ‫املتبقــي بشــيك مصــدق هكــذا قــرر وبعــرض ذلــك علــى املدعــي قــرر‬\n     ‫بقولــه أطلــب فســخ العقــد بيننــا ولســت راغــب يف إمضــاء البيــع مــع‬\n     ‫مــوكل هــذا احلاضــر هكــذا قــرر ثــم جــرى ســؤالهما عــن تفســير‬\n     ‫مقصودهمــا يف البنــد ثانيـ ًا واملتضمــن مــا نصــه ‪ ( :‬مــن املتفــق عليــه بــن‬\n     ‫ا مللكيــة الوحــدة إلى الطرف‬      ‫الطرفــن أن هنــا العقــد ال يعتبــر بيعـ ًا ناقـ ً‬\n     ‫الثانــي إال بعــد ســداد كامــل قيمــة الوحــدة إلــى الطــرف األول وإمتــام‬\n     ‫البيــع باإلفــراغ لصالــح الطــرف الثانــي لــدى كاتــب عــدل ) فاســتعد‬\n     ‫كل طــرف منهمــا يف اجللســة القادمــة تقــدمي تفســير ملقصودهمــا لــذا‬\n     ‫فقــد رفعــت اجللســة ثــم يف جلســة أخــرى حضــر املدعــي واملدعــى عليــه‬\n     ‫وكالــة وقــدم املدعــي ورقــة لتفســير البنــد الثانــي مــن العقــد نصهــا مــا‬\n     ‫يلــي ‪ ( :‬أمــا عــن تفســير البنــد الثانــي مــن العقــد فهــو أن املبايعــة تلغــى يف‬\n     ‫حــال عــدم قيــام املشــتري بســداد كامــل قيمــة الشــقة خــال ســتة أشــهر‬\n     ‫وأن ال حجيــة لهــذا العقــد اال بعــد إفــراغ الشــقة للمشــتري لــدى كتابــة‬\n     ‫العــدل أي أن العقــد ال يعتــد بــه إذا لــم يتبــع باإلفــراغ لــدى كتابــة العــدل‬\n\n\n‫‪77‬‬\n\f‫وهــذا البنــد يلــزم البائــع إفــراغ الشــقة للمشــتري عنــد كتابــة العــدل بعــد‬\n‫ســداد املبلــغ يف الســتة أشــهر التاليــة لتوقيــع العقــد ويلــزم املشــتري إعــادة‬\n‫الشــقة إلــى صاحبهــا يف حــال عــدم دفعــه للمبلــغ يف املــدة املشــار لهــا‬\n‫وهــذا مــا أطلبــه ‪ .‬االســم ‪ .......‬توقيعــه‪ ).......‬ثــم قــرر املدعــي بقولــه هــذا‬\n‫مــا لــدي مــن تفســير للمــادة املشــار إليهــا يف العقــد واالتفاقيــة وقــد‬\n‫كتبــت هــذا التفســير بعــد مراجعــة املكتــب الــذي أجــرى العقــد بيننــا‬\n‫هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــرر بقولــه إن‬\n‫هــذا التفســير الــذي ذكــره املدعــي غيــر صحيــح وإمنــا الصحيــح ســآتي‬\n‫بــه يف اجللســة املقبلــة أطلــب إمهالــي إلحضــاره هكــذا قــرر ثــم يف جلســة‬\n‫أخــرى حضــر الطرفــان وقــدم املدعــى عليــه وكالــة ورقــة نــص احلاجــة‬\n‫منهــا مــا يلــي‪ ( :‬بخصــوص طلــب تفســير البنــد الثانــي يف العقــد املبــرم‬\n‫بني ‪ .......‬وموكلي ‪ .......‬أفيد فضيلتكم بأن ــه مفسر يف البند اخلامس‬\n‫مــن نفــس العقــد ) ‪.‬اه ـ ‪ .‬وبالرجــوع إلــى البنــد اخلامــس والــذي نصــه مــا‬\n‫يلــي ‪ ( :‬ال يحــق للطــرف الثانــي التصــرف يف الوحــدة موضــوع هــذا العقد‬\n‫بــأي تصــرف ناقــل امللكيــة إال بعــد ســداد كامــل قيمتهــا وإفراغهــا لــه‬\n‫ا أي تصــرف قبــل اإلفــراغ واحليــازة‬    ‫وامتالكهــا امللــك التــام ويعــد باط ـ ً‬\n‫وتعتبــر الشــقة يف ملــك الطــرف األول حلــن ســداد كامــل قيمتهــا‬\n‫وتســليمها للطــرف الثانــي ) ‪.‬اه ـ ‪ .‬وبعرضــه علــى املدعــي قــرر بقولــه‬\n‫ســبق وأن فســرت املــادة ومــا ذكــره مــن تفســير فهــو راجــع للبنــد الثالــث‬\n‫هكــذا قــرر ثــم جــرى ســؤال اخلصمــن ألديكــم إضافــة علــى مــا تقــدم‬\n‫فأجــاب كل واحــد منهمــا أن ال مزيــد علــى مــا قدمنــا هكــذا قــررا‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق الطرفــان على‬         ‫فبنـ ً‬\n‫صحــة البيــع بينهمــا ودفــع املشــتري أكثــر مــن ثلــث املبلــغ ودخــل املبيــع‬\n\n\n                                                                                            ‫‪78‬‬\n\f     ‫يف حيــازة املشــتري ومبــا أن املدعــي عــدل عــن املطالبــة باملبلــغ املتبقــي‬\n     ‫إلــى طلــب فســخ العقــد ومبــا أن عقــد البيــع عقــد الزم ال يفســخ إال برضــا‬\n     ‫الطرفــن واختيارهمــا وال ينفــرد بــه أحدهمــا دون رضــا اآلخــر واللــزوم‬\n     ‫كمــا يف تعبيــرات الفقهــاء هــو الــذي ال يقبــل الفســخ جــاء يف بدائــع‬\n     ‫الصنائــع للكاســاني رحمــه اهلل ( ‪ ( : ) 299/5‬والعقــد الــازم ‪ :‬ال‬\n     ‫يحتمــل الفســخ ) كمــا جــاء يف املنثــور يف القواعــد للزركشــي رحمــة‬\n     ‫اهلل ( ‪ ( : ) 304 /2‬الــازم‪ :‬مــاال يقبــل الفســخ ‪ ،‬أو ال ميكــن الغيــر‬\n     ‫إبطالــه ‪ ،‬واجلائــز عكســه )‪ .‬ومــا ذكــره املدعــى عليــه أصالــة مــن‬\n     ‫رغبتــه بإقالتــه مــن البيــع يف أول اجللســات فاإلقالــة رفــع عقــد الزم ‪،‬‬\n     ‫فالبــد مــن رضــى الطرفــن ‪ ،‬وكمــا يشــترط الرضــا يف إثبــات العقــد‬\n     ‫ـاء عليــه فإنــه يشــترط احتــاد املجلــس لرفع‬   ‫كذلــك يشــترط يف رفعــه وبنـ ً‬\n     ‫العقــد باإلقالــة كمــا يشــترط إلثباتــه ‪ ،‬ألن معنــى العقــد موجــود فيهــا‬\n     ‫وحيــث لــم تتفــق اإلرادتــن يف مجلــس واحــد واختلفــت فيمــا بعــد ومبــا أن‬\n     ‫الطرفــن قــد اختلفــا يف تفســير البنــد الثانــي وظاهــر البنــد أنــه ال يعتبــر‬\n     ‫بيع ـ ًا ويؤكــده مــا جــاء يف آخــر البنــد اخلامــس حيــث جــاء مــا نصــه‬\n     ‫(تعتبــر الشــقة يف ملــك الطــرف األول حلــن ســداد كل قيمتها وتســليهما‬\n     ‫للطــرف الثانــي ) وال شــك أن هــذا شــرط مخالــف ملقصــود البيــع فهــو‬\n     ‫مــن الشــروط الفاســدة وال يعتــد بــه لذلــك كلــه فقــد رددت دعــوى‬\n     ‫املدعــي يف مطالبتــه فســخ العقــد وحكمــت بصحــة العقــد ولزومــه‬\n     ‫وأفهمتــه بــأن لــه مطالبــة املدعــى عليــه يف بقيــة املبلــغ وبعــرض احلكــم‬\n     ‫علــى الطرفــن قــرر املدعــي عــدم قناعتــه بــه وقــرر املدعــى عليــه القناعــة‬\n     ‫وطلــب املدعــي االســتئناف فأفهــم بــأن مــدة االعتــراض ثالثــون يوم ـ ًا‬\n     ‫تبــدأ بعــد مهلــة تنظيــم الصــك خمســة أيــام إذا مضــت املــدة ولــم يقــدم‬\n\n\n‫‪79‬‬\n\f‫الئحــة اعتراضيــة ســقط حقــه يف طلــب االســتئناف ولــه املراجعــة خــال‬\n‫املهلــة واملــدة النظاميــة الســتالم نســخة احلكــم لالعتــراض عليــه وبــاهلل‬\n‫التوفيــق وختمــت اجللســة يف متــام الســاعة احلاديــة عشــرة‪،‬وصلى اهلل‬\n   ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1433/08/10‬هـ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ .......‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى‬\n‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام املســاعد برقــم‬\n‫‪ 33/2232006‬وتاريــخ ‪1434/2/3‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34/305521‬وتاريــخ ‪1434/2/3‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ .......‬املســجل برقــم ‪33388994‬‬\n‫وتاريــخ ‪1433/8/21‬ه ـ اخلــاص بدعــوى ‪ .......‬ضــد ‪ .......‬يف قضيــة‬\n‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ ،‬ولبيانــه‬\n                                                                  ‫املعاملــة ّ‬\n                          ‫حــرر يف ‪1434/3/9‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                   ‫‪80‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":72,"source_page_end":80,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8f27134aec2524b46d6227d4319d1db24109b2e9877b28eda80040e6e3ee30e1","normalized_text_hash":"c006a4c860cc810c567d6ba4abc87336e32508c0525b44581271e8c45a50a5c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p72-33388994"},{"id":"1ad11f21-e5ab-53ca-ba03-b7d8cf549bd3","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة -فسخ البيع أو رد ثمن السيارة لعيب فيها -تقدير العيب عن طريق قسم اخلبراء -العيب يوجب إما اإلمساك أو الفسخ -احلكم بفسخ البيع ورد ثمن املبيع .","document_number":"33439017","case_number":"33405137","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة وبتعميد فضيلته لي بنظر هذه القضية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/25","year":"1434","subject":"بيع -بيع سيارة -فسخ البيع أو رد ثمن السيارة لعيب فيها -تقدير العيب عن طريق قسم اخلبراء -العيب يوجب إما اإلمساك أو الفسخ -احلكم بفسخ البيع ورد ثمن املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/10/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33439017 :‬‬\n                         ‫َر ْق ُم الدعوى‪33405137 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34241289‬تاريخه‪1434/6/14 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع ســيارة ‪ -‬فســخ البيــع أو رد ثمــن الســيارة لعيــب فيهــا ‪ -‬تقديــر‬\n      ‫العيــب عــن طريــق قســم اخلبــراء ‪ -‬العيــب يوجــب إمــا اإلمســاك أو‬\n                               ‫الفســخ ‪ -‬احلكــم بفســخ البيــع ورد ثمــن املبيــع ‪.‬‬\n\n\n\n\n      ‫‪ .1‬ذكــر صاحــب املقنــع (‪ )44/2‬مــا نصــه‪ « :‬فمــن اشــترى معيبــا لــم‬\n                                 ‫يعلــم عيبــه فلــه اخليــار بــن الــرد واإلمســاك»‪.‬‬\n      ‫‪ .2‬ذكــر ابــن قدامــة يف املغنــي (‪ )522/6‬مــا نصــه‪« :‬أنــه متــى علم باملبيع‬\n      ‫عيبـ ًا لــم يكــن عاملـ ًا بــه فلــه اخليــار بــن اإلمســاك والفســخ ســواء كان‬\n                                        ‫البائــع علــم بالعيــب وكتمــه أو لــم يعلــم»‪.‬‬\n      ‫‪ .3‬مــا روي عــن النبــي صلــى اهلل عليــه وســلم أنــه اشــترى مملوكا فكتب‬\n      ‫(هــذا مــا اشــترى محمــد بــن عبــداهلل مــن العــداء بــن خالــد اشــترى منــه‬\n                             ‫عبــدا أو أمــة الداء بــه وال غائلــة بيــع املســلم واملســلم)‬\n      ‫‪ .4‬ذكر الزحيلي يف الفقه اإلسالمي وأدلته (‪ )261/4‬ما نصه‪« :‬يثبت‬\n      ‫خيــار العيــب متــى ظهــر العيــب ولــو بعــد العقــد بزمــن طويــل ويقــول‬\n      ‫أيضــا «وإذا لــم تتوافــر الســامة لــم يتحقــق أيض ـ ًا مبــدأ التعــادل يف‬\n      ‫التبــادل الــذي تقــوم عليــه عقــود املعاوضــات فشــرع هــذا اخليــار حفاظــا‬\n      ‫علــى مبــدأ املســاواة وقــد أثبــت الشــرع هــذا اخليــار ملــن فوجــئ بالعيــب‬\n      ‫بأحاديــث نبويــة متعــددة منهــا (املســلم أخــو املســلم) (ال يحــل ملســلم باع‬\n      ‫مــن أخيــه بيع ـ ًا وفيــه عيــب إال بينــه) وقولــه‪( :‬مــن غشــنا فليــس منــا)‬\n‫‪81‬‬\n\f‫وقــال أيضــا «وممــا يثبــت فيــه اخليــار مــا كان محــل العقد عينــا معينة‬\n    ‫أو مشــخصة مــن األعيــان كمــا األرض والــدار والدابــة والســيارة»‬\n                             ‫‪ .5‬املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن الشــركة املدعــى عليهــا ســيارة جديــدة‬\n‫موصوفــة يف الدعــوى وبعــد اســتخدامه لهــا ظهــر فيهــا عيــوب مصنعيــة‬\n‫مذكــورة يف دعــواه‪ ،‬ولــذا طلــب إلــزام املدعــى عليهــا باســتالم الســيارة‬\n‫وتســليمه قيمتهــا ‪ ،‬أنكــر وكيــل املدعــى عليهــا مــا جــاء يف الدعــوى‬\n‫ودفــع بــأن الضمــان ال يخــول للمدعــي تغييــر الســيارة وإمنــا تصليــح‬\n‫األعطــال الناجتــة عــن خلــل يف التصنيــع أو اســتبدال القطعــة إذا تعــذر‬\n‫إصالحهــا ‪ ،‬قــررت احملكمــة تكليــف اخلبــراء بفحــص الســيارة وتقــدمي‬\n‫تقريــر عــن ســبب اخللــل فيهــا فأفــادوا بوجــود عيــب يف احملــرك وأنــه‬\n‫ال يوجــد ســوء اســتخدام للســيارة ‪ ،‬متــى علــم املشــتري باملبيــع عيبــا‬\n‫لــم يكــن عاملــا بــه فلــه اخليــار بــن اإلمســاك والفســخ ســواء كان‬\n‫البائــع علــم بالعيــب وكتمــه أو لــم يعلــم ‪ ،‬قضــت احملكمــة بفســخ‬\n‫عقــد بيــع الســيارة املذكــورة كمــا حكمــت علــى الشــركة املدعــى‬\n‫عليهــا بإعــادة كامــل ثمــن الســيارة إلــى املدعــي‪ ،‬قنــع املدعــي باحلكــم‬\n‫وعارضــت عليــه املدعــى عليهــا ‪ ،‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                 ‫علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪82‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n     ‫أنــا (‪ )....‬املــازم القضائــي لــدى فضيلــة الشــيخ (‪ )........‬القاضــي يف‬\n     ‫احملكمــة العامــة ببريــدة وبتعميــد فضيلتــه لــي بنظــر هــذه القضيــة‬\n     ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n                                                                               ‫وبنـ ً‬\n     ‫ببريــدة املســاعد برقــم ‪ 33405137‬وتاريخ‪1433/6/16‬ه ـ واملقيــدة يف‬\n     ‫احملكمــة برقــم ‪ 331128692‬وتاريــخ ‪1433/6/16‬ه ـ ففــي هــذا اليــوم‬\n     ‫االثنــن املوافــق ‪1433/6/30‬ه ـ ويف الســاعة الثامنــة والنصــف صباحـ ًا‬\n     ‫افتتحــت اجللســة وفيهــا حضــر (‪ )........‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم (‪ )........‬ولــم يحضــر املدعى عليه شــركة (‪ )........‬للســيارات‬\n     ‫وباالطــاع علــى ورقــة التبليــغ املؤرخــة ب ـ ‪1433/6/16‬ه ـ تبــن أنــه مت‬\n     ‫ـاء علــى املــادة (‪ )55‬مــن‬\n                                ‫التبليــغ عــن طريــق ســكرتارية الشــركة وبنـ ً‬\n     ‫نظــام املرافعــات الشــرعية فقــد جــرى رفــع هــذه اجللســة إلعــادة التبليــغ‬\n     ‫مرة أخرى ويف هذا اليوم الســبت املوافق ‪1433/7/5‬هـ افتتحت اجللســة‬\n     ‫وفيهــا حضــر املدعــي وحضــر حلضــوره (‪ )........‬ســعودي اجلنســية مبوجــب‬\n     ‫ا عــن املدعــى عليــه مبوجــب‬  ‫الســجل املدنــي رقــم (‪ )........‬بصفتــه وكيـ ً‬\n     ‫الوكالة رقم ‪ 12152‬وتاريخ ‪1428/2/27‬هـ الصادرة من كتابة عدل‬\n     ‫ا أننــي اشــتريت‬  ‫الدمــام الثانيــة وبســؤال املدعــي عــن دعــواه أجــاب قائـ ً‬\n     ‫ســيارة جديــدة مــن شــركة (‪ )........‬للســيارات مــن نــوع (‪ )........‬موديــل‬\n     ‫(‪ )........‬ولكــن انتبهــت للزيــت بعــد مســافة ‪25000‬كــم ولــم أخبــر عــن‬\n     ‫نقصــه أثنــاء تغييــره عندهــم وكنــت متابــع للصيانــة عندهــم ففوجئــت‬\n     ‫بــأن الزيــت ينقــص مــن املاكينــة وأخبرتهــم ومت فحصهــا مــع وجــود‬\n\n‫‪83‬‬\n\f‫علــة أخــرى وهــي صــوت قــوي داخــل املاكينــة ثــم قامــوا بإصالحهــا‬\n‫وأخبرونــي أن الزيــت رمبــا مــن هــذه املشــكلة ولكنهــا اســتمرت‬\n‫وراجعتهــم مــرة أخــرى ثــم حجزوهــا عندهــم ثــم أخبرونــي بجاهزيتهــا‬\n‫وبعــد ذلــك راجعتهــم للمــرة الثالثــة فأخبرونــي أنهــا حتتــاج إلــى توضيــب‬\n‫ولــم يبلــغ مشــيها ‪ 50000‬ألــف كــم وطالبتهــم بعــدم توضيــب املاكينــة‬\n‫ألن التوضيــب يؤثــر علــى قيمــة الســيارة وأنــا أدعــي الغــن يف الســيارة‬\n‫وطلبــي يف هــذه الدعــوى إلــزام املدعــى عليــه بإعطائــي ســيارة جديــدة‬\n‫بــدل احلاليــة وإعطائــي ضمــان كامــل وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه وكالــة أجــاب بــأن الضمــان ال يخــول للمدعــي تغييــر الســيارة وإمنــا‬\n‫تصليــح األعطــال الناجتــة عــن خلــل يف التصنيــع وإذا جتــاوزت نســبة‬\n‫التصليــح ‪ 80‬باملئــة مــن القطعــة فــإن القطعــة تغيــر بالكامــل وال تغيــر‬\n‫الســيارة هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة وحيــث األمــر‬\n‫مــا ذكــر فقــد قــررت الكتابــة إلــى كليــة التقنيــة بعنيــزة لتزويدنــا‬\n‫بتقريــر عــن ســبب اخللــل يف الســيارة وحتــى ورود الــرد منهــم فقــد‬\n‫رفعــت اجللســة ويف يــوم األثنــن ‪1433/9/18‬ه ـ افتتحــت اجللســة لــدي‬\n‫أنــا (‪ )........‬القاضــي يف احملكمــة العامــة ببريــدة نظــر ًا النتقــال املــازم‬\n‫(‪ )........‬عــن هــذا املكتــب وفيهــا حضــر الطرفــان وقــد ســبق أن كتبنــا‬\n‫للكليــة التقنيــة بخطابنــا رقــم ‪ 33/1254617‬يف ‪1433/7/5‬ه ـ فوردنــا‬\n‫خطابهــم رقــم ‪ 346‬يف ‪1433/8/5‬ه ـ املتضمــن أن اللجنــة املشــكلة مــن‬\n‫قســم التقنيــة امليكانيكيــة لفحــص الســيارة أفــادت أنــه ال يوجــد هناك‬\n‫ســوء اســتخدام للســيارة كمــا هــو مرفــق بالتقريــر وبعــرض ذلــك علــى‬\n‫املدعــى عليــه وكالــة أجــاب أطلــب نســخة مــن هــذا التقريــر لعرضــه‬\n‫علــى الشــركة وحيــث ال مانــع لــذا فقــد جــرى تزويــده بنســخة منــه كما‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫جــرى ســؤال املدعــي عــن طلبــه فأجــاب بأنــه مــادام أن هــذا عيــب فأنــا‬\n     ‫أطالــب بــرد الســيارة وتســليمي قيمتهــا وقــدره مائــة وســتة وأربعــون ألــف‬\n     ‫ريــال هكــذا أجــاب كمــا جــرى ســؤال املدعــى عليــه وكالــة عــن دعوى‬\n     ‫املدعــي بشــأن شــراء الســيارة فقــال إن مــا ذكــره املدعــي يف دعــواه مــن‬\n     ‫شــرائه الســيارة نوعهــا (‪ )........‬موديــل (‪ )........‬صحيــح هكــذا أجــاب ‪،‬‬\n     ‫لذا جرى رفع اجللسة ويف يوم األربعاء ‪1433/10/25‬هـ افتتحت اجللسة‬\n     ‫وفيهــا حضــر الطرفــان وقــد جــرى ســؤالهما هــل لديكمــا إضافــة فأفــاد‬\n     ‫املدعــى عليــه وكالــة بــأن الكفالــة احملــدودة للســيارات اجلديــدة تشــمل‬\n     ‫الكفالــة التصليحــات الالزمــة لتصحيــح األعطــال التــي حتــدث أثنــاء‬\n     ‫مــدة الكفالــة والناجتــة عــن ســوء يف التصنيــع أو املــواد املســتعملة ســيتم‬\n     ‫إجــراء أيــة عمليــة ضبــط الزمــة أثنــاء مــدة الكفالــة ســيتم اســتعمال‬\n     ‫قطــع جديــدة أو قطــع معــاد تصنيعهــا وبعــرض ذلــك علــى املدعــي أجــاب‬\n     ‫بــأن العيــب ليــس مــن ســوء االســتعمال بــل مــن جدهــا وهــو فيهــا العيــب‬\n     ‫وقــد مت إصالحهــا مــن قبلهــم ولــم تتغيــر هكــذا أجــاب فبنــاء علــى مــا‬\n     ‫تقــدم مــن الدعــوى واإلجابــة واالطــاع علــى قــرار اللجنــة املشــكلة يف‬\n     ‫الكليــة التقنيــة وبعــد االطــاع علــى وثيقــة ملكيــة الســيارة ومبــا أن‬\n     ‫املدعــي يطالــب بــرد الســيارة وتســليمه ثمنهــا واســتنادا ملــا قــرره الفقهــاء‬\n     ‫رحمهــم اهلل يف مضانــه ومنهــم مــا ذكــره صاحــب املقنــع يف اجلــزء الثاني‬\n     ‫صحيفــة (‪ )44‬مــا نصــه فمــن اشــترى معيبــا لــم يعلــم عيبــه فلــه اخليــار بــن‬\n     ‫الــرد واإلمســاك وذكــر ابــن قدامــة يف املغنــي اجلــزء الســادس صحيفــة‬\n     ‫(‪ )522‬مــا نصــه «أنــه متــى علــم باملبيــع عيبــا لــم يكــن عاملــا بــه فلــه‬\n     ‫اخليــار بــن اإلمســاك والفســخ ســواء كان البائــع علــم بالعيــب وكتمــه‬\n     ‫أو لــم يعلــم ال نعلــم بــن أهــل العلــم خالفــا وإثبــات النبــي صلــى اهلل عليــه‬\n\n\n‫‪85‬‬\n\f‫وســلم للتصريــة تنبيــه علــى ثبوتــه بالعيــب وألن مطلــق العقــد يقتضــي‬\n‫الســامة مــن العيــب بدليــل مــا روي عــن النبــي صلــى اهلل عليــه وســلم‬\n‫أنــه اشــترى مملــوكا فكتــب (هــذا مــا اشــترى محمــد بــن عبــداهلل مــن‬\n‫العــداء بــن خالــد اشــترى منــه عبــدا أو أمــة الداء بــه وال غائلــة بيــع املســلم‬\n‫املســلم) فثبــت أن بيــع املســلم اقتضــى الســامة وألن األصــل الســامة‬\n‫والعيــب حــادث أو مخالــف للظاهــر فعنــد اإلطــاق يحمــل عليهــا فمتــى‬\n‫فاتــت فــات بعــض مقتضــى العقــد فلــم يلزمــه أخــذه بالعــوض وكان‬\n‫لــه الــرد وأخــذ الثمــن كامــا وذكــر الزحيلــي يف الفقــه اإلســامي‬\n‫وأدلتــه اجلــزء الرابــع صحيفــة (‪ )261‬مــا نصــه «يثبــت خيــار العيــب متــى‬\n‫ظهــر العيــب ولــو بعــد العقــد بزمــن طويــل ويقــول أيضــا «وإذا لــم تتوافــر‬\n‫الســامة لــم يتحقــق أيض ـ ًا مبــدأ التعــادل يف التبــادل الــذي تقــوم عليــه‬\n‫عقــود املعاوضــات فشــرع هــذا اخليــار حفاظــا علــى مبــدأ املســاواة وقــد‬\n‫أثبــت الشــرع هــذا اخليــار ملــن فوجــئ بالعيــب بأحاديــث نبويــة متعــددة‬\n‫منهــا (املســلم أخــو املســلم) (ال يحــل ملســلم بــاع مــن أخيــه بيعـ ًا وفيــه عيــب‬\n‫إال بينــه) وقولــه‪( :‬مــن غشــنا فليــس منــا) وقــال أيضــا «وممــا يثبــت فيــه‬\n‫اخليــار مــا كان محــل العقــد عينــا معينــة أو مشــخصة مــن األعيــان كمــا‬\n‫األرض والــدار والدابــة والســيارة ‪. « ....‬ملــا ســبق كلــه فقــد فســخت‬\n‫عقــد بيــع الســيارة املذكــورة وأن علــى شــركة مــوكل املدعــى عليــه‬\n‫إعــادة كامــل ثمــن الســيارة املذكــورة وقــدره مائــة وســتة وأربعــون ألــف‬\n‫ريــال وبــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫وكالــة عــدم القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة فأجبــت‬\n‫لطلبــه وســيتم تزويــده بنســخه مــن احلكــم وبــاهلل التوفيــق وصلــى اهلل‬\n                         ‫وســلم علــى نبيينــا محمــد حــرر يف ‪1433/10/25‬ه ـ‬\n\n\n                                                                                            ‫‪86‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n     ‫يــوم الثالثــاء ‪1434/5/21‬ه ـ افتتحــت اجللســة وقــد وردتنــا املعاملــة‬\n     ‫مــن محكمــة االســتئناف بالقصيــم رفــق خطــاب فضيلــة رئيســها‬\n     ‫رقــم ‪ 332205449‬يف ‪1434/1/24‬ه ـ واملقيــدة برقــم ‪ 34232737‬يف‬\n     ‫‪1434/1/27‬ه ـ مالحظـ ًا علــى احلكــم الصــادر منــي برقــم ‪33439017‬‬\n     ‫يف ‪1433/10/25‬ه ـ مبوجــب القــرار رقم ‪ 3414819‬يف ‪1434/1/18‬هـ‬\n     ‫املتضمــن أنــه «وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة لوحــظ مــا يلــي أوال‪ :‬أن تقريــر اللجنــة املشــكلة مــن‬\n     ‫قســم التقنيــة امليكانيكيــة بكليــة التنقيــة مبحافظــة عنيــزة الــذي‬\n     ‫اســتند عليــه فضيلــة القاضــي يف حكمــه لــم يذكــر فيــه أن العيــب‬\n     ‫املوجــود بالســيارة مصنعــي وال بــد مــن التصريــح بذلــك إضافــة إلــى أن‬\n     ‫هــذا التقريــر لــم يوقــع مــن أعضــاء اللجنــة التــي قامت بإعــداده وال بد من‬\n     ‫ذلــك ثاني ـاً‪ :‬لــم يســأل فضيلتــه ويناقــش املدعــي متــى اكتشــف العيــب‬\n     ‫الــذي يدعيــه بالســيارة وســؤال املدعــى عليــه وكالة عما ذكــره املدعي‬\n     ‫مــن متابعتــه الصيانــة للســيارة لــدى الشــركة وتدويــن ذلــك يف الضبــط‬\n     ‫والصــك ثالثـاً‪ :‬صــورة وكالــة املدعــى عليــه لــم توثــق مبطابقتهــا ألصلهــا‬\n     ‫رابعـاً‪ :‬حكــم فضيلتــه بفســخ عقــد الســيارة علــى أن الفســخ يكــون مــن‬\n     ‫املدعــي طالــب الــرد حســب مــا ذكــره العلمــاء وكان علــى فضيلتــه أن‬\n     ‫يعــرض ذلــك علــى املدعــي ثــم يحكــم بثبــوت الفســخ متــى ظهــر موجبــه‬\n     ‫« وعليــه أجيــب أصحــاب الفضيلــة بأنــه جــرت منــا الكتابــة إلــى الكليــة‬\n     ‫التقنيــة مبحافظــة عنيــزة بخطابنــا رقــم ‪ 34/316829‬يف ‪1434/2/6‬هـ ـ‬\n     ‫فوردنــا خطابهــم رقــم ‪ 97‬يف ‪1434/3/10‬هـ ـ املتضمــن ســعادة رئيــس‬\n     ‫احملكمــة العامــة ببريــدة املســاعد حفظــه اهلل الســام عليكــم ورحمــة‬\n\n\n‫‪87‬‬\n\f‫اهلل وبركاتــه حتيــة طيبــة وبعــد رد ًا علــى خطابكــم رقــم ‪34/316829‬‬\n‫وتاريــخ ‪1434/2/6‬ه ـ والــذي تطلبــون فيــه اإلفــادة عــن ســيارة املواطــن‬\n‫(‪ )........‬نفيدكــم أن قســم التقنيــة امليكانيكيــة بالكليــة أفــاد بأنــه‬\n‫ا مــن شــركة (‪ )........‬للســيارات وقــد تبــن مــن‬    ‫طلــب تقريــر ًا مفص ـ ً‬\n‫التقريــر أنــه مت فــك احملــرك مبراحــل متقدمــة مــن عمــر احملــرك لظهــور‬\n‫صــوت باحملــرك ومت تبديــل صمامــات رأس احملــرك وعليــة فــإن هنــاك‬\n‫عيــب باحملــرك كمــا هــو مرفــق ‪ .‬وتقبلــوا ســعادتكم خالــص التحيــة‬\n‫والتقديــر واهلل يحفظكــم عميــد الكليــة التقنيــة مبحافظــة عنيــزة‬\n‫(‪ )........‬وتوقيعــه وأمــا املالحظــة الثانيــة ‪ :‬فإنــه جــرى ســؤال املدعــي متــى‬\n‫اكتشــف العيــب الــذي يدعيــه فقــال إننــي اكتشــفته مــن يــوم وصــل‬\n‫عــداد الســيارة عشــرين ألــف كيلومتــر حيــث حضــرت إلــى الشــركة‬\n‫يف مقرهــا يف محافظــة عنيــزة لوجــود صــوت يف املاكينــة فخضــت أن‬\n‫تكــون املاكينــة فتــم الفحــص عليهــا ووجــود الزيــت ناقص ـ ًا فقالــوا‬\n‫راجــع الشــركة يف بريــدة وقــد راجعــت الشــركة قبــل وصــول العــداد‬\n‫خمســة وعشــرون ألــف كيلــو وذكــرت لهــم أن الزيــت ينقــص فقالــوا إن‬\n‫الزيــت ال ينقــص حيــث قامــوا بإدخــال الســيارة إلــى داخــل الصيانــة ثــم‬\n‫أفادونــي أن الزيــت ال ينقــص وفكــوا العيــار فوجــد أن الزيــت متعــدي‬\n‫الكميــة احملــددة ممــا يــدل علــى أنهــم وضعــوا الزيــت فقلــت أن الزيــت‬\n‫ينقــص فقالــوا نغيــر لــك الزيــت ونضــع شــطرطون لننظــر هــل ينقــص أم‬\n‫ال ؟ مــع أن الزيــت يهــرب مــن أســفل فتــم تغييــر الزيــت ومــازال الصوت يف‬\n‫املاكينة وبعد أن مشــيت خمســة آالف كيلو حضرت لديهم للكشــف‬\n‫ا وجــد‬   ‫عليهــا لعــل الزيــت نقــص أم ال فقامــوا بالكشــف عليهــا وفع ـ ً‬\n‫الزيــت ناقصـ ًا فقالــوا األن صحيــح الزيــت ناقــص وحتتــاج املاكينــة إلــى‬\n\n\n                                                                                        ‫‪88‬‬\n\f     ‫فــك وهــذه األشــياء املطلوبــة ومنهــا الشــنابر وهــذا معنــاه أنهــا حتتــاج إلــى‬\n     ‫توظيــب فلــم أوافــق والزالــت الســيارة عندهــم هكــذا أجــاب وبعــرض‬\n     ‫ذلــك علــى املدعــى عليــه وكالــة عمــا ذكــره املدعــي مــن متابعتــه‬\n     ‫للصيانــة لــدى الشــركة فقــال إننــي لســت فنيـ ًا وهــذا يتضــح مــن خــال‬\n     ‫الكتالــوج ووضــع اخلتــم عليــه هكــذا أجــاب وبعــرض ذلــك علــى املدعــي‬\n     ‫أجــاب إننــي متابــع معهــم وكل مــرة يذكــرون أنــه علــى الضمــان ولــو‬\n     ‫لــم يكــن علــى الضمــان ملــا اســتقبلوني هكــذا أجــاب وأمــا املالحظــة‬\n     ‫الثالثــة فإنــه جــرى إكمــال الــازم حيالهــا وأمــا املالحظــة الرابعــة فــإن‬\n     ‫املدعــي طلــب الفســخ وهــذا مــا حكمــت بــه وبعرضــه عليــه قنــع بــه ملــا‬\n     ‫ســبق كلــه الزلــت علــى مــا حكمــت بــه وقــررت إعــادة املعاملــة إلــى‬\n               ‫محكمــة االســتئناف وبــاهلل التوفيــق ‪ .‬حــرر يف ‪1434/5/21‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافق‪1434/07/09‬ه ـ افتتحــت‬\n     ‫اجللســة وقــد وردتنــي املعاملــة مــن محكمــة االســتئناف بالقصيــم رفــق‬\n     ‫خطــاب فضيلــة رئيســها رقــم ‪ 341318484‬يف ‪1434/6/26‬ه ـ واملقيــدة‬\n     ‫بهــذه احملكمــة برقــم ‪ 341318484‬يف ‪1434/6/28‬ه ـ واملرفــق بهــا‬\n     ‫قــرار الدائــرة احلقوقيــة األولــى رقــم ‪ 34241289‬يف ‪1434/6/14‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم الصــادر منــي برقــم ‪ 33439017‬يف‬\n     ‫‪1433/10/25‬ه ـ ولــذا جــرى إثباتــه والتهميــش مبوجبــه علــى الضبــط‬\n     ‫وســجل الصــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                       ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/9‬ه ـ‬\n     ‫احلمــد هلل وحــده ويف يــوم االحــد ‪1434/8/14‬ه ـ افتتحــت اجللســة وفيهــا‬\n     ‫حضــر املدعــي وقــرر انــه اســتلم املبلــغ احملكــوم بــه أعــاه وقــدره مائــة‬\n     ‫وســتة وأربعــون ألــف ريــال مــن الشــركة املدعــى عليهــا وبهــذا االقــرار‬\n\n\n‫‪89‬‬\n\f‫تعتبــر القضيــة منتهيــة وال يطالــب أحدهمــا االخــر بخصوصهــا وقــررت‬\n‫التهميــش بذلــك علــى الصــك وســجله وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n                             ‫علــى نبينــا محمــد حــرر يف ‪1434/8/14‬ه ـ ‪.‬‬\n\n\n\n\n                                                                              ‫‪90‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":81,"source_page_end":90,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4093e0492c70bd4728f2ad166f64eb43d420de29da6e878c044339a2e4d51355","normalized_text_hash":"09f28dd921b79d353ce53b6e0812aa7e0dc783c79ab5fda3fdfce1c65ba86ad9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p81-33439017"},{"id":"b5f06aeb-f438-515c-9d79-9e235d6ea298","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عيب مبيع -املطالبة برد ثمن سيارة مبيعه -إقرار الشركة املصنعة بالعيب -إنكار الشركة البائعة للعيب -االستعانة بأهل اخلبرة يف بيان العيب -القول قول املشتري يف العيب مع ميينه -عدم سقوط احلق يف إرجاع املبيع بالتراخي إال بدليل الرضا - ثبوت العيب وإمضاء خيار الفسخ للمشتري لعدم ثبوت ما يسقطه -احلكم بإعادة الثمن للمشتري والسيارة للبائع .","document_number":"34194877","case_number":"33474401","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"بيع -عيب مبيع -املطالبة برد ثمن سيارة مبيعه -إقرار الشركة املصنعة بالعيب -إنكار الشركة البائعة للعيب -االستعانة بأهل اخلبرة يف بيان العيب -القول قول املشتري يف العيب مع ميينه -عدم سقوط احلق يف إرجاع املبيع بالتراخي إال بدليل الرضا - ثبوت العيب وإمضاء خيار الفسخ للمشتري لعدم ثبوت ما يسقطه -احلكم بإعادة الثمن للمشتري والسيارة للبائع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/22 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34194877 :‬‬\n                        ‫َر ْق ُم الدعوى‪33474401 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34270712‬تاريخه‪1434/7/17 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬عيــب مبيــع ‪ -‬املطالبــة بــرد ثمــن ســيارة مبيعــه ‪ -‬إقــرار الشــركة‬\n     ‫املصنعــة بالعيــب ‪ -‬إنــكار الشــركة البائعــة للعيــب ‪ -‬االســتعانة بأهــل‬\n     ‫اخلبــرة يف بيــان العيــب ‪ -‬القــول قــول املشــتري يف العيــب مــع ميينــه‬\n     ‫‪ -‬عــدم ســقوط احلــق يف إرجــاع املبيــع بالتراخــي إال بدليــل الرضــا ‪-‬‬\n     ‫ثبــوت العيــب وإمضــاء خيــار الفســخ للمشــتري لعــدم ثبــوت مــا يســقطه‬\n                       ‫‪ -‬احلكــم بإعــادة الثمــن للمشــتري والســيارة للبائــع ‪.‬‬\n\n\n\n\n     ‫‪ .1‬قولــه تعالــى (يــا أيهــا الذيــن آمنــوا ال تأكلــوا أموالكــم بينكــم‬\n     ‫بالباطــل) ‪ ،‬قــال ابــن العربــي‪« :‬يعنــي مبــا ال يحــل شــرعا و ال يفيــد‬\n     ‫مقصــودا» أحــكام القــرآن ‪ ، 97/1‬وجــاء يف تفســير املنــار ‪ 40/5‬يف معنــى‬\n     ‫الباطــل ‪ « :‬أنــه مــا لــم يكــن يف مقابلــة شــيء حقيقــي وهــو مــن الباطــل‬\n     ‫والبطــان أي الضيــاع واخلســار ‪ ،‬فقــد حرمــت الشــريعة أخــذ املــال‬\n                        ‫بــدون مقابلــة حقيقيــة يعتــد بهــا ممــن يؤخــذ منــه»‪.‬‬\n     ‫‪ .2‬حديــث أبــي هريــرة رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وآلــه‬\n     ‫وســلم قــال‪« :‬كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه» رواه‬\n                                                                             ‫مســلم‪.‬‬\n     ‫‪ .3‬قــال ابــن تيميــة رحمــه اهلل‪« :‬إن كل مــا يوجــد باملبيــع ممــا ينقــص‬\n     ‫العــن أو القيمــة نقصــا يفــوت بــه غــرض صحيــح يثبــت بــه الــرد»‬\n                                                    ‫حاشــية ابــن قاســم ‪. 442/4‬‬\n‫‪91‬‬\n\f‫‪ .4‬قــال الشــيرازي ‪-‬رحمــه اهلل‪ -‬يف املهــذب) ‪« :)286/1‬والعيــب الــذي يــرد‬\n‫بــه املبيــع ممــا يعــده النــاس عيبــا فــإن خفــي منــه شــيء رجــع فيــه إلــى‬\n                                             ‫أهــل اخلبــرة بذلــك اجلنــس» ‪.‬‬\n‫‪ .5‬قــال املــرداوي يف اإلنصــاف‪« :‬العيــب هــو مــا ينقــص قيمــة املبيــع‬\n                 ‫نقيصــة يقتضــي العــرف ســامة املبيــع عنهــا غالبــا»‪.‬‬\n‫‪ .6‬مــا قــرره الفقهــاء مــن أن خيــار العيــب يثبــت بــا اشــتراط قــال ابــن‬\n         ‫عابديــن يف حاشــيته ‪« : 3/5‬خيــار العيــب يثبــت بــا اشــتراط» ‪.‬‬\n‫‪ .7‬مــا قــرره الفقهــاء مــن أن خيــار العيــب علــى التراخــي قــال البهوتــي‬\n‫يف شــرح منتهــى اإلرادات ‪« :211/3‬وخيــار عيــب متــراخ ألنــه لدفــع ضــرر‬\n‫متحقــق فــا يســقط بالتأخيــر كالقصــاص ‪ ،‬إال إن وجــد دليــل رضــاه‬\n                                                                 ‫أي املشــتري»‪.‬‬\n‫‪ .8‬مــا قــرره الفقهــاء مــن أنــه إذا اختلــف البائــع واملشــتري يف عيــب املبيع‬\n‫مــع االحتمــال فالقــول قــول املشــتري بيمينــه قــال البهوتــي رحمــه اهلل‪:‬‬\n‫«وإن اختلفــا أي البائــع واملشــتري يف معيــب عنــد مــن حــدث العيــب مــع‬\n‫االحتمــال فقــول مشــتر بيمينــه إن لــم يخــرج عــن يــده» الــروض املربــع‬\n                                                                        ‫‪.454 /4‬‬\n\n\n\n\n‫أقــام املدعــي علــى الشــركة املدعــى عليهــا دعــوى فســخ عقــد بيع ســيارة‬\n‫واســترداد ثمنهــا لوجــود عيــوب خفيــه بهــا تؤثــر علــى ســامتها وأنه راجع‬\n‫الشــركة أكثــر مــن مــرة لإلصــاح دون أن يتــم اإلصــاح علــى الوجــه‬\n‫الصحيــح ودفعــت الشــركة املدعــى عليهــا بعــدم صحــة ذلــك فجــرى‬\n‫اســتطالع رأي أهــل اخلبــرة والــذي أكــد وجــود بعــض العيــوب بســبب‬\n\n                                                                                      ‫‪92‬‬\n\f     ‫ســوء الصناعــة وعيــوب أخــرى ال ميكــن اجلــزم كونهــا ســوء صناعــة‬\n     ‫أم عيــوب اســتخدام وكمــا أقــر فنــي الشــركة املصنعــة بوجــود بعــض‬\n     ‫عيــوب بالســيارة ونظــر ًا ألن القاعــدة اذا اختلــف البائــع واملشــتري يف‬\n     ‫عيــب املبيــع مــع االحتمــال فالقــول قــول املشــتري بيمينــه لذلــك حكــم‬\n     ‫القاضــي بفســخ عقــد البيــع وإعــادة ثمــن الســيارة للبائــع وإعــادة ملكيــة‬\n     ‫الســيارة للشــركة البائعــة ولــم ترتــض املدعــى عليهــا احلكــم وجــرى‬\n                                            ‫تصديقــه مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬املــازم القضائــي لــدى فضيلــة‬\n     ‫الشــيخ د‪ )......( .‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى‬\n     ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامة بالريــاض (‪)......‬‬\n     ‫املســاعد برقــم ‪ 33474401‬وتاريــخ ‪1433/07/19‬هـ املقيدة باحملكمة‬\n     ‫برقــم ‪ 331356537‬وتاريــخ ‪1433/07/19‬ه ـ ففــي يــوم االثنــن املوافــق‬\n     ‫‪1433/8/11‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي(‪ )......‬ولم يحضر‬\n     ‫ممثــل الشــركة املدعــى عليهــا وقــد أبــرز املدعــي تبليــغ املديــر االداري‬\n     ‫باملنطقــة الوســطى ‪ .............‬باجللســة املاضيــة كمــا أبــرز خطــاب مديــر‬\n     ‫مركــز شــرطة النســيم برقــم بــدون وتاريــخ ‪1433/8/7‬ه ـ املتضمــن انــه‬\n     ‫مت ابــاغ املديــر اإلداري للشــركة حســب نســخة التبليــغ املرفقــة ا ه ـ‬\n     ‫ا‪:‬‬ ‫وعليــه فقــد أذنــت بســماع دعــوى املدعــي غيابيـ ًا فادعــى املدعــي قائـ ً‬\n     ‫يف اخــر شــعبان مــن عــام ‪1431‬ه ـ اشــتريت مــن شــركة ‪ .........‬ســيارة‪...‬‬\n     ‫ذات اللوحــة ‪ ..........‬صنــع عــام ‪2011‬م مببلــغ وقــدره مائتــان وعشــرون‬\n     ‫ألف ريال ‪ ،‬وبعد اســتالمي للســيارة اكتشــفت بها عدة عيوب مصنعية‬\n\n‫‪93‬‬\n\f‫منهــا أوال أن الســيارة تتوقــف فجــأة وهــي تســير ممــا يســبب خطــر ًا علــي‬\n‫وعلــى ابنائــي حيــث اخشــى ان تتوقــف الســيارة وانــا اســير بهــا ممــا يعنــي‬\n‫عــدم متكننــي مــن التحكــم بهــا يف الطريــق ثاني ًا اكتشــفت ان الفرامل‬\n‫ال تعمــل وعندمــا اخبرتهــم بذلــك قالــوا ان يف الفرامــل عيب ـ ًا مصنعي ـ ًا‬\n‫وســتأتينا قطــع غيارهــا بعــد عــدة اشــهر مــن املانيــا ثالث ـ ًا اكتشــفت ان‬\n‫كمبيوتــر الســيارة ال يظهــر االخطــاء واملشــاكل املوجــودة يف الســيارة‬\n‫كضغــط هــواء الكفــرات وغيــره رابع ـ ًا اكتشــفت ان اجلنــوط ســيئة‬\n‫حيــث انهــا انكســرت وقامــوا بتغييرهــا عــدة مــرات ‪ ،‬كمــا انهــم‬\n‫اصلحــوا الســيارة خــارج الوكالــة وهــذا االمــر يفقدنــي ضمــان الســيارة‬\n‫فيمــا بعــد ‪ ،‬ولــم ارض بهــذه العيــوب ابــد ًا وكنــت كثيــر التــردد علــى‬\n‫الشــركة إلصــاح الســيارة وهــي موجــودة عندهــم االن ألنــي وضعتهــا‬\n‫عندهــم ورفضــت اســتالمها ‪ ،‬اطلــب فســخ البيــع واعــادة كامــل الثمــن‬\n‫الــذي ســلمته لهــم وقــدره مئتــان وعشــرون الــف ريــال هــذه دعــواي لــذا‬\n‫فقــد قــررت الكتابــة لهيئــة النظــر لتقريــر هــل هــذه العيــوب عيــوب‬\n‫مصنعيــة ام ال ورفعــت اجللســة حلــن ورود اجلــواب ويف جلســة أخــرى‬\n‫حضــر املدعــي كمــا حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ..........‬بالوكالــة ‪ ............‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ............‬بوكالتــه عــن‪ ............‬بصفتــه صاحــب مؤسســة‬\n‫‪ ..............‬للســيارات مبوجــب الســجل التجــاري رقــم ………‪ ..‬يف‬\n‫‪1409/9/11‬ه ـ مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫يف شــمال محافظــة جــدة برقــم ‪ 43793‬يف ‪1433/5/15‬ه ـ املخــول فيهــا‬\n‫حضــور اجللســات واملدافعــة واملرافعــة وقــد وردنــا وقــد وردنــا كتــاب‬\n‫مديــر قســم اخلبــراء برقــم ‪ 331509883‬يف ‪1433/8/28‬ه ـ املتضمــن‬\n\n\n                                                                                      ‫‪94‬‬\n\f     ‫أنــه مت االســتعانة برئيــس مهنــة صناعيــة الريــاض القدميــة ‪ .......‬وتعــذر‬\n     ‫بقولــه ال ميكــن الكشــف عــن األعطــال حيــث مت االصــاح بــدون‬\n     ‫الوقــوف علــى الســيارة والكشــف عليهــا وبذلــك تعــذر أعضــاء الهيئــة‬\n                                                             ‫عــن كتابــة القــرار اه ـ ‪.‬‬\n     ‫وعليــه فقــد قــررت الكتابــة لــوزارة التجــارة لتقريــر هــل هــذه العيــوب‬\n     ‫عيــوب مصنعيــة ام ال ورفعــت اجللســة حلــن ورود اجلــواب ويف جلســة‬\n     ‫أخــرى حضــر املدعــي ‪ ............‬املــدون هويتــه ســلفا كمــا حضــر املدعــى‬\n     ‫عليــه وكالــة ‪ ...........‬املــدون رقــم هويتــه ووكالتــه ســلفا وقــد وردنــا‬\n     ‫خطــاب وكيــل وزارة التجــارة لشــؤون املســتهلك املكلــف ‪ .........‬برقــم‬\n         ‫‪/8166/9/5/267‬غ وتاريــخ ‪1433/10/08‬ه ـ واملتضمــن مانصــه‪:‬‬\n     ‫‪ -1‬عــدم عمــل آلــة التنبيــه ووجــود بقعــة زيــت علــى الســيارة قبل االســتالم‬\n                            ‫وأنــه قــد مت تلميــع الســيارة وإعــادة ضبــط آلــة التنبيه ‪.‬‬\n     ‫‪ -2‬توقــف الســيارة عــن احلركــة وانطفائهــا فجــأة وهبــوط يف الضغــط‬\n     ‫املكينــة ‪ ،‬أفــاد املشــرف علــى الصيانــة الســيد ‪ ...‬عــن ذلــك أفــاد بــان‬\n     ‫الســيارة املذكــورة قــد ســبق انطفــأت وهــو يقودهــا داخــل الورشــة ‪،‬‬\n     ‫وأفــادت الشــركة أنهــا قامــت بعمــل ســمكرة للســيارة مرتــن بســبب‬\n     ‫حــوادث مروريــة لكــن املدعــي أفــاد أنهــا حصلــت بســبب توقــف الســيارة‬\n                                    ‫املفاجــئ بالطريــق بســبب تعطــل الكمبيوتــر‪.‬‬\n     ‫‪ -3‬حســب التقريــر الفنــي الــوارد مــن الشــركة األم وحســب إفــادة‬\n     ‫الوكيــل (‪ )..........‬وجــود فشــل يف الكمبيوتــر امللحــق بالســيارة يف‬\n     ‫إظهــار التحذيــرات وفشــل الذاكــرة يف قــراءة األخطــاء حيــث لــم يتــم‬\n     ‫تســجيل أي نــوع مــن األعطــال عــن مراجعــة وحــدات التحكــم وذاكــرة‬\n           ‫احلاســب اآللــي بالســيارة وخلــل يف نظــام الكهروميكانيكــي ‪.‬‬\n\n\n‫‪95‬‬\n\f‫‪-4‬وجــود قطــع يف احــد اإلطــارات وكســر يف اجلنــوط األربعــة أفــادت‬\n‫الشــركة بــأن اجلنــوط والكفــرات قــد تعرضــت لصدمــات يف الطريــق‬\n‫أدت إلــى تلــف اجلنــوط وأنــه قــد مت تغييــر اجلنــوط األربعــة وكذلــك‬\n‫الكفــر املقطــوع مجانــا مــن قبــل شــركة ‪ .............‬للســيارات بينمــا‬\n‫يصــر املدعــي أنهــا بســبب ســوء التصنيــع وهنــا ال ميكــن االخــذ بــرأي‬\n‫الشــركة إذا ال يوجــد حــادث أو مشــاكل طريــق تــؤدي إلــى تلــف‬\n‫االربعــة جنــوط مــرة واحــدة وأن الشــركة أوضحــت أنهــا تأخــرت بتبديــل‬\n‫اجلنــوط بســبب أن اجلنــوط اجلديــدة التــي وصلــت لهــم مــن جــدة كانــت‬\n                        ‫غيــر صاحلــة لالســتعمال وهــذا يعنــي عيــب مصنعــي‬\n‫‪ -5‬قيــام الشــركة بإصــاح الســيارة خــارج الوكالــة يف ورشــة ‪.............‬‬\n‫لضبــط الزوايــا علــى نفقــة وحســاب الشــركة ‪ .............‬وهــذا مثبــت‬\n‫مبوجــب إفــادة الشــركة وبســؤال الشــركة عــن قيامهــم باســتدعاء‬\n‫الســيارة املعيبــة ماركــة ‪....‬موديــل ‪ 2011‬م أفــادو عــن قيامهــم بإجــراء‬\n‫االســتدعاء لســيارات بحســب رقــم الهيــكل الــوارد لهــم عــن طريــق‬\n‫الشــركة األم وال يشــملها رقــم هيــكل هــذه الســيارة وعليــه وبعــد‬\n‫الوقــوف علــى الســيارة وجــد أن جميــع ما ذكــره املدعي صحيح مع عدم‬\n‫إمكانيــة احلكــم بــأن العيــوب التــي ذكرهــا املدعــي عيــوب مصنعيــة‬\n‫ماعــدا اجلنــوط بهــا عيــوب مصنعيــه أو عيــوب جــراء االســتخدام كمــا‬\n‫تدعــي الشــركة مــع مالحظــة أن الســيارة حتــت فتــرة الضمــان وهــي‬\n‫ثــاث ســنوات أ ‪ .‬ه ـ وبعــرض القــرار علــى الطرفــن قــرر املدعــي قناعــة‬\n‫مبــا جــاء فيــه وبعــرض القــرار علــى املدعــى عليــه وكالــة طلــب املهلــة‬\n‫يف الــرد عليــه وعليــه جــرى رفــع اجللســة ويف جلســة أخــرى لــدي أنــا‪........‬‬\n‫املــازم القضائــي ‪ .......‬القاضــي يف احملكمــة العامــة بالريــاض حضــر‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫املدعــي ‪ .............‬املــدون هويتــه ســلفا كمــا حضــر املدعــى عليــه وكالــة‬\n     ‫‪ ............‬املــدون رقــم هويتــه ووكالتــه ســلفا وبعــرض مــا مت ضبطــه علــى‬\n     ‫الطرفــن بنــاء علــى املــادة ‪ 166‬مــن نظــام املرافعــات قــررا املصادقــة‬\n     ‫عليــه وبطلــب مــا اســتمهل ألجلــه املدعــى عليــه أبــرز مذكرتــه اجلوابيــة‬\n     ‫املكونــة مــن ورقــة واحــدة واملؤرخة يف ‪1434/3/17‬ه ـ وباالطالع عليها‬\n     ‫وجــد مــا نصــه‪ :‬اشــارة الــى خطــاب وزارة التجارة رقــم ‪8166/9/5/267‬‬\n     ‫بتاريــخ ‪1433/10/08‬ه ـ واملكــون مــن خمســة نقــاط لذلــك ســوف نبــن‬\n                                                        ‫مــا ذكــر علــى النحــو اآلتــي‪:‬‬\n     ‫أوالً‪ :‬وجــود بقــع زيــت علــى الســيارة وعــدم عمــل آلــة التنبيــه قبــل‬\n     ‫االســتالم يرجــى العلــم بــان إجــراء فحــص مــا قبــل التســليم هــو عمــل‬\n     ‫اساســي وضــروري جلميــع الســيارات الــواردة مــن املصنــع واســتناد ًا لذلــك‬\n     ‫الفحــص يتــم ضبــط منســوب جميــع الســوائل بالســيارة والكشــف علــى‬\n     ‫ضغــط هــواء اإلطــارات وكذلــك عمــل آلــة التنبيــه وجميــع األجهــزة‬\n     ‫املســاعدة وإزالــة جميــع الشــحومات التــي متواجــدة علــى جســم الســيارة‬\n     ‫واملقصــود بــه حفــظ اجلســم اخلارجــي للســيارة لعوامــل الشــحن وخالفــة‬\n     ‫ثانيــا ‪ :‬انطفــاء الســيارة فجــأة وهبــط ضغــط املاكينــة ‪ ..‬يرجــى العلــم‬\n     ‫واإلحاطــة بــأن الســيارة لــم تتوقــف أثنــاء الســير مــع وجــود مهنــدس‬\n     ‫الورشــة ولكــن قبــل البــدء بالــدوران أمــر طبيعــي نتيجــة عــدم تشــغيل‬\n     ‫الســيارة ملــد طويلــة وليــس لــه عالقــة بحــوادث الــواردة علــى اإلطــاق‪.‬‬\n     ‫حيــث الســيارة تعمــل بطريقــة تلقائيــة ال تعتمــد علــى البطاريــة امنــا علــى‬\n     ‫الدينامــو الــذي يقــوم بشــحن البطاريــة وامــداد جميــع وحــدات التحكــم‬\n                    ‫بالكهربــاء املطلوبــة علمــا أن الســيارة حتــت فتــرة الضمــان‬\n     ‫ثالثــا‪ :‬يرجــى العلــم بــأن جميــع أجهــزة الفحــص (الكمبيوتــر بالســيارة)‬\n\n\n‫‪97‬‬\n\f‫تعمــل بشــكل طبيعــي يف جميــع الظــروف وال يوجــد بهــا أي خلــل‬\n‫يذكــر وتقــوم بقيــاس جميــع األعطــال إن وجــدت ‪،‬وعــدم تســجيل أي‬\n‫أخطــاء هــو الدليــل بــأن جميــع مكونــات الســيارة تعمــل يشــكل جيــد‪.‬‬\n‫وان التقريــر املرفــق ضمــن أوراق القضيــة و املقــدم مــن املدعــي لــوزارة‬\n‫التجــارة واملوجــود منــه صــورة يف ملــف القضيــة ليــس مــن الشــركة األم‬\n‫أو الوكيــل ( ‪ .) ..................‬كمــا يرجــى العلــم بــان هــذا التقريــر يتــم‬\n‫طباعتــه عــن طريــق أجهــزة الكمبيوتــر خاصــة بالورشــة بعــد توصيلهــا‬\n‫بأجهــزة الصيانــة وذلــك ضمــن إجــراءات البرمجــة املصنعيــة التــي تتــم‬\n‫بصفــة يوميــه جلميــع ســيارات ‪...‬كمــا يرجــى العلــم بــان لفــظ كلمــة‬\n‫(‪ wronging‬يفيــد حتذيــر وليــس فشــل) واملذكــور إمامــه عبــارة‬\n‫عمليــة بــدء التشــغيل الكهربائــي مــن املقــود الكهربائــي وكذلــك‬\n‫كلمــة التحذيــر املذكــور إمــام قــراءة الكــود املخزنــة بالذاكــرة‬\n‫وهــذه ال يفيــد عطــل بتلــك األجــزاء املذكــورة وإمنــا تنبيــه للفنــي والــذي‬\n‫يعمــل علــى الســيارة ويجــري عمليــة برمجــة لألجــزاء التــي يتوجــب عليــه‬\n‫عملــة بعــد االنتهــاء مــن كل عمليــة برمجــة للتأكيــد بــان هــذه الوحدات‬\n‫تعمــل تلقائــي مــع العميــل بعــد خــروج الســيارة مــن الورشــة لذلــك إن تلــك‬\n‫التقاريــر املطبوعــة يتــم طبعــا بصفــة أوامــر للفنيــن بإجــراء الفحوصــات‬\n‫التــي يجــب االنتهــاء منــه قبــل خــروج الســيارة وهــي ليســت حتذيــرات‬\n‫للعميــل أو أي شــخص آخــر‪ ،‬ومبراجعــة الصفحــة التاليــة لهــذا التقريــر‬\n‫جتــدو أيضــا أن التقاريــر تطالــب العامــل الفنــي بالتأكيــد يف النظــر إلــى‬\n‫كل مــا هــو مكتــوب عليهــا لتحذيــر مبــا فيهــا العبارتــن الســابقتني‪.‬‬\n‫وللتأكيــد ممــا ســبق ذكــره فــأن ليــس لدينــا مانــع مــن اطــاع‬\n‫فضيلتكــم علــى تقاريــر مماثلــه الســيارات أخــرى أو جميــع الســيارات‬\n\n\n                                                                                       ‫‪98‬‬\n\f     ‫التــي بداخــل الورشــة مــع عمــل شــرح مفصــل للتقاريــر الصــادرة مــن‬\n     ‫أجهــزة التحكــم يف الســيارة وطبيعــة عمــل الفنيــن يف التعامــل معهــا‪.‬‬\n     ‫رابعــا‪ :‬يرجــى العلــم واالحاطــة بــأن جميــع جنــوط ‪ ...‬واملســتوردة عــن‬\n     ‫طريــق شــركة االم مت فحصهــا باملختبــرات والتــي مت حتديهــا مــن وزارة‬\n     ‫التجــارة والتــي تفيــد بــان جميــع جنــوط ســيارات ‪ ...‬قــد اجتــازت جميــع‬\n     ‫االختبــارات األزمــة لتتحمــل الصدمــات الطبيعيــة للطــرق ومــع ذلــك مت‬\n     ‫تغيرهــا للعميــل بصفــة مجانيــة كنــوع مــن اخلدمــة اإلضافيــة تقديــرا‬\n     ‫لعمــاء ‪ ) ...‬مرفــق صــورة مــن نتيجــة االختبــارات والتــي تثبــت مــا ســبق‬\n                                                                                 ‫ذكــره‪.‬‬\n     ‫خامســا‪ :‬إلصــاح وضبــط الزوايــا مت تغييــر الــذراع األمامــي األميــن علمــا‬\n     ‫بــأن ضبــط الزوايــا يتــم يف ورشــة ‪ ...........‬بإشــراف مــن مؤسســة ‪..........‬‬\n     ‫للســيارات وأيضــا بصفــة مجانيــة مــن مؤسســة ‪................‬للســيارات‪.‬‬\n     ‫ومت فحــص الســيارة علــى الطريــق والتأكــد مــن صحــة إصــاح الزوايــا‬\n     ‫ومطابقتــه املوصفــات الفنيــة املطلوبــة مــن شــركة ‪ ...‬العامليــة‪ .‬علمــا أنــه‬\n     ‫أثناء وجود ســيارة العميل بالورشــة مت تســليمه ســيارة بديلة من املؤسســة‬\n     ‫وقــد مت إرجاعهــا مــن قبــل العميــل بعــد االنتهــاء مــن إصــاح ســيارته ولــم‬\n     ‫يقــوم العميــل باســتالم ســيارته علمــا بأنهــا جاهــزة لالســتالم‪ .‬هــذا مــا‬\n     ‫أردنــا توضيحــه لفضيلتكــم ‪ ،‬ونحــن علــى اســتعداد لإلجابــة عــن أي‬\n     ‫استفســارات قــد تطلبونهــا الحقــا‪ ».‬وبســؤال املدعــي قــال لــدي بينــات‬\n     ‫أخــرى وأريــد إحضارهــا يف اجللســة القادمــة ‪ ،‬عليــه رفعــت اجللســة ويف‬\n     ‫جلســة أخــرى حضــر املدعــي ‪ ..............‬املــدون هويتــه ســلفا كمــا حضــر‬\n     ‫املدعــى عليــه وكالــة ‪ ...................‬املــدون رقــم هويتــه ووكالتــه ســلفا‬\n     ‫‪ ،‬وبطلــب مــا اســتمهل ألجلــه املدعــي أبــرز مذكرتــه اجلوابيــة املؤرخــة‬\n\n\n‫‪99‬‬\n\f‫‪1434/4/15‬ه ـ وباالطــاع عليهــا وجــد مــا نصــه ‪ »:‬فإنــه وإشــارة‬\n‫إلــى املوضــوع أعالهــا وإلــى مذكــرة وكيــل املدعــى عليــه املقدمــة‬\n‫لفضيلتكــم واملؤرخــة بتاريــخ ‪1434/3/1‬ه ـ والتــي جــاءت مــن املدعــى‬\n‫عليــه رد ًا علــى التقريــر الفنــي املوضــح بخطــاب وزيــر التجــارة فإننــي‬\n‫أتقــدم ملقــام فضيلتكــم بالتعقيــب علــى مــا ذكــره وكيــل املدعــى عليــه‬\n                                                                        ‫مبــا يلــي ‪:‬‬\n‫اوالً‪ :‬فلقــد ورد يف اخلطــاب املقــدم رد ًا علــى خطــاب فضيلتكــم مــن‬\n‫قبــل وزارة التجــارة والصناعــة وكالــة الــوزارة لشــئون املســتهلك ويف‬\n‫مقدمــة اخلطــاب أن املدعــى عليــه قــد أقــر بالعيــوب التــي ســببها رفــع‬\n‫هــذه الدعــوى وذلــك مبــا نصــه ‪( :‬وبحضــور كل مــن املواطــن ‪.............‬‬\n‫والســيد ‪ ...............‬مديــر إقليمــي بشركة‪........‬والســيد ‪ .............‬مديــر‬\n‫الصيانــة بشــركة ‪ ............‬ومبراجعــة العيــوب التــي تقــدم بهــا املدعــي‬\n‫والتــي أقــرت الشــركة بهــا ) انتهــى ‪ 0‬إذ ًا فــإن املدعــى عليــه قــد اقــر‬\n‫بالعيــب يف املبــاع حســب تقريــر وكالــة الــوزارة لشــئون املســتهلك‬\n‫بــوزارة التجــارة والصناعــة وحيــث إنــه مــن املقــرر شــرع ًا ونظام ـ ًا بــان‬\n‫خيــار العيــب يثبــت دون احلاجــة إلــى اشــتراطه صراحــة وكــذا الســامة‬\n‫وذلــك مــن مقتضيــات العقــد ألنــه مــن عقــود املعاوضــات والتــي تبنــي‬\n‫علــى املســاواة حقيقــة وعــادة ‪ ،‬وبالرجــوع إلــى ضمــن مــا جــاء بتقريــر‬\n‫خطــاب وزارة التجــارة آنــف الذكــر فلقــد جــاء يف البنــد الثالــث منــه مــا‬\n‫نصــه ‪( :‬حســب التقريــر الفنــي الــوارد مــن الشــركة األم وحســب إفــادة‬\n‫الوكيــل ( ‪ ) ...‬وجــود فشــل يف الكمبيوتــر امللحــق بالســيارة يف إظهــار‬\n‫التحذيــرات وفشــل الذاكــرة يف قــراءة األخطــاء حيــث لــم يتــم تســجيل‬\n‫أي نــوع مــن األعطــال عــن مراجعــة وحــدات التحكــم وذاكــرة احلاســب‬\n\n\n                                                                                        ‫‪100‬‬\n\f      ‫اآللــي بالســيارة وخلــل يف النظــام الكهروميكانيكــي) انتهــى ‪ 0‬ممــا‬\n      ‫يشــير إلــى وجــود عيــوب يف الســيارة موضــوع الدعــوى ومنــه فشــل يف آلــة‬\n      ‫التنبيــه وعــدم عملهــا قبــل االســتالم وعيــب يف الكمبيوتــر وهــذا مقــرا‬\n      ‫بــه مــن قبــل املدعــى عليــه ممــا يؤكــد إنــه عيــب خفــي لــم يظهــر قبــل‬\n      ‫االســتعمال ولــم اعلــم بــه أنــا املشــتري ممــا يتعــن معــه فســخ عقــد البيــع‬\n      ‫واســترداد مــا دفعتــه مــن ثمــن أخــذه املدعــى عليــه وأن تســتلم الوكالــة‬\n      ‫( املدعــى عليــه ) ســيارتها وأن نصــار إلــى احلالــة التــي كنــا عليــه اقبــل‬\n      ‫التعاقــد ‪ ،‬حيــث إننــي مشــترى هــذه الســيارة بغــرض إنهــا ســليمة مــن‬\n      ‫العيــوب علم ـ ًا بــان هــذا العيــب اخلفــي مؤثــر ًا يف املبيــع ومــن شــأنه أن‬\n      ‫يجعــل البيــع غيــر صالــح للغــرض الــذي اعــد لــه حيــث أن هــذه العيــوب‬\n      ‫جميعهــا كانــت موجــودة وقــت البيــع وهــي عيــوب تنقــص مــن قيمــة‬\n      ‫املبــاع ومــن نفعــه وإننــي لــم أكــن أعلمهــا ولــو كنــت أعلمهــا ملــا أقدمــت‬\n                                                                    ‫علــى شــراء املبــاع ‪.‬‬\n      ‫ثاني ـ ًا ‪ :‬مــا يريــد إن ينفيــه وكيــل املدعــى عليــه يف البنــد الثانــي مــن‬\n      ‫مذكرتــه مبــا نصــه ‪ .... ( :‬يرجــى العلــم واإلحاطــة بــأن الســيارة لــم‬\n      ‫تتوقــف أثنــاء الســير مــع وجــود مهنــدس الورشــة ) انتهــى ‪ ،‬هــذا يتناقــض‬\n      ‫مــع مــا ذكــره املشــرف علــى الصيانــة الســيد ‪ ...‬يف أقوالــة لــدي وزارة‬\n      ‫التجــارة فهــو قــال يف ثانيــا ممــا جــاء بخطــاب وزارة التجــارة لفضيلتكــم‬\n      ‫مــا نصــه ( توقــف الســيارة عــن احلركــة وانطفائهــا فجــأة أفــاد املشــرف‬\n      ‫علــى الصيانــة الســيد ‪...‬عــن ذلــك أفــاد بــأن الســيارة املذكــورة قــد‬\n      ‫ســبق انطفــأت وهــو يقودهــا داخــل الورشــة ) انتهــى ‪ .‬ونفيــد فضيلتكــم‬\n      ‫بــان هــذا االنطفــاء املفاجــئ تكــرر عــدة مــرات لنــا ويف الطريــق العــام‬\n      ‫والســؤال الــذي يطــرح نفســه ملــاذا ســيارة جديــدة يحــدث لهــا مثــل ذلــك‬\n\n\n‫‪101‬‬\n\f‫؟؟؟ فــا بــد أن يكــون هنالــك عيــب مصنعــي لــم يعتــرف بــه املدعــى‬\n‫عليــه !!! واعترفــت بــه الشــركة األم مصنعــة ومصــدرة هــذه الســيارة يف‬\n‫تقريرهــا املرفــق صــورة منــه ‪ 0‬وإقــرار موظفهــا املشــرف علــى الصيانــة‬\n‫مــا هــو إال دليــل يعضــد ذلــك ‪ ،‬وبالتالــي فــإن ذلــك يــدل علــى أن املدعــى‬\n‫عليــه كان يعلــم بــكل تلــك العيــوب اخلفيــة وكتمهــا وقــت البيــع ‪ ،‬فعــن‬\n‫أبــي هريــرة رضــي اهلل عنــه ( أن النبــي صلــى اهلل عليــه وســلم مــر علــى‬\n‫صبــرة طعــام ‪ -‬يعنــي كومــة طعــام ‪ -‬فأدخــل يــده فيهــا‪ ،‬فنالــت أصابعــه‬\n‫بلــا فقــال ‪ :‬مــا هــذا يــا صاحــب الطعــام ؟ قــال ‪ :‬أصابتــه الســماء يــا‬\n‫رســول يعنــي املطــر قــال ‪ :‬أفــا جعلتــه فــوق الطعــام كــي يــراه النــاس‬\n‫‪ ،‬مــن غــش فليــس منــي ) أخرجــه مســلم يف كتــب اإلميــان ‪ ،‬بــاب قــول‬\n                    ‫النبــي صلــي اهلل عليــه وســلم ( مــن غشــنا فليــس منــا )‬\n‫ثالثــا ‪ :‬إن مــا ذكــره وكيــل املدعــى عليــه يف الفقــرة الثالثــة مــن‬\n‫مذكرتــه هــذه أقــوال مرســله إذا إننــا ال ندعــى بوجــود عيــب يف جميــع‬\n‫الســيارات التــي يبيعهــا املدعــى وإمنــا العيــب واخللــل املصنعــي املعتــرف بــه‬\n‫مــن قبــل الشــركة املصنعــة يف الســيارة موضــوع الدعــوى والتــي اســتلم‬\n‫موكلــه ثمنهــا عــد ًا نقــد ًا دون انتفاعــي باملبــاع وضيــاع وقتــي وجهــدي‬\n                                                                ‫مبــا هــو يعلــم بــه ‪0‬‬\n‫رابع ـ ًا ‪ :‬مــا أشــار إليــه وكيــل املدعــى عليــه يف مذكرتــه يف الفقــرة‬\n‫الرابعــة منهــا هــذا غيــر صحيــح حيــث إنــه يحــاول التهــرب مــن العيــب‬\n‫املصنعــي يف اجلنــوط األربعــة ثــم الكفــرات للســيارة املباعــة ولكــن‬\n‫ذلــك مــردودا عليــه ومجابــا عليــه مــن قبــل وزارة التجــارة والصناعــة يف‬\n‫خطابهــا فقرتــه الرابعــة مبــا نصــه ‪ .... ( :‬وهنــا ال ميكــن األخــذ بــرأي‬\n‫الشــركة إذا ال يوجــد حــادث أو مشــاكل طريــق تــؤدي إلــى تلــف‬\n\n\n                                                                                           ‫‪102‬‬\n\f      ‫األربعــة جنــوط مــرة واحــدة ‪،‬وأن الشــركة أوضحــت أنهــا تأخــرت‬\n      ‫بتبديــل اجلنــوط بســبب أن اجلنــوط اجلديــدة التــي وصلتلهــم مــن جــده‬\n      ‫كانــت غيــر صاحلــة لالســتعمال وهــذا يعنــي عيــب مصنعــي ‪ ) .‬انتهــى‪.‬‬\n      ‫وكذلــك إجابتــه بالفقــرة املذكــورة تتناقــض مــع مــا تضمنــه خطابــه‬\n      ‫املرســل لــي ( املرفــق صورتــه ) حيــث أشــار يف الفقــرة التاســعة منــه مــا‬\n      ‫نصــه ( ‪ .......‬لقــد قضــى العميــل أيــام عديــدة بانتظــار إصــاح عجــات‬\n      ‫الســيارة والســبب كان ال بــد مــن إعــادة طلــب بعــض العجــات مــن جــدة‬\n      ‫‪ .‬لقــد اســتلمنا العجــات ولكــن لألســف وجدناهــا معطوبــة ) انتهــى‬\n      ‫‪ ..‬والســؤال هنــا الذيــي طــرح نفســه ملــاذا ســيارة جديــدة الصنــع تتلــف‬\n      ‫جنوطهــا ؟؟؟؟ إال يــدل ذلــك علــى توفــر العيــب !!! ملــاذا يتــم تغيــر اجلنــوط‬\n      ‫؟؟؟؟ لســيارة لــم يكتمــل عمرهــا عــدة شــهور !!!! بالتالــي فــإن مــا ذكره‬\n      ‫وكيــل املدعــى عليــه بالفقــرة الرابعــة يرقــي بظــال مــن الشــك والريبــة‬\n      ‫حــول تقاريــر الفحــص باملختبــرات التــي ذكرهــا مــن صالحيــة اجلنــوط‬\n      ‫املســتوردة مــن قبلــه وان كان ذلــك ال يعنينــا يف شــيء وغيــر منتــج يف‬\n      ‫الدعــوى بكــون الســيارة موضــوع الدعــوى كان بهــا عيــب مصنعــي‬\n      ‫خفــي يتمثــل يف العيــب املصنعــي للجنــوط التــي مت تغيرهــا ولكــن دون‬\n      ‫فائــدة الســتمرار التوقــف املفاجــئ للســيارة نتيجــة تعطــل الكمبيوتــر‬\n      ‫الــذي يــؤدي إلــى حــدوث كــوارث يف األرواح مــن راكبيهــا ومســتخدمي‬\n      ‫الطريــق العــام وخســارة يف املمتلــكات ثــم الدخــول مــرة ثاني ـ ًا وثالثــة‬\n      ‫ورابعــة وهكــذا يف دوامــة تغيــر اجلنــوط !!!!! إذ ًا فمــا الهــدف مــن‬\n      ‫شــراء مثــل هكــذا ســيارة !!!!!! ‪ .‬هــل قيادتهــا آمنــه !!! أم تــؤدي إلــى‬\n      ‫التهلكــة ؟؟؟ التــي منهــي عنهــا شــرع ًا ‪ ،‬فليحضــر املدعــى عليــه تســجيل‬\n      ‫الكاميــرات إلثبــات عــدد املــرات التــي زرت فيهــا الشــركة مــن اجــل‬\n\n\n‫‪103‬‬\n\f‫إصــاح هــذه الســيارة ‪ ،‬وعــن عقبــة بــن عامــر رضــي اهلل عنــه قــال ‪:‬‬\n‫ســمعت النبــي صلــي اهلل عليــه وســلم يقــول ‪ ( :‬املســلم أخــو املســلم ‪ ،‬وال‬\n‫يحــل ملســلم بــاع مــن أخيــه بيعــا وفيــه عيــب فــا بينــه لــه ) (أخرجــه ابــن‬\n‫ماجــه يف أبــواب التجــارات بــاب بــاع عيبـ ًا فليبينــه برقــم ‪ 2246‬واحلاكــم‬\n‫يف مســتدركه ‪ 1/2‬وصححــه شــرطهما و وافقــه الذهبــي وقــواه ابــن‬\n‫تيميــة يف إقامــة الدليــل ص ‪121‬وإننــي لــم اعلــم بــكل تلــك العيــوب قبــل‬\n‫ا‬\n‫الشــراء ممــا يتعــن معــه احلكــم لــي بأخــذ الثمــن الــذي دفعتــه كامـ ً‬\n‫وإنــي ال ارغــب بغيــر ذلــك علمـ ًا بــأن الســيارة املباعــة يف يــد املدعــى عليــه‬\n‫مــن تاريــخ خطابهــم املوجهــة لــي ‪ ،‬ومحاولــة املدعــى عليــه إصالحهــا‬\n‫مــا هــو إال تهــرب مــن رد الثمــن وهــذا ظلــم منهــي عنــه بقولــه تعالــي‬\n‫( يــا أيهــا الذيــن آمنــوا ال تأكلــوا أموالكــم بينكــم بالباطــل إال أن‬\n‫تكــون جتــارة عــن تــراض منكــم ) اآليــة(‪ )29‬ســورة النســاء ‪ ،‬والظلــم‬\n‫يفســد الرضــا يف العقــد كمــا إنــه مــن أكل املــال بالباطــل والظلــم يف‬\n‫البيــع فهــو الغــش خامس ـ ًا ‪ :‬لقــد أورد وكيــل املدعــى عليــه بالفقــرة‬\n‫اخلامســة مــن مذكرتــه مــا نصــه ‪ ( :‬إلصــاح وضبــط الزوايــا مت تغيــر‬\n‫الــذراع األمامــي األميــن علم ـ ًا بــأن ضبــط الزوايــا يتــم يف ورشــة ‪...........‬‬\n‫بإشــراف مؤسســة ‪..........‬للســيارات ‪ ...‬ومت فحــص الســيارة علــى الطريــق‬\n‫والتأكــد مــن إصــاح الزوايــا ومطابقتهــا للمواصفــات الفنيــة املطلوبــة‬\n‫مــن شــركة ‪ ...‬العامليــة ‪ ....‬الــخ ) ‪ ،‬يــا صاحــب الفضيلــة إنــي أشــتري‬\n‫ســيارة جديــدة ثــم يحــدث لهــا كل ذلــك وهــى جديــدة ‪ ،‬إضافــة إلــى أن‬\n‫التقريــر الفنــي الصــادر مــن الشــركة التــي املدعــى عليــه هــو وكيلهــا‬\n‫( واملرفــق صــورة منــه مترجم ـ ًا ) يفيــد مــا نصــه ‪ ( :‬أن بالســيارة فشــل‬\n‫يف قــراءة األخطــاء ‪ -‬وبهــا خلــل يف نظــام القيــادة الكهروميكانيكــي‬\n\n\n                                                                                          ‫‪104‬‬\n\f      ‫‪ -‬ومبعاجلــة اخلطــأ أغلــق البرنامــج الدولــي لتطبيقــات الصيانــة الفنيــة‬\n      ‫وانتقــل إلــى التشــخيص للبحــث ضمــن اخلطــأ املوجــودة ‪ -‬لــم يتــم إجــراء‬\n      ‫مطابقــة تــوازن الســيارة ) انتهــى ‪ 0‬ممــا يعنــي أن املدعــى عليــه تعمــد‬\n      ‫تعطيــل الكمبيوتــر لعــدم ظهــور أيــة عيــوب علــى الســيارة وبعــد تقريــر‬\n      ‫الشــركة األم الــذي أوضــح تلــك العيــوب ملــاذا يصــر املدعــى عليــه بــان‬\n      ‫الســيارة ســليمة وخاليــة مــن العيــوب الصناعيــة والشــركة األم هــي‬\n      ‫ذات نفســها تقــر بذلــك فهــو ادخــل الســيارة إلــى ورشــة ‪ ............‬إلصــاح‬\n      ‫الزوايــا والشــركة املصنعــة للســيارة تقــر بأنــه لــم يجــري لهــا مطابقــة‬\n      ‫تــوازن حــن صنعهــا ‪ ،‬كمــا وان املدعــى عليهــا تقــر مبوجــب تقريــر‬\n      ‫وزارة التجــارة املوجهــة ملقــام فضيلتكــم بأنهــا لــم تقــوم باســتدعاء‬\n      ‫الســيارة موضــوع الدعــوى مــن قبــل الشــركة األم انظــر يف ذلــك إلــى‬\n      ‫الفقــرة اخلامســة مــن هــذا التقريــر مبــا نصــه ‪ ( :‬وبســؤال الشــركة عــن‬\n      ‫قيامهــم باســتدعاء الســيارة املعيبــة ماركــة ‪ ...‬الفئــة اخلامســة موديــل‬\n      ‫‪2011‬م أفــادوا عــن قيامهــم بإجــراء االســتدعاء لســيارات بحســب رقــم‬\n      ‫الهيــكل الــوارد لهــم عــن طريــق الشــركة األم وال يشــملها رقــم هيــكل‬\n      ‫هــذه الســيارة ) انتهــى سادس ـ ًا ‪ :‬الطلبــات ‪:‬احلكــم لــي بإلــزام املدعــى‬\n                             ‫عليــه بــرد ثمــن الســيارة وفســخ عقــد البيــع للعيــب ‪0‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه قــال‪ :‬أكتفــي مبــا قدمــت وال جديــد‬\n      ‫لــدي‪ .‬وبســؤال املدعــي عــن العيــب متــى حصــل فقــال‪ :‬لقــد حصــل‬\n      ‫العيــب مــن ثانــي يــوم اســتلمت فيــه الســيارة فآلــة التنبيــه ال تعمــل‬\n      ‫وجهــاز الكمبيوتــر لــم يبــن هــذا العيــب ( ثــم أرجعــت الســيارة لهــم ثــم‬\n      ‫قامــوا بإصــاح جهــاز التنبيــه ولكــن الكمبيوتــر ال يعمــل علــى الوجــه‬\n      ‫املطلــوب ‪ ،‬ثــم تعيبــت الفرامــل وقامــوا بإصالحهــا لــي ثــم حــدث عيــب‬\n\n\n‫‪105‬‬\n\f‫يف الكمبيوتــر جعــل الســيارة تنطفــئ مــن حالهــا ممــا ســبب حادثــا‬\n‫ثــم أرجعــت الســيارة لهــم وأصلحوهــا لــي ثــم صــرت أتــردد عليهــم شــبه‬\n‫يومــي فهــواء الكفــرات دائــم النقــص والكمبيوتــر ال يبــن ذلــك‬\n‫زيــادة علــى أن اخللــل صــار مــن اجلنــوط التــي تبــن أنهــا مكســرة وقــد‬\n‫أثبتــت وزارة التجــارة أنــه عيــب مصنعــي ‪ ،‬ثــم حــدث حــادث آخــر بنفــس‬\n‫املشــكلة الســابقة ثــم أعدتهــا لهــم وأصلحوهــا ثــم أخــذت الســيارة‬\n‫والزالــت املشــكلة قائمــة ثــم أرجعتهــا إليهــم ولــم آخذهــا حتــى اآلن ‪،‬‬\n‫وبســؤال املدعــي هــل هــو مســتعد ببــذل اليمــن علــى ذلــك فقــال نعــم ‪،‬‬\n‫وبســؤاله هــل لديــك مــا تقدمــه فقــال أكتفــي مبــا قدمــت ‪ ،‬وبســؤال‬\n‫املدعــى عليــه وكالــة قــال أكتفــي مبــا قدمــت لــذا جــرى قفــل بــاب‬\n‫املرافعــة ورفعــت اجللســة للدراســة والتأمــل ويف جلســة أخــرى ويف جلســة‬\n‫أخــرى حضــر املدعــي ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ……‪ ..‬وحضــر حلضــوره …‪ ..‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ، .............‬وبطلــب اليمــن املدعــي اســتعد بأدائهــا وبعــد‬\n‫أن بينــت لــه عاقبــة اليمــن الكاذبــة ومغبتهــا ‪ ،‬أذنــت لــه ببــذل اليمــن‬\n‫فقــال‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو احلــي القيــوم القــوي القاهــر‬\n‫أنــي اشــتريت ســيارة مــن نــوع ‪ 523 ...‬الفئــة اخلامســة صنــع عــام ‪2011‬‬\n‫م ذات اللوحــة رقــم ( ‪ )..............‬مببلــغ وقــدره مائتــان وخمســة عشــر‬\n‫ألــف ريــال مــن شــركة ‪ ...............‬للســيارات ‪ ،‬وأنــه قــد حصــل فيهــا‬\n‫عيــب مــن ثانــي يــوم اســتلمت فيــه الســيارة فآلــة التنبيــه ال تعمــل وجهــاز‬\n‫الكمبيوتــر لــم يبــن العيــب ‪ ،‬ثــم تعيبــت الفرامــل ثــم حــدث عيــب يف‬\n‫جهــاز الكمبيوتــر جعــل الســيارة تنطفــئ مــن حالهــا ممــا ســبب حادثــا ‪،‬‬\n‫ثــم حــدث عيــب يف هــواء الكفــرات و جهــاز الكمبيوتــر لــم يبــن هــذا‬\n\n\n                                                                                      ‫‪106‬‬\n\f      ‫العيــب ثــم حــدث حــادث آخــر بســبب انطفــاء الســيارة مــن حالهــا ‪ ،‬ولــم‬\n      ‫أرض بهــذه العيــوب ولــم تكــن العيــوب ناجتــة عــن اســتخدامي ‪ ،‬وقــد‬\n      ‫راجعــت الشــركة بعــد كل عيــب يف الســيارة واهلل العظيــم‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة واليمــن ولقولــه تعالــى (يــا أيهــا الذيــن‬\n      ‫آمنــوا ال تأكلــوا أموالكــم بينكــم بالباطــل) قــال ابــن العربــي‪« :‬يعنــي‬\n      ‫مبــا ال يحــل شــرعا و ال يفيــد مقصــودا» أحــكام القــرآن ‪ ، 97/1‬وجــاء‬\n      ‫يف تفســير املنــار ‪ 40/5‬يف معنــى الباطــل‪« :‬أنــه مــا لــم يكــن يف مقابلــة‬\n      ‫شــيء حقيقــي وهــو مــن الباطــل والبطــان أي الضيــاع واخلســار ‪ ،‬فقــد‬\n      ‫حرمــت الشــريعة أخــذ املــال بــدون مقابلــة حقيقيــة يعتــد بهــا ممــن يؤخــذ‬\n      ‫منــه» ‪ ،‬وملــا جــاء يف حديــث أبــي هريــرة رضــي اهلل عنــه أن النبــي صلــى‬\n      ‫اهلل عليــه وآلــه وســلم قــال (كل املســلم علــى املســلم حــرام دمــه ومالــه‬\n      ‫وعرضــه) رواه مســلم ‪ ،‬وملــا جــاء يف معنــى العيــب عنــد العلمــاء فقــد‬\n      ‫قــال ابــن تيميــه رحمــه اهلل‪« :‬إن كل مــا يوجــد باملبيــع ممــا ينقــص العــن‬\n      ‫أو القيمــة نقصــا يفــوت بــه غــرض صحيــح ‪ ،‬يثبــت بــه الــرد» حاشــية‬\n      ‫ابــن قاســم ‪ . 442/4‬وقــال الشــيرازي رحمــه اهلل يف املهــذب‪1/286« :‬‬\n      ‫والعيــب الــذي يــرد بــه املبيــع ممــا يعــده النــاس عيبــا فــإن خفــي منــه شــيء‬\n      ‫رجــع فيــه إلــى أهــل اخلبــرة بذلــك اجلنــس» وقــال املــرداوي يف اإلنصــاف‪»:‬‬\n      ‫العيبــه ومــا ينقــص قيمــة املبيــع نقيصــة يقتضــي العــرف ســامة املبيــع‬\n      ‫عنهــا غالبــا» ‪ ،‬وملــا قــرره الفقهــاء مــن أن خيــار العيــب يثبــت بــا اشــتراط‬\n      ‫قــال ابــن عابديــن يف حاشــيته ‪« : 3/5‬خيــار العيــب يثبــت بــا اشــتراط»‪.‬‬\n      ‫وملــا قــرره الفقهــاء مــن أن خيــار العيــب علــى التراخــي قــال البهوتــي يف‬\n      ‫شــرح منتهــى اإلرادات ‪« : 211/3‬وخيــار عيــب متــراخ ألنــه لدفــع ضــرر‬\n      ‫متحقــق فــا يســقط بالتأخيــر كالقصــاص ‪ ،‬إال إن وجــد دليــل رضــاه‬\n\n\n‫‪107‬‬\n\f‫أي املشــتري» ‪ ،‬وملــا قــرره الفقهــاء مــن أنــه إذا اختلــف البائــع واملشــتري‬\n‫يف عيــب املبيــع مــع االحتمــال فالقــول قــول املشــتري بيمينــه قــال البهوتــي‬\n‫رحمــه اهلل‪ » :‬وإن اختلفــا أي البائــع واملشــتري يف معيــب عنــد مــن حــدث‬\n‫العيــب مــع االحتمــال فقــول مشــتر بيمينــه إن لــم يخــرج عــن يــده « الروض‬\n‫املربــع ‪ ، 454 /4‬وملــا قــرره الفقهــاء مــن أنــه متــى علــم املشــتري بالعيــب‬\n‫فهــو باخليــار بــن اإلمســاك مــع األرش أو الــرد قــال ابــن قدامــة رحمــه‬\n‫اهلل يف املغنــي ‪ »:108/4‬ومتــى علــم ‪ ،‬يعنــي املشــتري‪ -‬باملبيــع عيبــا لــم‬\n‫يكــن عاملــا بــه فلــه اخليــار بــن اإلمســاك والفســخ ســواء كان البائــع‬\n‫علــم العيــب وكتمهــا ولــم يعلــم ‪ ،‬ال نعلــم بــن أهــل العلــم يف هــذا خالفــا»‬\n‫‪ ،‬ومبــا أن املشــتري رفــض اإلمســاك مــع األرش وطالــب بالثمــن مــع رد‬\n‫املبيــع ‪ ،‬ومبــا أن تقريــر وزارة التجــارة قــد صــدر مــن خبيــر واخلبيــر أمــن‬\n‫كمــا قــرر ذلــك الفقهــاء وملــا جــاء يف قــرار وزارة التجــارة مــن تأييــد‬\n‫كالم املدعــي مــع عــدم اجلــزم بالعيــوب هــل هــي مصنعيــة أو ال ممــا يعــد‬\n‫قرينــة تقــوي جانــب املدعــي خصوصــا مــع جــدة الســيارة ‪ ،‬وملــا جــاء يف‬\n‫تقريــر وزارة التجــارة مــن اجلــزم بوجــود عيــب مصنعــي يف اجلنــط ممــا يعد‬\n‫قرينــة أخــرى تقــوي جانــب املدعــي ‪ ،‬ومبــا أن املدعــي لــم يــرض بتلــك‬\n‫العيــوب ولــم يصــدر منــه أي فعــل يــدل علــى الرضــا بدليــل تــردده علــى‬\n‫مركــز الصيانــة بعــد كل عيــب يحــدث يف الســيارة ومــن ثــم تركــه‬\n‫للســيارة عندهــم ‪ ،‬ومبــا أن هــذا العيــب يعــد عيبــا مؤثــرا يف الســيارة‬\n‫ال يحقــق املقصــود مــن شــراءها ‪ ،‬وملــا جــاء يف ميــن املدعــي ‪ ،‬ومبــا أن‬\n‫املشــتري قــد بــذل الثمــن ليســلم لــه مبيــع ســليم ولــم يســلم لــه فثبــت لــه‬\n‫الرجــوع بالثمــن أو اإلمســاك مــع األرش ‪ ،‬لذلــك كلــه فقــد حكمــت‬\n‫علــى شــركة ‪ .........‬للســيارات بإعــادة ثمــن الســيارة املعيبــة وقــدره‬\n\n\n                                                                                        ‫‪108‬‬\n\f      ‫مائتــان وخمســة عشــر ألــف ريــال لصالــح املدعــي ‪ ،............‬وبعــرض‬\n      ‫احلكــم علــى املدعــي قــرر قناعتــه ‪ ،‬وبعرضــه علــى وكيــل الشــركة‬\n      ‫املدعــى عليــه قــرر عــدم القناعــة فجــرى تســليمه نســخة مــن احلكــم ‪،‬‬\n      ‫وأفهــم بــأن مــدة االعتــراض ثالثــون يومــا مــن تاريــخ هــذا اليــوم فــإن تقدم‬\n      ‫باعتراضــه وإال ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n      ‫ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                     ‫وســلم‪ .‬حــرر يف ‪1434/4/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬املــازم القضائــي لــدى الشــيخ‬\n      ‫‪ .........‬القاضــي يف احملكمــة العامــة بالريــاض وبناء على املعاملة احملالة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪33474401‬‬\n      ‫وتاريــخ ‪1433/07/19‬ه ـ املقيــدة باحملكمة برقــم ‪ 331356537‬وتاريخ‬\n      ‫‪1433/7/19‬ه ـ يف يــوم الســبت املوافق‪1434/07/01‬ه ـ عــادت إلينــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف بالريــاض رقــم ‪ 341370055‬وتاريــخ‬\n      ‫‪1434/6/18‬ه ـ املرفــق بهــا قــرار املالحظــة رقــم ‪ 34238979‬وتاريــخ‬\n      ‫‪1434/6/12‬ه ـ واملتضمــن مــا نصــه بعــد املقدمــة‪ »:‬لوحــظ بــأن فضيلتــه‬\n      ‫قــد ألــزم الشــركة بإعــادة ثمــن الســيارة قبــل أن يقــرر فســخ عقــد البيــع‬\n      ‫للعيــب والبــد مــن ذلــك كمــا أنــه لــم يقــرر بــأن ملكيــة الســيارة تعــود‬\n      ‫إلــى الشــركة وأن لهــا التصــرف بهــا مبــا تشــاء بعــد اكتســاب احلكــم‬\n      ‫القطعيــة فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم ‪ ،‬قاضــي‬\n      ‫اســتئناف ‪ .........‬توقيــع وختــم ‪ ،‬قاضــي اســتئناف ‪ ..........‬توقيــع وختــم ‪،‬‬\n      ‫رئيــس الدائــرة ‪ ............‬توقيــع وختــم ‪.‬اهــ‪ .‬عليــه أفيــد أصحــاب الفضيلــة‬\n      ‫بــأن مــا ذكــروا مــن مالحظــات قــد ســقطت ســهوا عليــه افتتحــت‬\n      ‫اجللســة وحضــر الطرفــان ‪ ،‬وذكــرت لهــم بــأن منطــوق احلكــم هــو‪:‬‬\n\n\n‫‪109‬‬\n\f‫لذلــك كلــه فقــد حكمــت بفســخ عقــد البيــع لوجــود العيــب املذكــور‬\n‫ومبوجبــه يتــم إعــادة ثمــن الســيارة املعيبــة وقــدره مائتــان وخمســة عشــرة‬\n‫ألــف ريــال لصالــح املدعــي ‪ ................‬وأفهمــت وكيــل الشــركة بــأن‬\n‫الســيارة تعــود مللكيــة الشــركة ولهــا أن تتصــرف بهــا مبــا تشــاء بعــد‬\n‫اكتســاب احلكــم القطعيــة ففهــم ذلــك ‪ .‬وأمــرت بإعــادة املعاملــة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/1‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬املــازم القضائــي لــدى‬\n‫فضيلــة الشــيخ‪..........‬القاضي يف احملكمــة العامــة بالريــاض ففــي‬\n‫يــوم الثالثاءاملوافــق‪ 1434/09/22‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n‫‪02‬وفيهــا حضــر ‪ .......‬املدونــة هويتــه ســابقا ‪ .‬وأفــاد بأنــه قد اســتلم شــيك‬\n‫مــن املدعــي برقــم ‪899879‬مــن البنــك ‪ ....‬مببلــغ وقــدره ( ‪) 215.000‬‬\n‫ريــال ‪ .‬وبذلــك تكــون املطالبــة منتهيــة بــن الطرفــن وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1434/9/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫باخلطــاب رقــم ‪ 341370055‬وتاريــخ ‪1434/7/3‬ه ـ املرفــق بهــا الصــك‬\n‫رقــم ‪34194877‬وتاريــخ ‪1434/4/22‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ............‬املتضمــن احلكــم يف الدعــوى املقامــة‬\n‫مــن‪ ...........‬ضــد ‪ ..........‬علــى النحــو املوضــح بالصــك واملتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وباالطــاع على ما أجاب بــه فضيلته‬\n\n\n                                                                                      ‫‪110‬‬\n\f      ‫وأحلقــه بالصــك وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪34238979‬‬\n      ‫وتاريــخ ‪1434/6/12‬ه ـ فقــد قــررت الدائــرة املصادقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":91,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0abd7b698bc92ce2c080ebeb45df8794b1bdc2bb746d9101cded133d040672b4","normalized_text_hash":"fde1c098d69eb5e4110e923e033e614c794c8970d3d132c782cb42ee71838aa0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p91-34194877"},{"id":"a06aeb97-2278-5159-87a5-d091b445fac5","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -خيار العيب -مطالبة برد ثمن سيارة معيبة -رد دعوى املدعي لقيامه ببيع العن املعيبة قبل املطالبة برد ثمنها -بيع املبيع بعد تلفه -مواجهة املدعى عليه بالدعوى -تقرير الدفاع املدني -تراخي يف املطالبة برد املببيع .","document_number":"33477956","case_number":"33490485","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/26","year":"1434","subject":"بيع -خيار العيب -مطالبة برد ثمن سيارة معيبة -رد دعوى املدعي لقيامه ببيع العن املعيبة قبل املطالبة برد ثمنها -بيع املبيع بعد تلفه -مواجهة املدعى عليه بالدعوى -تقرير الدفاع املدني -تراخي يف املطالبة برد املببيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/26 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33477956 :‬‬\n                    ‫َر ْق ُم الدعوى‪33490485 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34297931‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n ‫بيــع ‪ -‬خيــار العيــب ‪ -‬مطالبــة بــرد ثمــن ســيارة معيبــة ‪ -‬رد دعــوى‬\n ‫املدعــي لقيامــه ببيــع العــن املعيبــة قبــل املطالبــة بــرد ثمنهــا‪ -‬بيــع‬\n ‫املبيــع بعــد تلفــه ‪ -‬مواجهــة املدعــى عليــه بالدعــوى ‪ -‬تقريــر الدفــاع‬\n                               ‫املدنــي ‪ -‬تراخــي يف املطالبــة بــرد املببيــع ‪.‬‬\n\n\n\n\n ‫‪ .1‬نــص ابــن قدامــة يف املغنــى‪« :‬إذا اشــترى معيبـ ًا فباعــه ســقط رده ألنــه‬\n                                                    ‫قــد زال ملكــه عنه» ‪.242/6‬‬\n ‫‪ .2‬نــص املــرداوي يف اإلنصــاف‪« :‬وإن فعلــه عامل ـ ًا بعيبــه فــا شــيء لــه‬\n ‫وكــذا لــو تصــرف فيــه مبــا يــدل علــى الرضــا أو عرضــه للبيع أو اســتغله‬\n ‫وهــو املذهــب يف ذلــك كلــه وعليــه جماهيــر األصحــاب وقطــع بــه‬\n     ‫كثيــر منهــم»‪ 398/11‬اإلنصــاف مــع الشــرح الكبيــر علــى املقنــع ‪.‬‬\n\n\n\n\n ‫تقــدم املدعــي بدعــوى ضــد الشــركة املدعــى عليهــا ( الوكيــل التجاري‬\n ‫املعتمــد للســيارة املشــتراة ) بأنــه اشــترى مــن أحــد معــارض الســيارات‬\n ‫ســيارة جديــدة فتفاجــأ يومــا باحتراقهــا بالكامــل لعيــب مصنعــي ال‬\n ‫بفعــل فاعــل ممــا تعــذر االنتفــاع بهــا فباعهــا بالتشــليح «كومــة حديــد»‬\n ‫لــذا فيطلــب إلــزام املدعــى عليهــا بإعــادة مــا ســلمه مــن ثمــن ‪ ،‬فجــرى‬\n\n                                                                                     ‫‪112‬‬\n\f      ‫ســؤاله كيــف علــم بالعيــب املصنعــي وعــن ســبب تأخــره يف إقامــة‬\n      ‫الدعــوى فأجــاب بــأن الدفــاع املدنــي أخبــره بــأن ســببه عيــب مصنعــي‬\n      ‫وأنــه تقــدم بشــكوى لــدى الداخليــة ضــد صاحــب املعــرض فدفــع بأنــه‬\n      ‫ال عالقــة لــه بذلــك وأن عليــه أن يقيــم دعــواه ضــد الشــركة املــوردة‬\n      ‫‪،‬عليــه وإلقــرار املشــتري ببيعــه الســيارة محــل الدعــوى بعــد ســبعة أشــهر‬\n      ‫مــن تاريــخ شــرائها وألن املدعــي يطلــب إلــزام الشــركة املدعــى عليهــا‬\n      ‫بإعــادة ثمــن الســيارة وطلبــه وإن كان أحــد األمريــن املتاحــن للمشــتري‬\n      ‫العالــم بالعيــب (اإلمســاك مــع األرش أورد الثمــن) عليــه وحلصــر املدعــي‬\n      ‫دعــواه يف طلبــه رد الثمــن وألن الســيارة التــي تصــرف فيهــا املدعــي بالبيع‬\n      ‫هــي أحــد العوضــن وملــا قــرره أهــل العلــم يف هــذه املســألة قال ابــن قدامة‬\n      ‫يف املغنــى‪« :‬إذا اشــترى معيب ـ ًا فباعــه ســقط رده ألنــه قــد زال ملكــه‬\n      ‫عنــه» ‪ ، 242/6‬وقــال املــرداوي يف اإلنصــاف‪« :‬وإن فعلــه عامل ـ ًا بعيبــه‬\n      ‫فــا شــيء لــه وكــذا لــو تصــرف فيــه مبــا يــدل علــى الرضــا أو عرضــه‬\n      ‫للبيــع أو اســتغله وهــو املذهــب يف ذلــك كلــه وعليــه جماهيــر األصحــاب‬\n      ‫وقطــع بــه كثيــر منهــم»‪ 398/11‬اإلنصــاف مــع الشــرح الكبيــر علــى‬\n      ‫املقنــع ‪،‬عليــه فقــد قــررت الدائــرة صــرف النظــر عــن دعــوى املدعــي‬\n      ‫وأخلــت ســبيل املدعــى عليهــا ‪ ،‬بعــرض احلكــم عليــه قــرر االعتــراض‬\n              ‫فأفهــم بالتعليمــات ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n‫ـاء علــى أوراق املعاملــة احملالــة الينــا مــن فضيلــة‬\n                                                      ‫مبكــة املكرمــة وبنـ ً‬\n‫رئيــس هــذه احملكمــة برقــم ‪ 33490485‬يف ‪1433/7/27‬ه ـ واملقيــدة‬\n‫برقــم ‪ 331414585‬يف ‪1433/7/27‬ه ـ واملتعلقــة بدعــوى (‪ ).....‬ضــد‬\n‫ـاء علــى ذلــك فقــد حضــر لــدي يف هــذا اليــوم الثالثــاء‬\n                                                            ‫شــركة (‪ ).....‬بنـ ً‬\n‫‪1433/11/16‬هـ الســاعة ‪ 10‬املدعى (‪ ).....‬ســعودي اجلنســية برقم (‪).....‬‬\n‫وحضــر حلضــوره املدعــو (‪ ).....‬بالســجل املدنــي رقــم (‪ ).....‬بوكالتــه عــن‬\n‫(‪ ).....‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب‬\n‫ســجل مدنــي رقــم (‪ ).....‬بصفتــه مديــر ًا ل(‪ ).....‬احملــدودة املخــول لــه‬\n‫فيهــا إقامــة وســماع الدعــاوى والشــكاوي والســير فيهــا إلــى أخــر‬\n‫درجــة مــن درجــات التقاضــي الصــادرة مــن كتابــة العــدل الثانيــة شــمال‬\n‫محافظــة جــدة برقــم ‪ 28070‬يف ‪1433/3/27‬ه ـ ثــم ادعــى املدعــي يف‬\n‫مواجهــة املدعــى عليــه وكالــة قائــا يف حتريــر دعــواه لقــد اشــتريت مــن‬\n‫الشــركة املدعــى عليهــا ســيارة نــوع ‪ ...‬موديــل ‪2006‬م طــراز ‪ ...‬وكان‬\n‫الشــراء بتاريــخ ‪2006‬م حيــث اشــتريتها بثمــن قــدره مائتــن ألــف ريــال‬\n‫دفعتهــا كاملــة وقــد مكثــت معــي تلــك الســيارة قرابــة ثالثــة أشــهر‬\n‫مــن تاريــخ الشــراء إال أنــي تفاجــأت باحتراقهــا بشــكل كامــل وذلــك‬\n‫االحتــراق لعيــب مصنعــي يف الســيارة أدى إلــى احتراقهــا وأفقدنــي‬\n‫االنتفــاع بهــا مــا جعلنــي أقــوم ببيعهــا يف التشــليح مببلــغ ســبعة عشــر ألــف‬\n‫ريــال لــذا فإنــي أطلــب احلكــم علــى الشــركة املدعــي عليهــا بإعــادة‬\n‫كامــل الثمــن الــذي بذلتــه والبالــغ مائتــن ألــف ريــال هــذه دعــواي‬\n\n                                                                                        ‫‪114‬‬\n\f      ‫وأســأل اجلــواب ثــم ســألته متــى بعــت الســيارة فأجــاب بقولــه لقــد بعتهــا‬\n      ‫بعــد ســبعة أشــهر مــن تاريــخ الشــراء ثــم ســألته عــن كيفيــة معرفتــه‬\n      ‫بــأن احتــراق الســيارة كان بســبب عطــل مصنعــي فأجــاب بقولــه ان‬\n      ‫تقريــر الدفــاع املدنــي والشــرطة والبحــث اجلنائــي أفادونــي بــأن عيب ـ ًا‬\n      ‫مصنعي ـ ًا كان الســبب يف احتراقهــا ثــم ســألته عــن ســبب تراخيــه يف‬\n      ‫مطالبتــه هــذه فأجــاب بقولــه إنــي تقدمــت بشــكاوى يف هــذا املوضــوع‬\n      ‫األولــى رفعتهــا لــوزارة الداخليــة ثــم تركــت متابعتهــا ثــم أقمــت دعــوى‬\n      ‫علــى صاحــب املعــرض الــذي اشــتريتها منــه فقــال انــي لســت مســئو ًال‬\n      ‫ـاء علــى‬‫عــن الســيارة وامنــا شــركة ‪ ...‬هــي املســئولة هكــذا قــال ‪ .‬فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى وال قــرار املشــتري ببيعــه الســيارة محــل الدعــوى‬\n      ‫بعــد ســبعة اشــهر مــن تاريــخ شــرائها وألن املدعــي يطلــب إلــزام الشــركة‬\n      ‫املدعــى عليهــا بإعــادة ثمــن الســيارة البالــغ مائتــن ألــف ريــال وألن طلبــه‬\n      ‫ذلــك وإن كان أحــد األمريــن املتاحــن للمشــتري العالــم بالعيــب وهــي‬\n      ‫امســاك املبيــع بأرشــه وهــو قســط مــا بــن قيمــة الصحــة والعيــب أورده‬\n      ‫وأخــذ الثمــن وحلصــر املدعــي دعــواه يف طلبه رد الثمن وألن الســيارة التي‬\n      ‫تصــرف فيهــا املدعــى بالبيــع هــي أحــد العوضــن وملــا قــرره أهــل العلــم‬\n      ‫يف هــذا اجلانــب حيــث قــال ابــن قدامــة يف املغنــى (( إذا اشــترى معيب ـ ًا‬\n      ‫فباعــه ســقط رده ألنــه قــد زال ملكــه عنــه ))‪ 242/6‬وقــال املــرداوي يف‬\n      ‫اإلنصــاف ( وإن فعلــه عاملـ ًا بعيبــه فــا شــيء لــه وكــذا لــو تصــرف فيــه‬\n      ‫مبــا يــدل علــى الرضــا أو عرضــه للبيــع أو اســتغله وهــو املذهــب يف ذلــك‬\n      ‫كلــه وعليــه جماهيــر األصحــاب وقطــع بــه كثيــر منهــم )‪398/11‬مــع‬\n      ‫ـاء علــى ذلــك فقــد صرفــت النظــر عــن‬  ‫الشــرح الكبيــر علــى املقنــع بنـ ً‬\n      ‫دعــوى املدعــي ‪..................‬أخليــت ســبيل املدعــى عليهــا وبذلــك حكمت‬\n\n\n‫‪115‬‬\n\f‫وبعرضــه علــى املدعــي قــرر اعتراضــه عليــه فأفهمتــه مبراجعــة احلكــم‬\n‫خــال عشــرة أيــام مــن تاريخــه الســتالم نســخة مــن هــذا احلكــم لتقــدمي‬\n‫مــا لديــه حيالــه مــن اعتــراض خــال ثالثــن يومـ ًا مــن تاريخ اســتالمه فإن‬\n‫لــم يفعــل خاللهــا فــإن حقــه يف االســتئناف يســقط ويكتســب احلكــم‬\n                      ‫القطعيــة وبــاهلل التوفيــق حــرر يف ‪1433/11/16‬ه ـ ‪.‬‬\n‫احلمد هلل وحده وبعد فقد عادت أوراق املعاملة من محكمة االستئناف‬\n‫برقــم ‪ 34515117‬يف ‪1434/4/7‬ه ــاملرفق بهــا قــرار مالحظــة الدائــرة‬\n‫احلقوقيــة الثانيــة ذو الرقــم ‪ 3457467‬يف ‪1434/3/8‬ه ـ ونــص احلاجــة‬\n‫منــه (بدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة إعادتهــا ملالحظــة مــا يلــي ‪ -1‬لــم جنــد فضيلــة عــرض دعــوى‬\n‫املدعــي علــى املدعــى عليــه وكالــة وإجــراء الــازم نحوهــا والبــد مــن‬\n‫ذلــك ‪ -2‬ذكــر املدعــي يف الئحتــه االعتراضيــة أمــور ينبغــي مناقشــتها‬\n‫بحضــور الطرفــن وإجــراء الوجــه الشــرعي نحوهــا) اهــ‪ .‬عليــه فإنــي‬\n‫أجيــب أصحــاب الفضيلــة وفقهــم اهلل تعالــى لــكل خيــر بــأن مــا أشــير‬\n‫إليــه يف املالحظــة األولــى فــا شــك أن جــواب املدعــى عليــه أثــر مــن‬\n‫اآلثــار الالزمــة لصحــة الدعــوى وذلــك ألن قطــع اخلصومــة واملنازعــة‬\n‫واجــب وال ميكــن القطــع إال باجلــواب فــكان واجبــا أمــا يف هــذه الدعوى‬\n‫فقــد صرفــت النظــر عــن دعــوى املدعــي ابتــداء لألســباب التــي ذكرتهــا‬\n‫وبالتالــي لــم أرى موجبــا لعرضهــا علــى املدعــى عليــه وكالــة وغيــر خاف‬\n‫علــى أصحــاب الفضيلــة مــا قــرره أهــل العلــم مــن أنــه إذا زال املوجــب‬\n‫زال املوجــب وأمــا املالحظــة الثانيــة فقــد أعــدت االطــاع علــى الالئحــة‬\n‫االعتراضيــة فلــم أرى فيهــا مــا يؤثــر علــى مــا حكمــت بــه وبالتالي الزلت‬\n‫عليــه وأمــرت بإعــادة أوراق املعاملــة حملكمــة االســتئناف لتدقيقهــا‬\n\n\n                                                                                   ‫‪116‬‬\n\f      ‫وبــاهلل التوفيــق وصــل اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                        ‫حتريــرا يف ‪1434/4/20‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامة مبكة‬\n      ‫املكرمــة القائــم بعمــل الشــيخ (‪ ).....‬خلــف فضيلة الشــيخ (‪ ).....‬القاضي‬\n      ‫األســبق بهــذه احملكمــة حيــث عــادت أوراق املعاملــة مــن محكمــة‬\n      ‫االســتئناف باخلطــاب رقــم ‪ 34515117‬يف ‪1434/9/3‬ه ـ رفقهــا الصــك‬\n      ‫الشــرعي رقــم ‪ 33477956‬يف ‪1433/12/26‬ه ـ مظهــر ًا عليــه بقــرار‬\n      ‫الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف رقــم ‪ 34297931‬يف‬\n      ‫‪1434/8/15‬ه ـ املتضمــن وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n      ‫االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ .‬قاضــي اســتئناف‬\n      ‫ختــم وتوقيــع (‪ ).....‬قاضــي اســتئناف ختــم وتوقيــع (‪ ).....‬قاضــي‬\n      ‫اســتئناف ختــم وتوقيــع (‪( ).....‬لــي وجهــة نظــر) ‪ .‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/10/11‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪34/515117‬وتاريــخ‬\n      ‫‪1434/7/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪).....‬‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33477956‬وتاريــخ‬\n      ‫‪1433/12/26‬هـ ‪ ،‬املتضمن دعوى (‪ ).....‬ضد (‪ ، ).....‬وبدراسة الصك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n‫‪117‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":112,"source_page_end":117,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c595041167de68f403926faf6e2c13942b4393846026b5dc4f56b698f6fa25e8","normalized_text_hash":"5ddf30296fae758a3430f2678a234829197e1f090995313e21652779787ab372","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p112-33477956"},{"id":"0f9f2c13-4392-518b-b666-2fd4cad2adca","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -طلب املدعي باقي ثمن املبيع -البينة شهادة الشاهد واليمن -اليمن تشرع يف جانب أقوى املتداعين -احلكم الغيابي بإلزام املدعى عليه أن يسلم للمدعي املبلغ املدعى به والغائب على حجته.","document_number":"34171137","case_number":"33526762","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف لدراسة احلكم وتدقيقه حسب املتبع وباهلل التوفيق","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/24","year":"1434","subject":"بيع -طلب املدعي باقي ثمن املبيع -البينة شهادة الشاهد واليمن -اليمن تشرع يف جانب أقوى املتداعين -احلكم الغيابي بإلزام املدعى عليه أن يسلم للمدعي املبلغ املدعى به والغائب على حجته.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/24 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34171137 :‬‬\n                    ‫َر ْق ُم الدعوى‪33526762 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34249959‬تاريخه‪1434/6/24 :‬هـ‬\n\n\n‫بيــع ‪ -‬طلــب املدعــي باقــي ثمــن املبيــع ‪ -‬البينــة شــهادة الشــاهد واليمــن‬\n‫‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬احلكــم الغيابــي بإلــزام‬\n‫املدعــى عليــه أن يســلم للمدعــي املبلــغ املدعــى بــه والغائــب على حجته‪.‬‬\n\n\n\n\n‫‪ .1‬حديــث ابــن عبــاس ( أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــاهد‬\n                                         ‫واليمني ) رواه مســلم يف صحيحه‪.‬‬\n‫‪ .2‬حديــث أبــي هريــرة قــال ( قضــى رســول اهلل صلــى اهلل عليــه وســلم‬\n‫باليمــن مــع الشــاهد الواحــد ) أخرجــه أبــو داود والترمــذي وابــن ماجــه‬\n                                                                      ‫والبيهقــي‪.‬‬\n‫‪ .3‬قــال ابــن قدامــة ‪ ( :‬وألن اليمــن تشــرع يف حــق مــن ظهــر صدقــه‬\n‫وقــوي جانبــه ولذلــك شــرعت يف حــق صاحــب اليــد لقــوة جنبتــه بهــا‬\n‫‪ ،‬ويف حــق املنكــر لقــوة جنبتــه فــإن األصــل بــراءة الذمــة‪ ،‬واملدعــي ههنــا‬\n‫( أي يف بــاب الشــاهد واليمــن ) قــد ظهــر صدقــه فوجــب أن تشـ ــرع‬\n                                 ‫اليمــن يف حقــه ) اهــ‪ .‬املغـ ــني ( ‪) 131/14‬‬\n‫‪ .4‬قــال ابــن القيــم ‪« :‬وليــس يف القــرآن مــا يقتضــي أنــه ال يحكــم إال‬\n‫بشــاهدين‪ ،‬أو شــاهد وامرأتــن فــإن اهلل ســبحانه إمنــا أمــر بذلــك‬\n‫أصحــاب احلقــوق أن يحفظــوا حقوقهــم بهــذا النصــاب ‪ ،‬ولــم يأمــر‬\n‫ا عــن أن يكــون قــد أمرهــم أال‬   ‫بذلــك احلــكام أن يحكمــوا بــه‪ ،‬فض ـ ً‬\n‫يقضــوا إال بذلــك ولهــذا يحكــم احلاكــم بالنكــول واليمــن املــردودة‬\n                                                                                     ‫‪118‬‬\n\f      ‫واملــرأة الواحــدة والنســاء املنفــردات ال رجــل معهــن ومبعاقــد القمــط‬\n      ‫ووجــوه اآلجــر وغيــر ذلــك مــن طــرق احلكــم التــي لــم تذكــر يف القــرآن‬\n      ‫‪ ....‬فطــرق احلكــم شــيء وطــرق حفــظ احلقــوق شــيء آخــر وليــس‬\n      ‫بينهمــا تــازم فتحفــظ احلقــوق مبــا ال يحكــم بــه احلاكــم ممــا يعلــم‬\n      ‫صاحــب احلــق أنــه يحفــظ بــه حقــه ‪ ،‬ويحكــم احلاكــم مبــا ال يحفــظ‬\n      ‫بــه صاحــب احلــق حقــه وال خطــر علــى بالــه مــن نكــول ورد ميــن وغيــر‬\n                                      ‫ذلــك ) أ ه ـ الطــرق احلكميــة ص (‪)145‬‬\n                  ‫‪ .5‬املادة اخلامسة واخلمسون من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم بعــد تبلغــه‬\n      ‫لشــخصه‪ ،‬أنــه اشــترى منــه ثالثــة رؤوس مــن األغنــام بثمــن إجمالــي‬\n      ‫قــدره ألفــان وســبعمائة وخمســون ريــاال ســلم منــه ثمامنائــة ريــال ولم يســلم‬\n      ‫املبلــغ املتبقــي وقــدره ألــف وتســعمائة وخمســون ريــاال وطلــب إلزامــه‬\n      ‫بتســليم مــا بقــي يف ذمتــه ‪،‬بطلــب البينــة مــن املدعــي علــى دعــواه أحضــر‬\n      ‫شــاهداً‪ ،‬ومت ســماع شــهادته وتعديلــه ‪،‬قــرر املدعــي أال بينــة لديــه ســوى‬\n      ‫الشــاهد ‪،‬بطلــب اليمــن مــن املدعــي املكملــة للشــاهد اســتعد ببذلهــا‪،‬‬\n      ‫ثــم حلفهــا ‪،‬مــن وســائل اإلثبــات التــي جــاءت بهــا الشــريعة اإلســامية‬\n      ‫القضــاء بالشــاهد وميــن الطالــب ‪،‬حديــث ابــن عبــاس رضــي اهلل عنــه‬\n      ‫(أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــاهد واليمــن ) رواه مســلم‬\n      ‫‪،‬أكثــر أهــل العلــم يــرون ثبــوت املــال ملدعيــه بشــاهد وميــن ‪،‬اليمــن‬\n      ‫تكــون يف جانــب أقــوى املتداعيــن‪ ،‬وأقــوى املتداعيــن يف هــذا البــاب‬\n      ‫هــو املدعــي لوجــود الشــاهد ‪،‬لــذ ثبتــت صحــة دعــوى املدعــي فيمــا‬\n\n‫‪119‬‬\n\f‫يدعيــه‪ ،‬واحلكــم غيابيــا بإلــزام املدعــى عليــه أن يســلم للمدعــي املبلــغ‬\n‫املدعــى بــه وقــدره ألــف وتســعمائة وخمســون ريــا ًال ‪ ،‬ســيتم إكمــال مــا‬\n‫يلــزم حيــال إبــاغ املدعــى عليــه باحلكــم ‪،‬بعــد رفــع احلكــم حملكمــة‬\n                                           ‫االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬املــازم القضائــي لــدى‬\n‫فضيلــة الشــيخ ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة بالريــاض‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n‫بالريــاض برقــم ‪ 33526762‬وتاريــخ ‪1433/8/14‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 331539887‬وتاريــخ ‪ 1433/08/14‬ه ـ ففــي يــوم االثنــن‬\n‫املوافــق‪ 1434/03/23‬ه ـ افتتحــت اجللســة الســاعة ‪ ، 08 : 15‬وفيهــا‬\n‫‪ ................‬ســعودي اجلنســية مبوجــب الســجل رقــم ‪ ............‬وادعــى‬\n‫ا يف دعــواه عليــه ‪:‬‬  ‫علــى الغائــب عــن مجلــس احلكــم ‪ ...............‬قائ ـ ً‬\n‫اننــي قــد بعــت علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم ثالثــة‬\n‫مــن االغنــام اثنــان منهــا مــن نــوع جنــدي واالخــر مــن نــوع املاعــز بقيمــة‬\n‫اجماليــة قدرهــا ألفــان وســبعمائة وخمســون ريــال وقــد ســلم لــي مبلغــا‬\n‫قــدره ثمامنائــة ريــال ولــم يســلم املبلــغ املتبقــي وقــدره الــف وتســعمائة‬\n‫وخمســون ريــال أطلــب إلزامــه بتســديد املتبقــي يف ذمتــه وقــدره الــف‬\n‫وتســعمائة وخمســون ريــال هــذه دعــواي ‪ ،‬وقــد ســبق لنــا طلــب املدعــى‬\n‫عليــه املذكــور ملقابلــة خصمــه شــرع ًا وتبلــغ باملواعيــد نظامي ـ ًا ولــم‬\n‫يحضــر كمــا يتضــح مــن مرفقــات املعاملــة وقــد وردنــا خطــاب محضــر‬\n‫اخلصــوم يف هــذه احملكمــة برقــم ‪331942529‬بتاريــخ ‪1433/11/2‬‬\n                                                                                       ‫‪120‬‬\n\f      ‫ه ـ واملتضمــن تبلــغ املدعــى عليــه لشــخصه وملــا ســبق واســتناد ًا علــى‬\n      ‫املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ونصهــا ‪ (:‬إذا‬\n      ‫غــاب املدعــى عليــه عــن اجللســة األولــى فيؤجــل النظــر يف القضيــة إلــى‬\n      ‫جلســة الحقــة يبلــغ بهــا املدعــى عليــه ‪ ،‬فــإن غــاب عــن هــذه اجللســة أو‬\n      ‫غــاب عــن جلســة أخــرى دون عــذر تقبلــه احملكمــة فتحكــم احملكمــة‬\n      ‫يف القضيــة ويعــد حكمهــا يف حــق املدعــى عليــه غيابي ـ ًا مــا لــم يكــن‬\n      ‫غيابــه بعــد قفــل بــاب املرافعــة يف القضيــة فيعــد احلكــم حضوريـ ًا ) ا‪.‬ه ـ‬\n      ‫‪،‬فلــذا قــررت الســير يف نظــر الدعــوى وطلبــت مــن املدعــي بينــة علــى‬\n      ‫صحــة مــا ادعــى بــه فأجــاب قائــا أنــه ليــس لــدي بينــة علــى البيعــة اال‬\n      ‫شــاهد واحــد فقــط وهــو هــذا احلاضــر وأطلــب ســماع شــهادته فأذنــت‬\n      ‫لــه فأحضــر للشــهادة ‪ .................‬ســعودي اجلنســية مبوجــب الســجل رقــم‬\n      ‫‪ ................‬ولــدى استشــهاده شــهد قائــا أشــهد هلل تعالــى أن للمدعــي‬\n      ‫يف ذمــة املدعــى عليــه ‪ ...............‬مبلغــا قــدره الــف وتســعمائة وخمســون‬\n      ‫ريــال وذلــك الباقــي مــن قيمــة االغنــام التــي باعهــا املدعــي للمدعــى‬\n      ‫عليــه هكــذا شــهد فجــرى تعديــل الشــاهد التعديــل الشــرعي مــن قبــل‬\n      ‫‪ ...............‬ســعودي اجلنســية مبوجــب الســجل رقــم ‪ ...............‬و‪..............‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل رقــم ‪ ...............‬مت طلبــت زيــادة بينــة‬\n      ‫مــن املدعــي فأجــاب قائــا أنــه ال بينــة لــدي ســوى هــذا الشــاهد فجــرى‬\n      ‫ا ‪ ( :‬واهلل‬   ‫طلــب اليمــن مــن املدعــي مــع الشــاهد فاســتعد وحلــف قائ ـ ً‬\n      ‫العظيــم أننــي قــد بعــت علــى املدعــى عليــه ‪ ...............‬ثالثــة مــن االغنــام‬\n      ‫مببلــغ قــدره الفــان وســبعمائة وخمســون وصــل منهــا مبلغــا قــدره ثمامنائــة‬\n      ‫ريــال والباقــي الــف وتســعمائة وخمســون لــم اســتلمها حتــى االن واهلل‬\n      ‫ـاء علــى مــا تقــدم وملــا كان مــن وســائل اإلثبــات التــي جــاءت‬   ‫العظيــم فبنـ ً‬\n\n‫‪121‬‬\n\f‫بهــا الشــريعة اإلســامية القضــاء بالشــاهد وميــن الطالــب ‪ ،‬وألن أكثــر‬\n‫أهــل العلــم يــرون ثبــوت املــال ملدعيــه بشــاهد وميــن فقــد روي ذلــك عــن‬\n‫ابــي بكــر وعمــر وعثمــان وعلــي رضــي اهلل عنهــم وهــو قــول الفقهــاء‬\n‫الســبعة وعمــر بــن عبدالعزيــز واحلســن وشــريح وايــاس وعبــداهلل بــن‬\n‫عتبــة وابــي ســلمة بــن عبدالرحمــن وربيعــة ومالــك وابــن أبــي ليلــى وابــي‬\n‫الزنــاد والشــافعي ‪ ،‬ودليــل ذلــك حديــث أبــي هريــرة قــال ( قضــى رســول‬\n‫اهلل صلــى اهلل عليــه وســلم باليمــن مــع الشــاهد الواحــد ) أخرجــه أبــو‬\n‫داود والترمــذي وابــن ماجــه والبيهقــي ‪ ،‬وحديــث ابــن عبــاس ( أن النبــي‬\n‫صلى اهلل عليه وســلم قضى بالشــاهد واليمني ) رواه مســلم يف صحيحه‬\n‫وقــال النســائي ‪ :‬اســناده جيــد ( انظــر حتفــة االشــراف ‪ ) 187/5‬وألن‬\n‫ا عــن ثبوتــه‬\n             ‫القضــاء بالشــاهد واليمــن موافــق ألصــول الشــريعة ‪ -‬فضـ ً‬\n‫بالدليــل ‪ -‬مــن حيــث أن اليمــن تكــون يف جانــب أقــوى املتداعيــن‪،‬‬\n‫وأقــوى املتداعيــن يف هــذا البــاب هــو املدعــي لوجــود الشــاهد ‪ ،‬قــال‬\n‫ابــن قدامــة ‪ ( :‬وألن اليمــن تشــرع يف حــق مــن ظهــر صدقــه وقــوي جانبــه‬\n‫ولذلــك شــرعت يف حــق صاحــب اليــد لقــوة جنبتــه بهــا ‪ ،‬ويف حــق املنكر‬\n‫لقــوة جنبتــه فــإن األصــل بــراءة الذمــة‪ ،‬واملدعــي ههنــا ( أي يف بــاب‬\n‫الشــاهد واليمــن ) قــد ظهــر صدقــه فوجــب أن تشـ ــرع اليمــن يف حقــه )‬\n‫أه ـ املغـ ــني ( ‪ ) 131/14‬وقــال ابــن القيــم ‪ ( :‬وليــس يف القــرآن مايقتضــي‬\n‫أنــه ال يحكــم إال بشــاهدين ‪ ،‬أو شــاهد وامرأتــن فــإن اهلل ســبحانه‬\n‫إمنــا أمــر بذلــك أصحــاب احلقــوق أن يحفظــوا حقوقهــم بهــذا النصــاب ‪،‬‬\n‫ا عــن أن يكــون قــد‬    ‫ولــم يأمــر بذلــك احلــكام أن يحكمــوا بــه ‪ ،‬فضـ ً‬\n‫أمرهــم أال يقضــوا اال بذلــك ولهــذا يحكــم احلاكــم بالنكــول واليمــن‬\n‫املــردودة واملــرأة الواحــدة والنســاء املنفــردات ال رجــل معهــن ومبعاقــد‬\n\n\n                                                                                    ‫‪122‬‬\n\f      ‫القمــط ووجــوه اآلجــر وغيــر ذلــك مــن طــرق احلكــم التــي لــم تذكــر يف‬\n      ‫القــرآن ‪ ....‬فطــرق احلكــم شــيء وطــرق حفــظ احلقــوق شــيء آخــر وليــس‬\n      ‫بينهمــا تــازم فتحفــظ احلقــوق مبــا ال يحكــم بــه احلاكــم ممــا يعلــم‬\n      ‫صاحــب احلــق أنــه يحفــظ بــه حقــه ‪ ،‬ويحكــم احلاكــم مبــا ال يحفــظ بــه‬\n      ‫صاحــب احلــق حقــه وال خطــر علــى بالــه مــن نكــول ورد ميــن وغيــر ذلــك)‬\n      ‫أ ه ـ (الطــرق احلكميــة ص (‪ )145‬وعلــى هــدى مــا تقــدم وحيــث ان‬\n      ‫املدعــي قــد تقــوى جانبــه فيمــا يتعلــق بدعــواه لــذا فقــد ثبــت لــدي صحــة‬\n      ‫دعــوى املدعــي فيمــا يدعيــه وحكمــت علــى املدعى عليــه ‪ ............‬غيابيا‬\n      ‫بــأن يدفــع للمدعــي املبلــغ املدعــى بــه وقــدره الــف وتســعمائة وخمســون‬\n      ‫ريــا ًال وبعــد ذلــك يخلــى ســبيله مــن هــذه الدعــوى وهــو علــى دعــواه متــى‬\n      ‫حضــر ‪ ،‬وبعرضــه علــى املدعــي قنــع باحلكــم وقــررت إكمــال مــا يلــزم‬\n      ‫حيــال إبــاغ املدعــى عليــه الغائــب باحلكــم حســب التعليمــات ‪ ،‬ثــم رفــع‬\n      ‫كامــل املعاملــة حــال اإلقتضــاء إلــى محكمــة االســتئناف لدراســة‬\n      ‫احلكــم وتدقيقــه حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم‬\n      ‫‪ 331539887‬وتاريــخ ‪1434/06/14‬ه ـ ملرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ .............‬املســجل برقــم ‪34171137‬‬\n                 ‫وتاريــخ ‪1434/3/24‬ه ـ اخلــاص بدعــوى ‪ ...........‬ضــد ‪...........‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه لــم يظهــر مــا يوجــب املالحظــة واهلل‬\n                                 ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n‫‪123‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":118,"source_page_end":123,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"019f6442e314277d373e4e04541c83862ca31ee141895833409794813dbf74ac","normalized_text_hash":"6bb345fb09e451b07144a2cd8cda5582636260f1a26f20300123d04274d9d014","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p118-34171137"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3d612890-9d0d-5caa-b947-0509fe28d663","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -ثمن مبيع -املطالبة بباقي ثمن سيارة -غياب املدعى عليه وتبلغه لشخصه -عدم وجود بينة للمدعي -تبلغ املدعى عليه","document_number":"3446843","case_number":"33381494","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة تبوك على املعاملة الواردة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/25","year":"1434","subject":"بيع -ثمن مبيع -املطالبة بباقي ثمن سيارة -غياب املدعى عليه وتبلغه لشخصه -عدم وجود بينة للمدعي -تبلغ املدعى عليه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/25 :‬هـ‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪3446843 :‬‬\n                  ‫َر ْق ُم الدعوى‪33381494 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34215742‬تاريخه‪1434/5/19 :‬هـ‬\n\n\n‫بيــع ‪ -‬ثمــن مبيــع ‪ -‬املطالبــة بباقــي ثمــن ســيارة ‪ -‬غيــاب املدعــى عليــه‬\n‫وتبلغــه لشــخصه ‪ -‬عــدم وجــود بينــة للمدعــي ‪ -‬تبلــغ املدعــى عليــه‬\n‫ال عــن‬\n      ‫بتوجــه اليمــن عليــه‪ -‬عــدم حضــور املدعــى عليــه يجعلــه نــاك ً‬\n‫أداء اليمــن ‪ -‬احلكــم علــى املدعــى عليــه بدفــع باقــي ثمــن الســيارة ‪-‬‬\n                                     ‫يعــد احلكــم حضوري ـ ًا يف مواجهتــه ‪.‬‬\n\n\n\n\n‫الالئحــة األولــى والرابعــة مــن املــادة (‪ )55‬والالئحــة الرابعــة مــن املــادة‬\n                                     ‫(‪ )109‬مــن نظــام املرافعــات الشــرعية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم‬\n‫واملتبلــغ لشــخصه أنــه اشــترى مــن موكلــه ســيارة مببلــغ أربعــة وعشــرين‬\n‫ألــف ريــال تســلم علــى أقســاط شــهرية مقــدار كل قســط ألــف ريــال ‪،‬‬\n‫وأن املدعــى عليــه ســدد مــن املبلــغ أربعــة عشــر ألــف ريــال وبقــي عشــرة‬\n‫آالف ريــال وطلــب إلزامــه بتســليمها ‪ ،‬بســؤال املدعــي عــن بينتــه علــى‬\n‫دعــواه‪ ،‬قــرر أنــه ال بينــة لديــه‪ ،‬وطلــب ميــن املدعــى عليــه علــى نفــي‬\n‫دعــواه‪ ،‬رفعــت اجللســة لتبليــغ املدعــى عليــه بتوجــه اليمــن عليــه وأنــه يف‬\n‫ال ‪ ،‬لــم يحضــر املدعــى عليــه وقــد تبلــغ‬\n                                            ‫حالــة عــدم حضــوره يعــد نــاك ً‬\n\n                                                                                      ‫‪68‬‬\n\f     ‫لشــخصه مبوعــد اجللســة‪ ،‬وأفهــم بتوجــه اليمــن عليــه بالدعــوى وذلــك‬\n     ‫مبوجــب إفــادة قســم احملضريــن ‪ ،‬عــدم وجــود بينــة للمدعــي وطلبــه‬\n     ‫ميــن خصمــه‪ ،‬وتبلــغ املدعــى عليــه بتوجــه اليمــن عليــه وعــدم حضــوره‬\n     ‫ألدائهــا وبنــاء علــى الالئحــة الرابعــة مــن املــادة (‪ )55‬واملــادة (‪ )109‬مــن‬\n     ‫ال عــن أداء اليمــن‪،‬‬  ‫نظــام املرافعــات الشــرعية يعــد املدعــى عليــه نــاك ً‬\n     ‫ثبــت أن بذمــة املدعــى عليــه للمدعــي أصالــة مبلــغ عشــرة آالف ريــال ومت‬\n     ‫احلكــم بإلزامــه بدفعهــا ‪ ،‬يعــد احلكــم حضوريـ ًا بحــق املدعــى عليــه ‪،‬‬\n                ‫بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫بتبــوك بنــاء علــى املعاملــة احملالــة إلـ َّـي مــن فضيلــة الرئيــس املســاعد‬\n     ‫برقم ‪ 33381494‬يف ‪1433/6/4‬هـ عليه حضر ‪ .........‬ســعودي اجلنســية‬\n     ‫ا عــن املدعــي ‪.........‬‬   ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬بصفتــه وكي ـ ً‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).............‬وذلــك مبوجــب‬\n     ‫وكالتــه الصــادرة مــن كتابــة العــدل الثانيــة بتبــوك برقــم ‪33159319‬‬\n     ‫وتاريــخ ‪1433/7/7‬ه ـ ولــم يحضــر املدعــى عليــه ‪ .................‬وقــد تبلــغ‬\n     ‫لشــخصه مبوعــد هــذه اجللســة وذلــك مبوجــب إفــادة مديــر قســم شــرطة‬\n     ‫احلمــراء برقــم ‪ 56/43/28‬وتاريــخ ‪1434/1/5‬ه ـ فلــذا وبنــاء علــى‬\n     ‫الالئحــة األولــى مــن املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n     ‫الشــرعية جــرى إفهــام املدعــي بــأن لــه أن تســمع دعــواه غيابيـ ًا ففهم ذلك‬\n     ‫ا لقــد بــاع موكلــي للمدعــى عليــه بتاريــخ ‪1429/4/21‬ه ـ‬          ‫وادعــى قائـ ً‬\n     ‫ســيارة نــوع ‪ ...‬صنــع عــام ‪2001‬م مببلــغ أربعــة وعشــرين ألــف ريــال‬\n\n‫‪69‬‬\n\f‫تســدد علــى أقســاط شــهرية مقــدار كل قســط ألــف ريــال تبــدأ بتاريــخ‬\n‫‪1429/4/25‬ه ـ وقــد ســدد املدعــى عليــه مبلــغ أربعــة عشــر ألــف ريــال‬\n‫وتبقــى مبلــغ عشــرة أالف ريــال لــم يســدد منهــا أي شــيء حتــى اآلن أطلــب‬\n‫إلزامــه بســدادها هــذه دعــواي وبســؤال املدعــي وكالــة إن كان لديــه‬\n‫ـدي وأطلــب ميــن املدعــى عليــه‬   ‫بينــة علــى دعــواه أجــاب بقولــه ال بينــة لـ ّ‬\n‫علــى نفــي الدعــوى هكــذا أجــاب وألجلــه رفعــت اجللســة وتأجلــت إلعادة‬\n‫تبليــغ املدعــى عليــه باحلضــور مــع إفهامــه بتوجيــه اليمــن عليــه بالدعــوى‬\n‫ال ويف جلســة أخــرى حضــر‬         ‫وأنــه يف حالــة عــدم حضــوره يعــد نــاك ً‬\n‫املدعــي وكالــة ولــم يحضــر املدعــى عليــه ‪ ...........‬وقــد تبلــغ لشــخصه‬\n‫مبوعــد هــذه اجللســة كمــا أفهــم بتوجــه اليمــن عليــه بالدعــوى وذلــك‬\n‫مبوجــب إفــادة قســم احملضريــن باحملكمــة برقــم ‪ 331053622‬يف‬\n‫‪1434/1/11‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى وعــدم وجــود بينــة‬\n‫للمدعــي وطلبــه ميــن خصمــه وملــا تبلــغ املدعــى عليــه بتوجــه اليمــن عليــه‬\n‫ولــم يحضــر ألدائهــا وبنــاء علــى الالئحــة الرابعــة مــن املــادة (‪ )55‬واملــادة‬\n‫ال عن‬ ‫(‪ )109‬مــن نظــام املرافعــات الشــرعية فــإن املدعــى عليــه يعــد ناك ً‬\n‫ـدي أن بذمــة املدعــى عليــه للمدعــي أصالــة‬     ‫أداء اليمــن لــذا فقــد ثبــت لـ َّ‬\n‫مبلــغ عشــرة آالف ريــال وألزمتــه بدفعهــا وبذلــك حكمــت ويعــد احلكــم‬\n‫حضوري ـ ًا بحــق املدعــى عليــه وســيتم نظــم صــك بذلــك وبعــث نســخة‬\n‫منــه للمدعــى عليــه لتمكينــه مــن االعتــراض مــع إفهامــه بــأن لــه مــدة‬\n‫ثالثــن يومـ ًا مــن تاريــخ اســتالم صــورة إعــام احلكــم لتقــدمي اعتراضــه‬\n‫فــإذا لــم يقــدم اعتراضــه خــال املــدة املقــررة ســقط حقــه يف االعتــراض‬\n‫واكتســب احلكــم الصفــة القطعيــة وللبيــان حــرر يف ‪1434/2/25‬ه ـ‬\n              ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n                                                                                          ‫‪70‬‬\n\f     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬فقــد اطلعن ــا نحــن‬\n     ‫قـض ــاة الدائ ــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة تبوك‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك‬\n     ‫املكلــف برقــم ‪ 331053622‬وتاريــخ ‪1434/4/14‬ه ـ املرفــق بهــا الصك‬\n     ‫الصــادر مــن فضيلــة الشــيخ ‪ .........‬وفقــه اهلل برقــم ‪3446843‬وتاريــخ‬\n     ‫‪1434/2/25‬ه ـ اخلــاص بدعــوى ‪ ...........‬ضــد ‪ .............‬وبدراســة الصــك‬\n     ‫وصــورة ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى احلكــم وبــاهلل‬\n                 ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪71‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":68,"source_page_end":71,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7324b680aee8eb8613cfcd9221b1196409aca573b079a60d6c91cc0e7f73e16d","normalized_text_hash":"95d390cc9cc7b6da2c387fe659f320dfa80bdd37867ddab8320d18455e00084b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p68-3446843"},{"id":"515e1346-3210-5b21-b4e9-0a0512e485cc","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع باآلجل لوحدة سكنية -طلب إلغاء البيع للعجز عن سداد باقي الثمن -معنى اللزوم يف العقود -عدم اتفاق إرادة املتعاقدين يف مجلس واحد -اختاف املتعاقدين يف تفسير بعض شروط العقد -مخالفه الشرط ملقصود العقد -وجوب رضا املتعاقدين يف اثبات العقد أو فسخه .","document_number":"33388994","case_number":"4520","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/21","year":"1434","subject":"بيع -بيع باآلجل لوحدة سكنية -طلب إلغاء البيع للعجز عن سداد باقي الثمن -معنى اللزوم يف العقود -عدم اتفاق إرادة املتعاقدين يف مجلس واحد -اختاف املتعاقدين يف تفسير بعض شروط العقد -مخالفه الشرط ملقصود العقد -وجوب رضا املتعاقدين يف اثبات العقد أو فسخه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/8/21 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33388994 :‬‬\n                        ‫َر ْق ُم الدعوى‪4520 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 33468477‬تاريخه‪1433/11/29 :‬هـ‬\n\n\n‫بيع ‪ -‬بيع باآلجل لوحدة ســكنية ‪ -‬طلب إلغاء البيع للعجز عن ســداد‬\n‫باقــي الثمــن ‪ -‬معنــى اللــزوم يف العقــود ‪ -‬عدم اتفاق إرادة املتعاقدين يف‬\n‫مجلــس واحــد ‪ -‬اختــاف املتعاقديــن يف تفســير بعــض شــروط العقــد‬\n‫‪ -‬مخالفــه الشــرط ملقصــود العقــد ‪ -‬وجــوب رضــا املتعاقديــن يف اثبــات‬\n                                                         ‫العقــد أو فســخه ‪.‬‬\n\n\n\n\n‫‪ -1‬العقــد الــازم هــو الــذي ال يقبــل الفســخ إال برضــا الطرفــن ‪.‬انظــر‪:‬‬\n                        ‫بدائــع الصنائــع للكاســاني رحمــه اهلل (‪.)299/5‬‬\n‫‪ -2‬قال الزركشي رحمه اهلل يف املنثور يف القواعد (‪( :)304/2‬الالزم‪:‬ما‬\n         ‫ال يقبل الفسخ ‪ ،‬أو ال ميكن للغير إبطاله ‪،‬و اجلائز عكسه ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى وكالــة بــأن املدعــى عليــه اشــترى مــن موكلــه وحــده‬\n‫ســكنيه مــن عمارتــه اململوكــة لــه مبوجــب صــك صــادر مــن كتابــة‬\n‫العــدل مببلــغ أربعمائــة وخمســن ألــف ريــال ‪ ،‬و أن املدعــى عليــه ســدد‬\n‫مائتــي ألــف ريــال وتبقــى مائتــان وخمســون ألــف ريــال تدفــع بعــد ســته‬\n‫أشــهر مــن تاريــخ العقــد ‪ ،‬حــل األجــل ولــم يســدد املدعــى عليــه هــذا املبلغ‬\n‫املتبقــي ملوكلــه ‪ ،‬أقــر املدعــى عليــه بالدعــوى ‪ ،‬قــرر املدعــى عليــه أنــه‬\n\n                                                                                       ‫‪72‬‬\n\f     ‫غيــر قــادر علــى الوفــاء يف الوقــت احلاضــر ورغــب يف إلغــاء البيــع وتســليم‬\n     ‫الوحــدة الســكنية للمدعــي بعــد تقديــر اجرتهــا للمــدة التــي بقــى فيهــا‬\n     ‫وحســمها مــن املبلــغ الــذي اســتلمه ‪ ،‬طلــب املدعــي وكالــة الرجــوع‬\n     ‫ملوكلــه ‪ ،‬يف جلســة أخــرى طلــب املدعــى عليــه امضــاء العقــد ‪ ،‬حضــر‬\n     ‫املدعــي أصالــه وطلــب فســخ العقــد ‪ ،‬جــرى االطــاع علــى صــك امللــك ‪،‬‬\n     ‫كمــا جــرى االطــاع علــى عقــد البيــع ورصــد مضمونــه ‪ ،‬حضــر احــد‬\n     ‫شــهود العقــد ورصــدت شــهادته ‪ ،‬اختلــف الطرفــان يف تفســير بعــض‬\n     ‫بنــود العقــد ‪ ،‬قــررت احملكمــة أن شــرط بقــاء املبيــع يف ملــك البائــع‬\n     ‫حلــن ســداد كامــل الثمــن شــرط فاســد ملخالفتــه ملقصــود البيــع ‪ ،‬صــدر‬\n     ‫احلكــم بــرد دعــوى املدعــي يف مطالبتــه بفســخ عقــد البيــع‪ ،‬احلكــم‬\n     ‫بصحــة عقــد البيــع ولزومــه ‪ ،‬جــرى افهــام املدعــي بــأن لــه مطالبــة‬\n     ‫املدعــى عليــه بدفــع مــا تبقــى مــن قيمــه املبيــع ‪ ،‬اعتــرض املدعــي علــى‬\n                           ‫احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .......‬القاضــي باحملكمــة العامة بالدمام‬\n     ‫ـاء علــى االوراق الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬    ‫بنـ ً‬\n     ‫بالدمــام برقــم ‪4520‬يف ‪1431/6/16‬ه ـ املقيــدة بهــذه احملكمــة برقــم‬\n     ‫‪ 31/18041‬يف ‪1431/6/16‬ه ـ حضــر ‪ .......‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪...‬بالوكالــة عــن ‪ .......‬مبوجــب الوكالــة الصــادرة‬\n     ‫مــن كتابــة عــدل محافظــة بلقرن برقــم ‪16‬يف‪1431/9/5‬هـ مجلد‪1642‬‬\n     ‫وحضــر حلضــوره ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقم‪.......‬‬\n     ‫وادعــى األول بقولــه‪ :‬بتاريــخ ‪2008/3/26‬م بــاع موكلــي علــى املدعــى‬\n\n‫‪73‬‬\n\f‫عليــه ‪...‬هــذا احلاضــر كامــل الوحــدة الســكنية رقــم(‪ )12‬مــن العمــارة‬\n‫املقامــة علــى قطعــة األرض رقــم(‪ )70‬مــن املخطــط رقــم ‪ 1/197‬بحــي‬\n‫املنــار بالدمــام العائــدة ملوكلــي مبوجــب الصــك الصــادر مــن كتابــة‬\n‫عــدل الدمــام االولــى برقــم‪339100401033‬يف ‪1426/11/26‬ه ـ بقيمــة‬\n‫قدرهــا اربعمائــة وخمســون الــف ريــال ســدد منهــا املدعــى عليــه عنــد‬\n‫العقــد مبلــغ وقــدره مائتــا ألــف ريــال علــى أن يســدد الباقــي وقــدره مائتان‬\n‫وخمســون ألــف ريــال بعــد مضــي ســتة أشــهر اعتبــار ًا مــن تاريــخ البيــع‬\n‫وقــد حــل موعــد الســداد ولــم يســدد املدعــى عليــه ملوكلــي مــن املتبقــي‬\n‫شــيئ ًا حتــى اآلن لــذا أطلــب إلــزام املدعــى عليــه بدفــع مائتــن وخمســن‬\n‫ألــف ريــال ملوكلــي هــذه دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه ‪:‬‬\n‫ا وأنــا‬‫مــا ذكــر املدعــي وكالــه يف دعــواه كلــه صحيــح جملـ ًة وتفصيـ ً‬\n‫غيــر قــادر علــى الوفــاء يف الوقــت احلاضــر وأرغــب يف إلغــاء البيــع وتســليم‬\n‫الوحــدة الســكنية ملــوكل املدعــي بعــد تقديــر اجرتهــا للمــدة التــي‬\n‫بقيــت فيهــا وحســمها مــن املبلــغ الــذي ملوكلــه وتســليمي املتبقــي هكــذا‬\n‫أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال أطلــب إمهالــي للرجــوع‬\n‫ملوكلــي لعــرض ذلــك عليــه وإفادتكــم هكــذا قــرر فأجيــب لطلبــه‬\n‫ورفعــت اجللســة لذلــك ثــم يف جلســة أخــرى حضــر املدعــي أصالــة ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر حلضــوره ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬بالوكالــة عــن ‪.......‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام الثانيــة برقــم‬\n‫‪ 60822‬يف ‪1431/2 1/30‬ه ـ جلــد ‪ 9149‬املخــول للوكيــل فيهــا حــق‬\n‫املطالبــة واملداعــاة واملخاصمــة وســماع الدعــاوي والــرد عليهــا وإقامــة‬\n‫البينــة والدفــع وقبــول احلكــم واالعتــراض عليــه يف أي دعــوى تقــام منــه‬\n\n\n                                                                                      ‫‪74‬‬\n\f     ‫أو ضــده وليــس فيهــا حــق اإلقــرار وقــد أعيــدت لنــا املعاملــة بخطــاب‬\n     ‫مأمــور قســم احملفوظــات باحملكمــة رقــم‪31 /18041‬يف‬\n     ‫‪1431/11/26‬ه ـ وقــال املدعــى أصالــة لقــد أخبرنــي وكيلــي الشــرعي‬\n     ‫‪ ...‬بــأن املدعــى عليــه ال يســتطيع ســداد باقــي القيمــة وأنــه يرغــب الغــاء‬\n     ‫ـاء عليــه وألنــه قــد تأخــر عــن ســداد الدفعــة الثانيــة عــن املوعــد‬\n                                                                             ‫البيــع وبنـ ً‬\n     ‫احملــدد وألن العقــد الــذي بيننــا قــد نــص علــى أن يتــم تســديد الدفعــة‬\n     ‫الثانيــة مــن القيمــة وقدرهــا مائتــان وخمســون ألــف ريــال بحــد أقصــى‬\n     ‫ســتة أشــهر مــن تاريــخ العقــد املبــرم يف ‪2008/6/8‬م لــذا أطلــب إلغــاء‬\n     ‫هــذا البيــع وإلــزام مــوكل املدعــى عليــه بتســليمي الشــقة املباعــة هكذا‬\n     ‫قــرر ثــم يف جلســة أخــرى حضــر املدعــي أصالــة ‪ .......‬وأبــرز صــك‬\n     ‫امللكية الصادر من كتابة عدل الدمام األولى برقم ‪630102010282‬‬\n     ‫يف ‪1430/7/13‬ه ـ املتضمــن متلكــه لقطعــة األرض رقــم (‪ )70‬مــن‬\n     ‫املخطــط رقــم (‪)1/791‬الواقــع بحــي الفــردوس بالدمــام واملذكــورة‬\n     ‫حدودهــا وأطوالهــا فيــه ومظهــر هــذا الصــك بتهميشــات تتضمــن انتقــال‬\n     ‫بعــض الشــقق آلخريــن كمــا أبــرز املدعــي العقــد الصادر من ‪...‬للتســويق‬\n     ‫العقــاري بتاريــخ ‪2008/3/26‬م املتضمــن بيــع ‪...‬الوحــدة الســكنية رقــم‬\n     ‫(‪ )12‬يف الــدور الرابــع مــن املبنــى املقــام علــى قطعــة األرض رقــم (‪)70‬‬\n     ‫مــن املخطــط رقــم ‪ 1/791‬بحــي املنــار بالدمــام علــى املدعــو ‪...‬بقيمــة‬\n     ‫قدرهــا أربعمائــة وخمســون الــف ريــال عنــد توقيــع العقــد والثانيــة متثــل‬\n     ‫مائتــان وخمســون الــف ريــال تدفــع بحــد أقصــى ســتة أشــهر مــن تاريــخ‬\n     ‫العقــد وقــد مت تســديد الدفعــة األولــى واإلفــراغ بعــد تكملــة املبلــغ وهــذا‬\n     ‫العقــد وفــق ســتة بنــود ومذيــل بتوقيــع كل مــن البائــع واملشــتري وتوقيــع‬\n     ‫الشــاهد ‪ .......‬وتوقيــع الشــاهد ‪ .......‬كمــا أحضــر املدعــي معــه ‪.......‬‬\n\n\n‫‪75‬‬\n\f‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬مــن مواليــد عــام ‪1399‬‬\n‫وبســؤاله عمــا لديــه قــال ‪:‬ال تربطنــي قرابــة باملدعــي ‪...‬وأشــهد هلل تعالــى‬\n‫أنــه بتاريــخ ‪2008/3/26‬م مت إبــرام عقــد بي ــع عقـ ــار مــن ‪ .......‬و‪ .......‬لدى‬\n‫مكتــب ‪...‬العقــاري باخلبــر حيــث بــاع ‪...‬املذكــور علــى ‪...‬املذكــور علــى‬\n‫‪ .......‬املذكــور كامــل الوحــدة الســكنية رقــم (‪ )12‬مــن الــدور الرابــع‬\n‫مــن املبنــى املقــام علــى قطعــة األرض رقم (‪ )70‬مــن املخطط رقم ‪1/197‬‬\n‫بحــي املنــار العائــدة ل‪ .......‬املذكــور مبوجــب الصــك الصــادر من كتابة‬\n‫الدمــام األولــى برقـ ــم ‪ 330104001933‬يف ‪1426/11/26‬ه ـ بقيمــة‬\n‫قدرهــا أربعمائــة وخمســون ألــف ريــال تســدد علــى دفعتني األولــى قدرها‬\n‫مائتــا ألــف ريــال وقــد ســددت عنــد العقــد والثانيــة قدرهــا مائتــان‬\n‫وخمســون ألــف ريــال تســدد بحــد أقصــى ســتة شــهور مــن تاريــخ العقــد‬\n‫وقــد مت حتريــر عقــد بذلــك ووقعــت عليــه بصفتــي شــاهد هــذا مــا لــدي‬\n‫وعليــه أوقــع هكــذا شــهد ثــم ســألت املدعــي عــن الشــاهد الثانــي يف‬\n‫العقــد فقــال أطلــب إمهالــي إلحضــاره يف اجللســة القادمــة ثــم يف جلســة‬\n‫أخــرى حضــر املدعــي أصالــة ‪ .......‬وســألته عــن الشــاهد الثانــي فقــال لــم‬\n‫أحضــره يف هــذه اجللســة وأطلــب إمهالــي ألمتكــن مــن إحضــاره وســماع‬\n‫مــا لديــه هكــذا قــرر وأجيــب لطلبــه ثــم يف جلســة أخــرى احلمــد هلل‬\n‫وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة بالدمــام‬\n‫حضــر املدعــي أصالــة ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪...‬وحضــر املدعــى عليــه وكالــة ‪ .......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫الدمــام الثانيــة الوكيــل عــن ‪ .......‬برقــم ‪ 27612‬وتاريــخ ‪1432/6/4‬ه ـ‬\n‫واملخــول لــه فيهــا حــق املطالبــة واملخاصمــة واملداعــاة وســماع الدعــاوي‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫والــرد عليهــا وإقامــة البينــة واإلقــرار والدفــع وقبــول احلكــم واالعتــراض‬\n     ‫عليــه وذلــك يف أي قضيــة تقــام منــي أو ضــدي أمــام أي محكمــة ويف أي‬\n     ‫جهــة وإنهــاء كافــة اإلجــراءات الشــرعية وجــرى تــاوة مــا ســبق ضبطــه‬\n     ‫مــن الدعــوى ومــا مت بعــد ذلــك فســألت املتداعيــن مبــا دون فصادقــا‬\n     ‫عليــه وطلبــا إكمــال الــازم والنظــر علــى ضوئــه ثــم يف جلســة أخــرى‬\n     ‫حضــر الطرفــان ويف هــذه اجللســة جــرى عــرض العقــد املوصــوف يف‬\n     ‫جلســة ســابقة لــدى القاضــي الســلف فقــرر بقولــه هــذا العقــد املتفــق‬\n     ‫عليــه بــن موكلــي وهــذا احلاضــر وهــي اتفاقيــة مــن ســبعة بنــود مــع‬\n     ‫متهيــد ســابق لهــا ثــم قــرر بقولــه إن موكلــي مســتعد بدفــع كامــل املبلــغ‬\n     ‫املتبقــي بشــيك مصــدق هكــذا قــرر وبعــرض ذلــك علــى املدعــي قــرر‬\n     ‫بقولــه أطلــب فســخ العقــد بيننــا ولســت راغــب يف إمضــاء البيــع مــع‬\n     ‫مــوكل هــذا احلاضــر هكــذا قــرر ثــم جــرى ســؤالهما عــن تفســير‬\n     ‫مقصودهمــا يف البنــد ثانيـ ًا واملتضمــن مــا نصــه ‪ ( :‬مــن املتفــق عليــه بــن‬\n     ‫ا مللكيــة الوحــدة إلى الطرف‬      ‫الطرفــن أن هنــا العقــد ال يعتبــر بيعـ ًا ناقـ ً‬\n     ‫الثانــي إال بعــد ســداد كامــل قيمــة الوحــدة إلــى الطــرف األول وإمتــام‬\n     ‫البيــع باإلفــراغ لصالــح الطــرف الثانــي لــدى كاتــب عــدل ) فاســتعد‬\n     ‫كل طــرف منهمــا يف اجللســة القادمــة تقــدمي تفســير ملقصودهمــا لــذا‬\n     ‫فقــد رفعــت اجللســة ثــم يف جلســة أخــرى حضــر املدعــي واملدعــى عليــه‬\n     ‫وكالــة وقــدم املدعــي ورقــة لتفســير البنــد الثانــي مــن العقــد نصهــا مــا‬\n     ‫يلــي ‪ ( :‬أمــا عــن تفســير البنــد الثانــي مــن العقــد فهــو أن املبايعــة تلغــى يف‬\n     ‫حــال عــدم قيــام املشــتري بســداد كامــل قيمــة الشــقة خــال ســتة أشــهر‬\n     ‫وأن ال حجيــة لهــذا العقــد اال بعــد إفــراغ الشــقة للمشــتري لــدى كتابــة‬\n     ‫العــدل أي أن العقــد ال يعتــد بــه إذا لــم يتبــع باإلفــراغ لــدى كتابــة العــدل‬\n\n\n‫‪77‬‬\n\f‫وهــذا البنــد يلــزم البائــع إفــراغ الشــقة للمشــتري عنــد كتابــة العــدل بعــد‬\n‫ســداد املبلــغ يف الســتة أشــهر التاليــة لتوقيــع العقــد ويلــزم املشــتري إعــادة‬\n‫الشــقة إلــى صاحبهــا يف حــال عــدم دفعــه للمبلــغ يف املــدة املشــار لهــا‬\n‫وهــذا مــا أطلبــه ‪ .‬االســم ‪ .......‬توقيعــه‪ ).......‬ثــم قــرر املدعــي بقولــه هــذا‬\n‫مــا لــدي مــن تفســير للمــادة املشــار إليهــا يف العقــد واالتفاقيــة وقــد‬\n‫كتبــت هــذا التفســير بعــد مراجعــة املكتــب الــذي أجــرى العقــد بيننــا‬\n‫هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــرر بقولــه إن‬\n‫هــذا التفســير الــذي ذكــره املدعــي غيــر صحيــح وإمنــا الصحيــح ســآتي‬\n‫بــه يف اجللســة املقبلــة أطلــب إمهالــي إلحضــاره هكــذا قــرر ثــم يف جلســة‬\n‫أخــرى حضــر الطرفــان وقــدم املدعــى عليــه وكالــة ورقــة نــص احلاجــة‬\n‫منهــا مــا يلــي‪ ( :‬بخصــوص طلــب تفســير البنــد الثانــي يف العقــد املبــرم‬\n‫بني ‪ .......‬وموكلي ‪ .......‬أفيد فضيلتكم بأن ــه مفسر يف البند اخلامس‬\n‫مــن نفــس العقــد ) ‪.‬اه ـ ‪ .‬وبالرجــوع إلــى البنــد اخلامــس والــذي نصــه مــا‬\n‫يلــي ‪ ( :‬ال يحــق للطــرف الثانــي التصــرف يف الوحــدة موضــوع هــذا العقد‬\n‫بــأي تصــرف ناقــل امللكيــة إال بعــد ســداد كامــل قيمتهــا وإفراغهــا لــه‬\n‫ا أي تصــرف قبــل اإلفــراغ واحليــازة‬    ‫وامتالكهــا امللــك التــام ويعــد باط ـ ً‬\n‫وتعتبــر الشــقة يف ملــك الطــرف األول حلــن ســداد كامــل قيمتهــا‬\n‫وتســليمها للطــرف الثانــي ) ‪.‬اه ـ ‪ .‬وبعرضــه علــى املدعــي قــرر بقولــه‬\n‫ســبق وأن فســرت املــادة ومــا ذكــره مــن تفســير فهــو راجــع للبنــد الثالــث‬\n‫هكــذا قــرر ثــم جــرى ســؤال اخلصمــن ألديكــم إضافــة علــى مــا تقــدم‬\n‫فأجــاب كل واحــد منهمــا أن ال مزيــد علــى مــا قدمنــا هكــذا قــررا‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق الطرفــان على‬         ‫فبنـ ً‬\n‫صحــة البيــع بينهمــا ودفــع املشــتري أكثــر مــن ثلــث املبلــغ ودخــل املبيــع‬\n\n\n                                                                                            ‫‪78‬‬\n\f     ‫يف حيــازة املشــتري ومبــا أن املدعــي عــدل عــن املطالبــة باملبلــغ املتبقــي‬\n     ‫إلــى طلــب فســخ العقــد ومبــا أن عقــد البيــع عقــد الزم ال يفســخ إال برضــا‬\n     ‫الطرفــن واختيارهمــا وال ينفــرد بــه أحدهمــا دون رضــا اآلخــر واللــزوم‬\n     ‫كمــا يف تعبيــرات الفقهــاء هــو الــذي ال يقبــل الفســخ جــاء يف بدائــع‬\n     ‫الصنائــع للكاســاني رحمــه اهلل ( ‪ ( : ) 299/5‬والعقــد الــازم ‪ :‬ال‬\n     ‫يحتمــل الفســخ ) كمــا جــاء يف املنثــور يف القواعــد للزركشــي رحمــة‬\n     ‫اهلل ( ‪ ( : ) 304 /2‬الــازم‪ :‬مــاال يقبــل الفســخ ‪ ،‬أو ال ميكــن الغيــر‬\n     ‫إبطالــه ‪ ،‬واجلائــز عكســه )‪ .‬ومــا ذكــره املدعــى عليــه أصالــة مــن‬\n     ‫رغبتــه بإقالتــه مــن البيــع يف أول اجللســات فاإلقالــة رفــع عقــد الزم ‪،‬‬\n     ‫فالبــد مــن رضــى الطرفــن ‪ ،‬وكمــا يشــترط الرضــا يف إثبــات العقــد‬\n     ‫ـاء عليــه فإنــه يشــترط احتــاد املجلــس لرفع‬   ‫كذلــك يشــترط يف رفعــه وبنـ ً‬\n     ‫العقــد باإلقالــة كمــا يشــترط إلثباتــه ‪ ،‬ألن معنــى العقــد موجــود فيهــا‬\n     ‫وحيــث لــم تتفــق اإلرادتــن يف مجلــس واحــد واختلفــت فيمــا بعــد ومبــا أن‬\n     ‫الطرفــن قــد اختلفــا يف تفســير البنــد الثانــي وظاهــر البنــد أنــه ال يعتبــر‬\n     ‫بيع ـ ًا ويؤكــده مــا جــاء يف آخــر البنــد اخلامــس حيــث جــاء مــا نصــه‬\n     ‫(تعتبــر الشــقة يف ملــك الطــرف األول حلــن ســداد كل قيمتها وتســليهما‬\n     ‫للطــرف الثانــي ) وال شــك أن هــذا شــرط مخالــف ملقصــود البيــع فهــو‬\n     ‫مــن الشــروط الفاســدة وال يعتــد بــه لذلــك كلــه فقــد رددت دعــوى‬\n     ‫املدعــي يف مطالبتــه فســخ العقــد وحكمــت بصحــة العقــد ولزومــه‬\n     ‫وأفهمتــه بــأن لــه مطالبــة املدعــى عليــه يف بقيــة املبلــغ وبعــرض احلكــم‬\n     ‫علــى الطرفــن قــرر املدعــي عــدم قناعتــه بــه وقــرر املدعــى عليــه القناعــة‬\n     ‫وطلــب املدعــي االســتئناف فأفهــم بــأن مــدة االعتــراض ثالثــون يوم ـ ًا‬\n     ‫تبــدأ بعــد مهلــة تنظيــم الصــك خمســة أيــام إذا مضــت املــدة ولــم يقــدم‬\n\n\n‫‪79‬‬\n\f‫الئحــة اعتراضيــة ســقط حقــه يف طلــب االســتئناف ولــه املراجعــة خــال‬\n‫املهلــة واملــدة النظاميــة الســتالم نســخة احلكــم لالعتــراض عليــه وبــاهلل‬\n‫التوفيــق وختمــت اجللســة يف متــام الســاعة احلاديــة عشــرة‪،‬وصلى اهلل‬\n   ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1433/08/10‬هـ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ .......‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى‬\n‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام املســاعد برقــم‬\n‫‪ 33/2232006‬وتاريــخ ‪1434/2/3‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34/305521‬وتاريــخ ‪1434/2/3‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ .......‬املســجل برقــم ‪33388994‬‬\n‫وتاريــخ ‪1433/8/21‬ه ـ اخلــاص بدعــوى ‪ .......‬ضــد ‪ .......‬يف قضيــة‬\n‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ ،‬ولبيانــه‬\n                                                                  ‫املعاملــة ّ‬\n                          ‫حــرر يف ‪1434/3/9‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                   ‫‪80‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":72,"source_page_end":80,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8f27134aec2524b46d6227d4319d1db24109b2e9877b28eda80040e6e3ee30e1","normalized_text_hash":"c006a4c860cc810c567d6ba4abc87336e32508c0525b44581271e8c45a50a5c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p72-33388994"},{"id":"1ad11f21-e5ab-53ca-ba03-b7d8cf549bd3","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة -فسخ البيع أو رد ثمن السيارة لعيب فيها -تقدير العيب عن طريق قسم اخلبراء -العيب يوجب إما اإلمساك أو الفسخ -احلكم بفسخ البيع ورد ثمن املبيع .","document_number":"33439017","case_number":"33405137","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة وبتعميد فضيلته لي بنظر هذه القضية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/25","year":"1434","subject":"بيع -بيع سيارة -فسخ البيع أو رد ثمن السيارة لعيب فيها -تقدير العيب عن طريق قسم اخلبراء -العيب يوجب إما اإلمساك أو الفسخ -احلكم بفسخ البيع ورد ثمن املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/10/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33439017 :‬‬\n                         ‫َر ْق ُم الدعوى‪33405137 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34241289‬تاريخه‪1434/6/14 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع ســيارة ‪ -‬فســخ البيــع أو رد ثمــن الســيارة لعيــب فيهــا ‪ -‬تقديــر‬\n      ‫العيــب عــن طريــق قســم اخلبــراء ‪ -‬العيــب يوجــب إمــا اإلمســاك أو‬\n                               ‫الفســخ ‪ -‬احلكــم بفســخ البيــع ورد ثمــن املبيــع ‪.‬‬\n\n\n\n\n      ‫‪ .1‬ذكــر صاحــب املقنــع (‪ )44/2‬مــا نصــه‪ « :‬فمــن اشــترى معيبــا لــم‬\n                                 ‫يعلــم عيبــه فلــه اخليــار بــن الــرد واإلمســاك»‪.‬‬\n      ‫‪ .2‬ذكــر ابــن قدامــة يف املغنــي (‪ )522/6‬مــا نصــه‪« :‬أنــه متــى علم باملبيع‬\n      ‫عيبـ ًا لــم يكــن عاملـ ًا بــه فلــه اخليــار بــن اإلمســاك والفســخ ســواء كان‬\n                                        ‫البائــع علــم بالعيــب وكتمــه أو لــم يعلــم»‪.‬‬\n      ‫‪ .3‬مــا روي عــن النبــي صلــى اهلل عليــه وســلم أنــه اشــترى مملوكا فكتب‬\n      ‫(هــذا مــا اشــترى محمــد بــن عبــداهلل مــن العــداء بــن خالــد اشــترى منــه‬\n                             ‫عبــدا أو أمــة الداء بــه وال غائلــة بيــع املســلم واملســلم)‬\n      ‫‪ .4‬ذكر الزحيلي يف الفقه اإلسالمي وأدلته (‪ )261/4‬ما نصه‪« :‬يثبت‬\n      ‫خيــار العيــب متــى ظهــر العيــب ولــو بعــد العقــد بزمــن طويــل ويقــول‬\n      ‫أيضــا «وإذا لــم تتوافــر الســامة لــم يتحقــق أيض ـ ًا مبــدأ التعــادل يف‬\n      ‫التبــادل الــذي تقــوم عليــه عقــود املعاوضــات فشــرع هــذا اخليــار حفاظــا‬\n      ‫علــى مبــدأ املســاواة وقــد أثبــت الشــرع هــذا اخليــار ملــن فوجــئ بالعيــب‬\n      ‫بأحاديــث نبويــة متعــددة منهــا (املســلم أخــو املســلم) (ال يحــل ملســلم باع‬\n      ‫مــن أخيــه بيع ـ ًا وفيــه عيــب إال بينــه) وقولــه‪( :‬مــن غشــنا فليــس منــا)‬\n‫‪81‬‬\n\f‫وقــال أيضــا «وممــا يثبــت فيــه اخليــار مــا كان محــل العقد عينــا معينة‬\n    ‫أو مشــخصة مــن األعيــان كمــا األرض والــدار والدابــة والســيارة»‬\n                             ‫‪ .5‬املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن الشــركة املدعــى عليهــا ســيارة جديــدة‬\n‫موصوفــة يف الدعــوى وبعــد اســتخدامه لهــا ظهــر فيهــا عيــوب مصنعيــة‬\n‫مذكــورة يف دعــواه‪ ،‬ولــذا طلــب إلــزام املدعــى عليهــا باســتالم الســيارة‬\n‫وتســليمه قيمتهــا ‪ ،‬أنكــر وكيــل املدعــى عليهــا مــا جــاء يف الدعــوى‬\n‫ودفــع بــأن الضمــان ال يخــول للمدعــي تغييــر الســيارة وإمنــا تصليــح‬\n‫األعطــال الناجتــة عــن خلــل يف التصنيــع أو اســتبدال القطعــة إذا تعــذر‬\n‫إصالحهــا ‪ ،‬قــررت احملكمــة تكليــف اخلبــراء بفحــص الســيارة وتقــدمي‬\n‫تقريــر عــن ســبب اخللــل فيهــا فأفــادوا بوجــود عيــب يف احملــرك وأنــه‬\n‫ال يوجــد ســوء اســتخدام للســيارة ‪ ،‬متــى علــم املشــتري باملبيــع عيبــا‬\n‫لــم يكــن عاملــا بــه فلــه اخليــار بــن اإلمســاك والفســخ ســواء كان‬\n‫البائــع علــم بالعيــب وكتمــه أو لــم يعلــم ‪ ،‬قضــت احملكمــة بفســخ‬\n‫عقــد بيــع الســيارة املذكــورة كمــا حكمــت علــى الشــركة املدعــى‬\n‫عليهــا بإعــادة كامــل ثمــن الســيارة إلــى املدعــي‪ ،‬قنــع املدعــي باحلكــم‬\n‫وعارضــت عليــه املدعــى عليهــا ‪ ،‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                 ‫علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪82‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n     ‫أنــا (‪ )....‬املــازم القضائــي لــدى فضيلــة الشــيخ (‪ )........‬القاضــي يف‬\n     ‫احملكمــة العامــة ببريــدة وبتعميــد فضيلتــه لــي بنظــر هــذه القضيــة‬\n     ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n                                                                               ‫وبنـ ً‬\n     ‫ببريــدة املســاعد برقــم ‪ 33405137‬وتاريخ‪1433/6/16‬ه ـ واملقيــدة يف‬\n     ‫احملكمــة برقــم ‪ 331128692‬وتاريــخ ‪1433/6/16‬ه ـ ففــي هــذا اليــوم‬\n     ‫االثنــن املوافــق ‪1433/6/30‬ه ـ ويف الســاعة الثامنــة والنصــف صباحـ ًا‬\n     ‫افتتحــت اجللســة وفيهــا حضــر (‪ )........‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم (‪ )........‬ولــم يحضــر املدعى عليه شــركة (‪ )........‬للســيارات‬\n     ‫وباالطــاع علــى ورقــة التبليــغ املؤرخــة ب ـ ‪1433/6/16‬ه ـ تبــن أنــه مت‬\n     ‫ـاء علــى املــادة (‪ )55‬مــن‬\n                                ‫التبليــغ عــن طريــق ســكرتارية الشــركة وبنـ ً‬\n     ‫نظــام املرافعــات الشــرعية فقــد جــرى رفــع هــذه اجللســة إلعــادة التبليــغ‬\n     ‫مرة أخرى ويف هذا اليوم الســبت املوافق ‪1433/7/5‬هـ افتتحت اجللســة‬\n     ‫وفيهــا حضــر املدعــي وحضــر حلضــوره (‪ )........‬ســعودي اجلنســية مبوجــب‬\n     ‫ا عــن املدعــى عليــه مبوجــب‬  ‫الســجل املدنــي رقــم (‪ )........‬بصفتــه وكيـ ً‬\n     ‫الوكالة رقم ‪ 12152‬وتاريخ ‪1428/2/27‬هـ الصادرة من كتابة عدل‬\n     ‫ا أننــي اشــتريت‬  ‫الدمــام الثانيــة وبســؤال املدعــي عــن دعــواه أجــاب قائـ ً‬\n     ‫ســيارة جديــدة مــن شــركة (‪ )........‬للســيارات مــن نــوع (‪ )........‬موديــل‬\n     ‫(‪ )........‬ولكــن انتبهــت للزيــت بعــد مســافة ‪25000‬كــم ولــم أخبــر عــن‬\n     ‫نقصــه أثنــاء تغييــره عندهــم وكنــت متابــع للصيانــة عندهــم ففوجئــت‬\n     ‫بــأن الزيــت ينقــص مــن املاكينــة وأخبرتهــم ومت فحصهــا مــع وجــود‬\n\n‫‪83‬‬\n\f‫علــة أخــرى وهــي صــوت قــوي داخــل املاكينــة ثــم قامــوا بإصالحهــا‬\n‫وأخبرونــي أن الزيــت رمبــا مــن هــذه املشــكلة ولكنهــا اســتمرت‬\n‫وراجعتهــم مــرة أخــرى ثــم حجزوهــا عندهــم ثــم أخبرونــي بجاهزيتهــا‬\n‫وبعــد ذلــك راجعتهــم للمــرة الثالثــة فأخبرونــي أنهــا حتتــاج إلــى توضيــب‬\n‫ولــم يبلــغ مشــيها ‪ 50000‬ألــف كــم وطالبتهــم بعــدم توضيــب املاكينــة‬\n‫ألن التوضيــب يؤثــر علــى قيمــة الســيارة وأنــا أدعــي الغــن يف الســيارة‬\n‫وطلبــي يف هــذه الدعــوى إلــزام املدعــى عليــه بإعطائــي ســيارة جديــدة‬\n‫بــدل احلاليــة وإعطائــي ضمــان كامــل وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه وكالــة أجــاب بــأن الضمــان ال يخــول للمدعــي تغييــر الســيارة وإمنــا‬\n‫تصليــح األعطــال الناجتــة عــن خلــل يف التصنيــع وإذا جتــاوزت نســبة‬\n‫التصليــح ‪ 80‬باملئــة مــن القطعــة فــإن القطعــة تغيــر بالكامــل وال تغيــر‬\n‫الســيارة هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة وحيــث األمــر‬\n‫مــا ذكــر فقــد قــررت الكتابــة إلــى كليــة التقنيــة بعنيــزة لتزويدنــا‬\n‫بتقريــر عــن ســبب اخللــل يف الســيارة وحتــى ورود الــرد منهــم فقــد‬\n‫رفعــت اجللســة ويف يــوم األثنــن ‪1433/9/18‬ه ـ افتتحــت اجللســة لــدي‬\n‫أنــا (‪ )........‬القاضــي يف احملكمــة العامــة ببريــدة نظــر ًا النتقــال املــازم‬\n‫(‪ )........‬عــن هــذا املكتــب وفيهــا حضــر الطرفــان وقــد ســبق أن كتبنــا‬\n‫للكليــة التقنيــة بخطابنــا رقــم ‪ 33/1254617‬يف ‪1433/7/5‬ه ـ فوردنــا‬\n‫خطابهــم رقــم ‪ 346‬يف ‪1433/8/5‬ه ـ املتضمــن أن اللجنــة املشــكلة مــن‬\n‫قســم التقنيــة امليكانيكيــة لفحــص الســيارة أفــادت أنــه ال يوجــد هناك‬\n‫ســوء اســتخدام للســيارة كمــا هــو مرفــق بالتقريــر وبعــرض ذلــك علــى‬\n‫املدعــى عليــه وكالــة أجــاب أطلــب نســخة مــن هــذا التقريــر لعرضــه‬\n‫علــى الشــركة وحيــث ال مانــع لــذا فقــد جــرى تزويــده بنســخة منــه كما‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫جــرى ســؤال املدعــي عــن طلبــه فأجــاب بأنــه مــادام أن هــذا عيــب فأنــا‬\n     ‫أطالــب بــرد الســيارة وتســليمي قيمتهــا وقــدره مائــة وســتة وأربعــون ألــف‬\n     ‫ريــال هكــذا أجــاب كمــا جــرى ســؤال املدعــى عليــه وكالــة عــن دعوى‬\n     ‫املدعــي بشــأن شــراء الســيارة فقــال إن مــا ذكــره املدعــي يف دعــواه مــن‬\n     ‫شــرائه الســيارة نوعهــا (‪ )........‬موديــل (‪ )........‬صحيــح هكــذا أجــاب ‪،‬‬\n     ‫لذا جرى رفع اجللسة ويف يوم األربعاء ‪1433/10/25‬هـ افتتحت اجللسة‬\n     ‫وفيهــا حضــر الطرفــان وقــد جــرى ســؤالهما هــل لديكمــا إضافــة فأفــاد‬\n     ‫املدعــى عليــه وكالــة بــأن الكفالــة احملــدودة للســيارات اجلديــدة تشــمل‬\n     ‫الكفالــة التصليحــات الالزمــة لتصحيــح األعطــال التــي حتــدث أثنــاء‬\n     ‫مــدة الكفالــة والناجتــة عــن ســوء يف التصنيــع أو املــواد املســتعملة ســيتم‬\n     ‫إجــراء أيــة عمليــة ضبــط الزمــة أثنــاء مــدة الكفالــة ســيتم اســتعمال‬\n     ‫قطــع جديــدة أو قطــع معــاد تصنيعهــا وبعــرض ذلــك علــى املدعــي أجــاب‬\n     ‫بــأن العيــب ليــس مــن ســوء االســتعمال بــل مــن جدهــا وهــو فيهــا العيــب‬\n     ‫وقــد مت إصالحهــا مــن قبلهــم ولــم تتغيــر هكــذا أجــاب فبنــاء علــى مــا‬\n     ‫تقــدم مــن الدعــوى واإلجابــة واالطــاع علــى قــرار اللجنــة املشــكلة يف‬\n     ‫الكليــة التقنيــة وبعــد االطــاع علــى وثيقــة ملكيــة الســيارة ومبــا أن‬\n     ‫املدعــي يطالــب بــرد الســيارة وتســليمه ثمنهــا واســتنادا ملــا قــرره الفقهــاء‬\n     ‫رحمهــم اهلل يف مضانــه ومنهــم مــا ذكــره صاحــب املقنــع يف اجلــزء الثاني‬\n     ‫صحيفــة (‪ )44‬مــا نصــه فمــن اشــترى معيبــا لــم يعلــم عيبــه فلــه اخليــار بــن‬\n     ‫الــرد واإلمســاك وذكــر ابــن قدامــة يف املغنــي اجلــزء الســادس صحيفــة‬\n     ‫(‪ )522‬مــا نصــه «أنــه متــى علــم باملبيــع عيبــا لــم يكــن عاملــا بــه فلــه‬\n     ‫اخليــار بــن اإلمســاك والفســخ ســواء كان البائــع علــم بالعيــب وكتمــه‬\n     ‫أو لــم يعلــم ال نعلــم بــن أهــل العلــم خالفــا وإثبــات النبــي صلــى اهلل عليــه‬\n\n\n‫‪85‬‬\n\f‫وســلم للتصريــة تنبيــه علــى ثبوتــه بالعيــب وألن مطلــق العقــد يقتضــي‬\n‫الســامة مــن العيــب بدليــل مــا روي عــن النبــي صلــى اهلل عليــه وســلم‬\n‫أنــه اشــترى مملــوكا فكتــب (هــذا مــا اشــترى محمــد بــن عبــداهلل مــن‬\n‫العــداء بــن خالــد اشــترى منــه عبــدا أو أمــة الداء بــه وال غائلــة بيــع املســلم‬\n‫املســلم) فثبــت أن بيــع املســلم اقتضــى الســامة وألن األصــل الســامة‬\n‫والعيــب حــادث أو مخالــف للظاهــر فعنــد اإلطــاق يحمــل عليهــا فمتــى‬\n‫فاتــت فــات بعــض مقتضــى العقــد فلــم يلزمــه أخــذه بالعــوض وكان‬\n‫لــه الــرد وأخــذ الثمــن كامــا وذكــر الزحيلــي يف الفقــه اإلســامي‬\n‫وأدلتــه اجلــزء الرابــع صحيفــة (‪ )261‬مــا نصــه «يثبــت خيــار العيــب متــى‬\n‫ظهــر العيــب ولــو بعــد العقــد بزمــن طويــل ويقــول أيضــا «وإذا لــم تتوافــر‬\n‫الســامة لــم يتحقــق أيض ـ ًا مبــدأ التعــادل يف التبــادل الــذي تقــوم عليــه‬\n‫عقــود املعاوضــات فشــرع هــذا اخليــار حفاظــا علــى مبــدأ املســاواة وقــد‬\n‫أثبــت الشــرع هــذا اخليــار ملــن فوجــئ بالعيــب بأحاديــث نبويــة متعــددة‬\n‫منهــا (املســلم أخــو املســلم) (ال يحــل ملســلم بــاع مــن أخيــه بيعـ ًا وفيــه عيــب‬\n‫إال بينــه) وقولــه‪( :‬مــن غشــنا فليــس منــا) وقــال أيضــا «وممــا يثبــت فيــه‬\n‫اخليــار مــا كان محــل العقــد عينــا معينــة أو مشــخصة مــن األعيــان كمــا‬\n‫األرض والــدار والدابــة والســيارة ‪. « ....‬ملــا ســبق كلــه فقــد فســخت‬\n‫عقــد بيــع الســيارة املذكــورة وأن علــى شــركة مــوكل املدعــى عليــه‬\n‫إعــادة كامــل ثمــن الســيارة املذكــورة وقــدره مائــة وســتة وأربعــون ألــف‬\n‫ريــال وبــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫وكالــة عــدم القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة فأجبــت‬\n‫لطلبــه وســيتم تزويــده بنســخه مــن احلكــم وبــاهلل التوفيــق وصلــى اهلل‬\n                         ‫وســلم علــى نبيينــا محمــد حــرر يف ‪1433/10/25‬ه ـ‬\n\n\n                                                                                            ‫‪86‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n     ‫يــوم الثالثــاء ‪1434/5/21‬ه ـ افتتحــت اجللســة وقــد وردتنــا املعاملــة‬\n     ‫مــن محكمــة االســتئناف بالقصيــم رفــق خطــاب فضيلــة رئيســها‬\n     ‫رقــم ‪ 332205449‬يف ‪1434/1/24‬ه ـ واملقيــدة برقــم ‪ 34232737‬يف‬\n     ‫‪1434/1/27‬ه ـ مالحظـ ًا علــى احلكــم الصــادر منــي برقــم ‪33439017‬‬\n     ‫يف ‪1433/10/25‬ه ـ مبوجــب القــرار رقم ‪ 3414819‬يف ‪1434/1/18‬هـ‬\n     ‫املتضمــن أنــه «وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة لوحــظ مــا يلــي أوال‪ :‬أن تقريــر اللجنــة املشــكلة مــن‬\n     ‫قســم التقنيــة امليكانيكيــة بكليــة التنقيــة مبحافظــة عنيــزة الــذي‬\n     ‫اســتند عليــه فضيلــة القاضــي يف حكمــه لــم يذكــر فيــه أن العيــب‬\n     ‫املوجــود بالســيارة مصنعــي وال بــد مــن التصريــح بذلــك إضافــة إلــى أن‬\n     ‫هــذا التقريــر لــم يوقــع مــن أعضــاء اللجنــة التــي قامت بإعــداده وال بد من‬\n     ‫ذلــك ثاني ـاً‪ :‬لــم يســأل فضيلتــه ويناقــش املدعــي متــى اكتشــف العيــب‬\n     ‫الــذي يدعيــه بالســيارة وســؤال املدعــى عليــه وكالة عما ذكــره املدعي‬\n     ‫مــن متابعتــه الصيانــة للســيارة لــدى الشــركة وتدويــن ذلــك يف الضبــط‬\n     ‫والصــك ثالثـاً‪ :‬صــورة وكالــة املدعــى عليــه لــم توثــق مبطابقتهــا ألصلهــا‬\n     ‫رابعـاً‪ :‬حكــم فضيلتــه بفســخ عقــد الســيارة علــى أن الفســخ يكــون مــن‬\n     ‫املدعــي طالــب الــرد حســب مــا ذكــره العلمــاء وكان علــى فضيلتــه أن‬\n     ‫يعــرض ذلــك علــى املدعــي ثــم يحكــم بثبــوت الفســخ متــى ظهــر موجبــه‬\n     ‫« وعليــه أجيــب أصحــاب الفضيلــة بأنــه جــرت منــا الكتابــة إلــى الكليــة‬\n     ‫التقنيــة مبحافظــة عنيــزة بخطابنــا رقــم ‪ 34/316829‬يف ‪1434/2/6‬هـ ـ‬\n     ‫فوردنــا خطابهــم رقــم ‪ 97‬يف ‪1434/3/10‬هـ ـ املتضمــن ســعادة رئيــس‬\n     ‫احملكمــة العامــة ببريــدة املســاعد حفظــه اهلل الســام عليكــم ورحمــة‬\n\n\n‫‪87‬‬\n\f‫اهلل وبركاتــه حتيــة طيبــة وبعــد رد ًا علــى خطابكــم رقــم ‪34/316829‬‬\n‫وتاريــخ ‪1434/2/6‬ه ـ والــذي تطلبــون فيــه اإلفــادة عــن ســيارة املواطــن‬\n‫(‪ )........‬نفيدكــم أن قســم التقنيــة امليكانيكيــة بالكليــة أفــاد بأنــه‬\n‫ا مــن شــركة (‪ )........‬للســيارات وقــد تبــن مــن‬    ‫طلــب تقريــر ًا مفص ـ ً‬\n‫التقريــر أنــه مت فــك احملــرك مبراحــل متقدمــة مــن عمــر احملــرك لظهــور‬\n‫صــوت باحملــرك ومت تبديــل صمامــات رأس احملــرك وعليــة فــإن هنــاك‬\n‫عيــب باحملــرك كمــا هــو مرفــق ‪ .‬وتقبلــوا ســعادتكم خالــص التحيــة‬\n‫والتقديــر واهلل يحفظكــم عميــد الكليــة التقنيــة مبحافظــة عنيــزة‬\n‫(‪ )........‬وتوقيعــه وأمــا املالحظــة الثانيــة ‪ :‬فإنــه جــرى ســؤال املدعــي متــى‬\n‫اكتشــف العيــب الــذي يدعيــه فقــال إننــي اكتشــفته مــن يــوم وصــل‬\n‫عــداد الســيارة عشــرين ألــف كيلومتــر حيــث حضــرت إلــى الشــركة‬\n‫يف مقرهــا يف محافظــة عنيــزة لوجــود صــوت يف املاكينــة فخضــت أن‬\n‫تكــون املاكينــة فتــم الفحــص عليهــا ووجــود الزيــت ناقص ـ ًا فقالــوا‬\n‫راجــع الشــركة يف بريــدة وقــد راجعــت الشــركة قبــل وصــول العــداد‬\n‫خمســة وعشــرون ألــف كيلــو وذكــرت لهــم أن الزيــت ينقــص فقالــوا إن‬\n‫الزيــت ال ينقــص حيــث قامــوا بإدخــال الســيارة إلــى داخــل الصيانــة ثــم‬\n‫أفادونــي أن الزيــت ال ينقــص وفكــوا العيــار فوجــد أن الزيــت متعــدي‬\n‫الكميــة احملــددة ممــا يــدل علــى أنهــم وضعــوا الزيــت فقلــت أن الزيــت‬\n‫ينقــص فقالــوا نغيــر لــك الزيــت ونضــع شــطرطون لننظــر هــل ينقــص أم‬\n‫ال ؟ مــع أن الزيــت يهــرب مــن أســفل فتــم تغييــر الزيــت ومــازال الصوت يف‬\n‫املاكينة وبعد أن مشــيت خمســة آالف كيلو حضرت لديهم للكشــف‬\n‫ا وجــد‬   ‫عليهــا لعــل الزيــت نقــص أم ال فقامــوا بالكشــف عليهــا وفع ـ ً‬\n‫الزيــت ناقصـ ًا فقالــوا األن صحيــح الزيــت ناقــص وحتتــاج املاكينــة إلــى‬\n\n\n                                                                                        ‫‪88‬‬\n\f     ‫فــك وهــذه األشــياء املطلوبــة ومنهــا الشــنابر وهــذا معنــاه أنهــا حتتــاج إلــى‬\n     ‫توظيــب فلــم أوافــق والزالــت الســيارة عندهــم هكــذا أجــاب وبعــرض‬\n     ‫ذلــك علــى املدعــى عليــه وكالــة عمــا ذكــره املدعــي مــن متابعتــه‬\n     ‫للصيانــة لــدى الشــركة فقــال إننــي لســت فنيـ ًا وهــذا يتضــح مــن خــال‬\n     ‫الكتالــوج ووضــع اخلتــم عليــه هكــذا أجــاب وبعــرض ذلــك علــى املدعــي‬\n     ‫أجــاب إننــي متابــع معهــم وكل مــرة يذكــرون أنــه علــى الضمــان ولــو‬\n     ‫لــم يكــن علــى الضمــان ملــا اســتقبلوني هكــذا أجــاب وأمــا املالحظــة‬\n     ‫الثالثــة فإنــه جــرى إكمــال الــازم حيالهــا وأمــا املالحظــة الرابعــة فــإن‬\n     ‫املدعــي طلــب الفســخ وهــذا مــا حكمــت بــه وبعرضــه عليــه قنــع بــه ملــا‬\n     ‫ســبق كلــه الزلــت علــى مــا حكمــت بــه وقــررت إعــادة املعاملــة إلــى‬\n               ‫محكمــة االســتئناف وبــاهلل التوفيــق ‪ .‬حــرر يف ‪1434/5/21‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافق‪1434/07/09‬ه ـ افتتحــت‬\n     ‫اجللســة وقــد وردتنــي املعاملــة مــن محكمــة االســتئناف بالقصيــم رفــق‬\n     ‫خطــاب فضيلــة رئيســها رقــم ‪ 341318484‬يف ‪1434/6/26‬ه ـ واملقيــدة‬\n     ‫بهــذه احملكمــة برقــم ‪ 341318484‬يف ‪1434/6/28‬ه ـ واملرفــق بهــا‬\n     ‫قــرار الدائــرة احلقوقيــة األولــى رقــم ‪ 34241289‬يف ‪1434/6/14‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم الصــادر منــي برقــم ‪ 33439017‬يف‬\n     ‫‪1433/10/25‬ه ـ ولــذا جــرى إثباتــه والتهميــش مبوجبــه علــى الضبــط‬\n     ‫وســجل الصــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                       ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/9‬ه ـ‬\n     ‫احلمــد هلل وحــده ويف يــوم االحــد ‪1434/8/14‬ه ـ افتتحــت اجللســة وفيهــا‬\n     ‫حضــر املدعــي وقــرر انــه اســتلم املبلــغ احملكــوم بــه أعــاه وقــدره مائــة‬\n     ‫وســتة وأربعــون ألــف ريــال مــن الشــركة املدعــى عليهــا وبهــذا االقــرار‬\n\n\n‫‪89‬‬\n\f‫تعتبــر القضيــة منتهيــة وال يطالــب أحدهمــا االخــر بخصوصهــا وقــررت‬\n‫التهميــش بذلــك علــى الصــك وســجله وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n                             ‫علــى نبينــا محمــد حــرر يف ‪1434/8/14‬ه ـ ‪.‬‬\n\n\n\n\n                                                                              ‫‪90‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":81,"source_page_end":90,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4093e0492c70bd4728f2ad166f64eb43d420de29da6e878c044339a2e4d51355","normalized_text_hash":"09f28dd921b79d353ce53b6e0812aa7e0dc783c79ab5fda3fdfce1c65ba86ad9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p81-33439017"},{"id":"b5f06aeb-f438-515c-9d79-9e235d6ea298","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عيب مبيع -املطالبة برد ثمن سيارة مبيعه -إقرار الشركة املصنعة بالعيب -إنكار الشركة البائعة للعيب -االستعانة بأهل اخلبرة يف بيان العيب -القول قول املشتري يف العيب مع ميينه -عدم سقوط احلق يف إرجاع املبيع بالتراخي إال بدليل الرضا - ثبوت العيب وإمضاء خيار الفسخ للمشتري لعدم ثبوت ما يسقطه -احلكم بإعادة الثمن للمشتري والسيارة للبائع .","document_number":"34194877","case_number":"33474401","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"بيع -عيب مبيع -املطالبة برد ثمن سيارة مبيعه -إقرار الشركة املصنعة بالعيب -إنكار الشركة البائعة للعيب -االستعانة بأهل اخلبرة يف بيان العيب -القول قول املشتري يف العيب مع ميينه -عدم سقوط احلق يف إرجاع املبيع بالتراخي إال بدليل الرضا - ثبوت العيب وإمضاء خيار الفسخ للمشتري لعدم ثبوت ما يسقطه -احلكم بإعادة الثمن للمشتري والسيارة للبائع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/22 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34194877 :‬‬\n                        ‫َر ْق ُم الدعوى‪33474401 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34270712‬تاريخه‪1434/7/17 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬عيــب مبيــع ‪ -‬املطالبــة بــرد ثمــن ســيارة مبيعــه ‪ -‬إقــرار الشــركة‬\n     ‫املصنعــة بالعيــب ‪ -‬إنــكار الشــركة البائعــة للعيــب ‪ -‬االســتعانة بأهــل‬\n     ‫اخلبــرة يف بيــان العيــب ‪ -‬القــول قــول املشــتري يف العيــب مــع ميينــه‬\n     ‫‪ -‬عــدم ســقوط احلــق يف إرجــاع املبيــع بالتراخــي إال بدليــل الرضــا ‪-‬‬\n     ‫ثبــوت العيــب وإمضــاء خيــار الفســخ للمشــتري لعــدم ثبــوت مــا يســقطه‬\n                       ‫‪ -‬احلكــم بإعــادة الثمــن للمشــتري والســيارة للبائــع ‪.‬‬\n\n\n\n\n     ‫‪ .1‬قولــه تعالــى (يــا أيهــا الذيــن آمنــوا ال تأكلــوا أموالكــم بينكــم‬\n     ‫بالباطــل) ‪ ،‬قــال ابــن العربــي‪« :‬يعنــي مبــا ال يحــل شــرعا و ال يفيــد‬\n     ‫مقصــودا» أحــكام القــرآن ‪ ، 97/1‬وجــاء يف تفســير املنــار ‪ 40/5‬يف معنــى‬\n     ‫الباطــل ‪ « :‬أنــه مــا لــم يكــن يف مقابلــة شــيء حقيقــي وهــو مــن الباطــل‬\n     ‫والبطــان أي الضيــاع واخلســار ‪ ،‬فقــد حرمــت الشــريعة أخــذ املــال‬\n                        ‫بــدون مقابلــة حقيقيــة يعتــد بهــا ممــن يؤخــذ منــه»‪.‬‬\n     ‫‪ .2‬حديــث أبــي هريــرة رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وآلــه‬\n     ‫وســلم قــال‪« :‬كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه» رواه‬\n                                                                             ‫مســلم‪.‬‬\n     ‫‪ .3‬قــال ابــن تيميــة رحمــه اهلل‪« :‬إن كل مــا يوجــد باملبيــع ممــا ينقــص‬\n     ‫العــن أو القيمــة نقصــا يفــوت بــه غــرض صحيــح يثبــت بــه الــرد»‬\n                                                    ‫حاشــية ابــن قاســم ‪. 442/4‬‬\n‫‪91‬‬\n\f‫‪ .4‬قــال الشــيرازي ‪-‬رحمــه اهلل‪ -‬يف املهــذب) ‪« :)286/1‬والعيــب الــذي يــرد‬\n‫بــه املبيــع ممــا يعــده النــاس عيبــا فــإن خفــي منــه شــيء رجــع فيــه إلــى‬\n                                             ‫أهــل اخلبــرة بذلــك اجلنــس» ‪.‬‬\n‫‪ .5‬قــال املــرداوي يف اإلنصــاف‪« :‬العيــب هــو مــا ينقــص قيمــة املبيــع‬\n                 ‫نقيصــة يقتضــي العــرف ســامة املبيــع عنهــا غالبــا»‪.‬‬\n‫‪ .6‬مــا قــرره الفقهــاء مــن أن خيــار العيــب يثبــت بــا اشــتراط قــال ابــن‬\n         ‫عابديــن يف حاشــيته ‪« : 3/5‬خيــار العيــب يثبــت بــا اشــتراط» ‪.‬‬\n‫‪ .7‬مــا قــرره الفقهــاء مــن أن خيــار العيــب علــى التراخــي قــال البهوتــي‬\n‫يف شــرح منتهــى اإلرادات ‪« :211/3‬وخيــار عيــب متــراخ ألنــه لدفــع ضــرر‬\n‫متحقــق فــا يســقط بالتأخيــر كالقصــاص ‪ ،‬إال إن وجــد دليــل رضــاه‬\n                                                                 ‫أي املشــتري»‪.‬‬\n‫‪ .8‬مــا قــرره الفقهــاء مــن أنــه إذا اختلــف البائــع واملشــتري يف عيــب املبيع‬\n‫مــع االحتمــال فالقــول قــول املشــتري بيمينــه قــال البهوتــي رحمــه اهلل‪:‬‬\n‫«وإن اختلفــا أي البائــع واملشــتري يف معيــب عنــد مــن حــدث العيــب مــع‬\n‫االحتمــال فقــول مشــتر بيمينــه إن لــم يخــرج عــن يــده» الــروض املربــع‬\n                                                                        ‫‪.454 /4‬‬\n\n\n\n\n‫أقــام املدعــي علــى الشــركة املدعــى عليهــا دعــوى فســخ عقــد بيع ســيارة‬\n‫واســترداد ثمنهــا لوجــود عيــوب خفيــه بهــا تؤثــر علــى ســامتها وأنه راجع‬\n‫الشــركة أكثــر مــن مــرة لإلصــاح دون أن يتــم اإلصــاح علــى الوجــه‬\n‫الصحيــح ودفعــت الشــركة املدعــى عليهــا بعــدم صحــة ذلــك فجــرى‬\n‫اســتطالع رأي أهــل اخلبــرة والــذي أكــد وجــود بعــض العيــوب بســبب‬\n\n                                                                                      ‫‪92‬‬\n\f     ‫ســوء الصناعــة وعيــوب أخــرى ال ميكــن اجلــزم كونهــا ســوء صناعــة‬\n     ‫أم عيــوب اســتخدام وكمــا أقــر فنــي الشــركة املصنعــة بوجــود بعــض‬\n     ‫عيــوب بالســيارة ونظــر ًا ألن القاعــدة اذا اختلــف البائــع واملشــتري يف‬\n     ‫عيــب املبيــع مــع االحتمــال فالقــول قــول املشــتري بيمينــه لذلــك حكــم‬\n     ‫القاضــي بفســخ عقــد البيــع وإعــادة ثمــن الســيارة للبائــع وإعــادة ملكيــة‬\n     ‫الســيارة للشــركة البائعــة ولــم ترتــض املدعــى عليهــا احلكــم وجــرى‬\n                                            ‫تصديقــه مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬املــازم القضائــي لــدى فضيلــة‬\n     ‫الشــيخ د‪ )......( .‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى‬\n     ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامة بالريــاض (‪)......‬‬\n     ‫املســاعد برقــم ‪ 33474401‬وتاريــخ ‪1433/07/19‬هـ املقيدة باحملكمة‬\n     ‫برقــم ‪ 331356537‬وتاريــخ ‪1433/07/19‬ه ـ ففــي يــوم االثنــن املوافــق‬\n     ‫‪1433/8/11‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي(‪ )......‬ولم يحضر‬\n     ‫ممثــل الشــركة املدعــى عليهــا وقــد أبــرز املدعــي تبليــغ املديــر االداري‬\n     ‫باملنطقــة الوســطى ‪ .............‬باجللســة املاضيــة كمــا أبــرز خطــاب مديــر‬\n     ‫مركــز شــرطة النســيم برقــم بــدون وتاريــخ ‪1433/8/7‬ه ـ املتضمــن انــه‬\n     ‫مت ابــاغ املديــر اإلداري للشــركة حســب نســخة التبليــغ املرفقــة ا ه ـ‬\n     ‫ا‪:‬‬ ‫وعليــه فقــد أذنــت بســماع دعــوى املدعــي غيابيـ ًا فادعــى املدعــي قائـ ً‬\n     ‫يف اخــر شــعبان مــن عــام ‪1431‬ه ـ اشــتريت مــن شــركة ‪ .........‬ســيارة‪...‬‬\n     ‫ذات اللوحــة ‪ ..........‬صنــع عــام ‪2011‬م مببلــغ وقــدره مائتــان وعشــرون‬\n     ‫ألف ريال ‪ ،‬وبعد اســتالمي للســيارة اكتشــفت بها عدة عيوب مصنعية‬\n\n‫‪93‬‬\n\f‫منهــا أوال أن الســيارة تتوقــف فجــأة وهــي تســير ممــا يســبب خطــر ًا علــي‬\n‫وعلــى ابنائــي حيــث اخشــى ان تتوقــف الســيارة وانــا اســير بهــا ممــا يعنــي‬\n‫عــدم متكننــي مــن التحكــم بهــا يف الطريــق ثاني ًا اكتشــفت ان الفرامل‬\n‫ال تعمــل وعندمــا اخبرتهــم بذلــك قالــوا ان يف الفرامــل عيب ـ ًا مصنعي ـ ًا‬\n‫وســتأتينا قطــع غيارهــا بعــد عــدة اشــهر مــن املانيــا ثالث ـ ًا اكتشــفت ان‬\n‫كمبيوتــر الســيارة ال يظهــر االخطــاء واملشــاكل املوجــودة يف الســيارة‬\n‫كضغــط هــواء الكفــرات وغيــره رابع ـ ًا اكتشــفت ان اجلنــوط ســيئة‬\n‫حيــث انهــا انكســرت وقامــوا بتغييرهــا عــدة مــرات ‪ ،‬كمــا انهــم‬\n‫اصلحــوا الســيارة خــارج الوكالــة وهــذا االمــر يفقدنــي ضمــان الســيارة‬\n‫فيمــا بعــد ‪ ،‬ولــم ارض بهــذه العيــوب ابــد ًا وكنــت كثيــر التــردد علــى‬\n‫الشــركة إلصــاح الســيارة وهــي موجــودة عندهــم االن ألنــي وضعتهــا‬\n‫عندهــم ورفضــت اســتالمها ‪ ،‬اطلــب فســخ البيــع واعــادة كامــل الثمــن‬\n‫الــذي ســلمته لهــم وقــدره مئتــان وعشــرون الــف ريــال هــذه دعــواي لــذا‬\n‫فقــد قــررت الكتابــة لهيئــة النظــر لتقريــر هــل هــذه العيــوب عيــوب‬\n‫مصنعيــة ام ال ورفعــت اجللســة حلــن ورود اجلــواب ويف جلســة أخــرى‬\n‫حضــر املدعــي كمــا حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ..........‬بالوكالــة ‪ ............‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ............‬بوكالتــه عــن‪ ............‬بصفتــه صاحــب مؤسســة‬\n‫‪ ..............‬للســيارات مبوجــب الســجل التجــاري رقــم ………‪ ..‬يف‬\n‫‪1409/9/11‬ه ـ مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫يف شــمال محافظــة جــدة برقــم ‪ 43793‬يف ‪1433/5/15‬ه ـ املخــول فيهــا‬\n‫حضــور اجللســات واملدافعــة واملرافعــة وقــد وردنــا وقــد وردنــا كتــاب‬\n‫مديــر قســم اخلبــراء برقــم ‪ 331509883‬يف ‪1433/8/28‬ه ـ املتضمــن‬\n\n\n                                                                                      ‫‪94‬‬\n\f     ‫أنــه مت االســتعانة برئيــس مهنــة صناعيــة الريــاض القدميــة ‪ .......‬وتعــذر‬\n     ‫بقولــه ال ميكــن الكشــف عــن األعطــال حيــث مت االصــاح بــدون‬\n     ‫الوقــوف علــى الســيارة والكشــف عليهــا وبذلــك تعــذر أعضــاء الهيئــة‬\n                                                             ‫عــن كتابــة القــرار اه ـ ‪.‬‬\n     ‫وعليــه فقــد قــررت الكتابــة لــوزارة التجــارة لتقريــر هــل هــذه العيــوب‬\n     ‫عيــوب مصنعيــة ام ال ورفعــت اجللســة حلــن ورود اجلــواب ويف جلســة‬\n     ‫أخــرى حضــر املدعــي ‪ ............‬املــدون هويتــه ســلفا كمــا حضــر املدعــى‬\n     ‫عليــه وكالــة ‪ ...........‬املــدون رقــم هويتــه ووكالتــه ســلفا وقــد وردنــا‬\n     ‫خطــاب وكيــل وزارة التجــارة لشــؤون املســتهلك املكلــف ‪ .........‬برقــم‬\n         ‫‪/8166/9/5/267‬غ وتاريــخ ‪1433/10/08‬ه ـ واملتضمــن مانصــه‪:‬‬\n     ‫‪ -1‬عــدم عمــل آلــة التنبيــه ووجــود بقعــة زيــت علــى الســيارة قبل االســتالم‬\n                            ‫وأنــه قــد مت تلميــع الســيارة وإعــادة ضبــط آلــة التنبيه ‪.‬‬\n     ‫‪ -2‬توقــف الســيارة عــن احلركــة وانطفائهــا فجــأة وهبــوط يف الضغــط‬\n     ‫املكينــة ‪ ،‬أفــاد املشــرف علــى الصيانــة الســيد ‪ ...‬عــن ذلــك أفــاد بــان‬\n     ‫الســيارة املذكــورة قــد ســبق انطفــأت وهــو يقودهــا داخــل الورشــة ‪،‬‬\n     ‫وأفــادت الشــركة أنهــا قامــت بعمــل ســمكرة للســيارة مرتــن بســبب‬\n     ‫حــوادث مروريــة لكــن املدعــي أفــاد أنهــا حصلــت بســبب توقــف الســيارة‬\n                                    ‫املفاجــئ بالطريــق بســبب تعطــل الكمبيوتــر‪.‬‬\n     ‫‪ -3‬حســب التقريــر الفنــي الــوارد مــن الشــركة األم وحســب إفــادة‬\n     ‫الوكيــل (‪ )..........‬وجــود فشــل يف الكمبيوتــر امللحــق بالســيارة يف‬\n     ‫إظهــار التحذيــرات وفشــل الذاكــرة يف قــراءة األخطــاء حيــث لــم يتــم‬\n     ‫تســجيل أي نــوع مــن األعطــال عــن مراجعــة وحــدات التحكــم وذاكــرة‬\n           ‫احلاســب اآللــي بالســيارة وخلــل يف نظــام الكهروميكانيكــي ‪.‬‬\n\n\n‫‪95‬‬\n\f‫‪-4‬وجــود قطــع يف احــد اإلطــارات وكســر يف اجلنــوط األربعــة أفــادت‬\n‫الشــركة بــأن اجلنــوط والكفــرات قــد تعرضــت لصدمــات يف الطريــق‬\n‫أدت إلــى تلــف اجلنــوط وأنــه قــد مت تغييــر اجلنــوط األربعــة وكذلــك‬\n‫الكفــر املقطــوع مجانــا مــن قبــل شــركة ‪ .............‬للســيارات بينمــا‬\n‫يصــر املدعــي أنهــا بســبب ســوء التصنيــع وهنــا ال ميكــن االخــذ بــرأي‬\n‫الشــركة إذا ال يوجــد حــادث أو مشــاكل طريــق تــؤدي إلــى تلــف‬\n‫االربعــة جنــوط مــرة واحــدة وأن الشــركة أوضحــت أنهــا تأخــرت بتبديــل‬\n‫اجلنــوط بســبب أن اجلنــوط اجلديــدة التــي وصلــت لهــم مــن جــدة كانــت‬\n                        ‫غيــر صاحلــة لالســتعمال وهــذا يعنــي عيــب مصنعــي‬\n‫‪ -5‬قيــام الشــركة بإصــاح الســيارة خــارج الوكالــة يف ورشــة ‪.............‬‬\n‫لضبــط الزوايــا علــى نفقــة وحســاب الشــركة ‪ .............‬وهــذا مثبــت‬\n‫مبوجــب إفــادة الشــركة وبســؤال الشــركة عــن قيامهــم باســتدعاء‬\n‫الســيارة املعيبــة ماركــة ‪....‬موديــل ‪ 2011‬م أفــادو عــن قيامهــم بإجــراء‬\n‫االســتدعاء لســيارات بحســب رقــم الهيــكل الــوارد لهــم عــن طريــق‬\n‫الشــركة األم وال يشــملها رقــم هيــكل هــذه الســيارة وعليــه وبعــد‬\n‫الوقــوف علــى الســيارة وجــد أن جميــع ما ذكــره املدعي صحيح مع عدم‬\n‫إمكانيــة احلكــم بــأن العيــوب التــي ذكرهــا املدعــي عيــوب مصنعيــة‬\n‫ماعــدا اجلنــوط بهــا عيــوب مصنعيــه أو عيــوب جــراء االســتخدام كمــا‬\n‫تدعــي الشــركة مــع مالحظــة أن الســيارة حتــت فتــرة الضمــان وهــي‬\n‫ثــاث ســنوات أ ‪ .‬ه ـ وبعــرض القــرار علــى الطرفــن قــرر املدعــي قناعــة‬\n‫مبــا جــاء فيــه وبعــرض القــرار علــى املدعــى عليــه وكالــة طلــب املهلــة‬\n‫يف الــرد عليــه وعليــه جــرى رفــع اجللســة ويف جلســة أخــرى لــدي أنــا‪........‬‬\n‫املــازم القضائــي ‪ .......‬القاضــي يف احملكمــة العامــة بالريــاض حضــر‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫املدعــي ‪ .............‬املــدون هويتــه ســلفا كمــا حضــر املدعــى عليــه وكالــة‬\n     ‫‪ ............‬املــدون رقــم هويتــه ووكالتــه ســلفا وبعــرض مــا مت ضبطــه علــى‬\n     ‫الطرفــن بنــاء علــى املــادة ‪ 166‬مــن نظــام املرافعــات قــررا املصادقــة‬\n     ‫عليــه وبطلــب مــا اســتمهل ألجلــه املدعــى عليــه أبــرز مذكرتــه اجلوابيــة‬\n     ‫املكونــة مــن ورقــة واحــدة واملؤرخة يف ‪1434/3/17‬ه ـ وباالطالع عليها‬\n     ‫وجــد مــا نصــه‪ :‬اشــارة الــى خطــاب وزارة التجارة رقــم ‪8166/9/5/267‬‬\n     ‫بتاريــخ ‪1433/10/08‬ه ـ واملكــون مــن خمســة نقــاط لذلــك ســوف نبــن‬\n                                                        ‫مــا ذكــر علــى النحــو اآلتــي‪:‬‬\n     ‫أوالً‪ :‬وجــود بقــع زيــت علــى الســيارة وعــدم عمــل آلــة التنبيــه قبــل‬\n     ‫االســتالم يرجــى العلــم بــان إجــراء فحــص مــا قبــل التســليم هــو عمــل‬\n     ‫اساســي وضــروري جلميــع الســيارات الــواردة مــن املصنــع واســتناد ًا لذلــك‬\n     ‫الفحــص يتــم ضبــط منســوب جميــع الســوائل بالســيارة والكشــف علــى‬\n     ‫ضغــط هــواء اإلطــارات وكذلــك عمــل آلــة التنبيــه وجميــع األجهــزة‬\n     ‫املســاعدة وإزالــة جميــع الشــحومات التــي متواجــدة علــى جســم الســيارة‬\n     ‫واملقصــود بــه حفــظ اجلســم اخلارجــي للســيارة لعوامــل الشــحن وخالفــة‬\n     ‫ثانيــا ‪ :‬انطفــاء الســيارة فجــأة وهبــط ضغــط املاكينــة ‪ ..‬يرجــى العلــم‬\n     ‫واإلحاطــة بــأن الســيارة لــم تتوقــف أثنــاء الســير مــع وجــود مهنــدس‬\n     ‫الورشــة ولكــن قبــل البــدء بالــدوران أمــر طبيعــي نتيجــة عــدم تشــغيل‬\n     ‫الســيارة ملــد طويلــة وليــس لــه عالقــة بحــوادث الــواردة علــى اإلطــاق‪.‬‬\n     ‫حيــث الســيارة تعمــل بطريقــة تلقائيــة ال تعتمــد علــى البطاريــة امنــا علــى‬\n     ‫الدينامــو الــذي يقــوم بشــحن البطاريــة وامــداد جميــع وحــدات التحكــم‬\n                    ‫بالكهربــاء املطلوبــة علمــا أن الســيارة حتــت فتــرة الضمــان‬\n     ‫ثالثــا‪ :‬يرجــى العلــم بــأن جميــع أجهــزة الفحــص (الكمبيوتــر بالســيارة)‬\n\n\n‫‪97‬‬\n\f‫تعمــل بشــكل طبيعــي يف جميــع الظــروف وال يوجــد بهــا أي خلــل‬\n‫يذكــر وتقــوم بقيــاس جميــع األعطــال إن وجــدت ‪،‬وعــدم تســجيل أي‬\n‫أخطــاء هــو الدليــل بــأن جميــع مكونــات الســيارة تعمــل يشــكل جيــد‪.‬‬\n‫وان التقريــر املرفــق ضمــن أوراق القضيــة و املقــدم مــن املدعــي لــوزارة‬\n‫التجــارة واملوجــود منــه صــورة يف ملــف القضيــة ليــس مــن الشــركة األم‬\n‫أو الوكيــل ( ‪ .) ..................‬كمــا يرجــى العلــم بــان هــذا التقريــر يتــم‬\n‫طباعتــه عــن طريــق أجهــزة الكمبيوتــر خاصــة بالورشــة بعــد توصيلهــا‬\n‫بأجهــزة الصيانــة وذلــك ضمــن إجــراءات البرمجــة املصنعيــة التــي تتــم‬\n‫بصفــة يوميــه جلميــع ســيارات ‪...‬كمــا يرجــى العلــم بــان لفــظ كلمــة‬\n‫(‪ wronging‬يفيــد حتذيــر وليــس فشــل) واملذكــور إمامــه عبــارة‬\n‫عمليــة بــدء التشــغيل الكهربائــي مــن املقــود الكهربائــي وكذلــك‬\n‫كلمــة التحذيــر املذكــور إمــام قــراءة الكــود املخزنــة بالذاكــرة‬\n‫وهــذه ال يفيــد عطــل بتلــك األجــزاء املذكــورة وإمنــا تنبيــه للفنــي والــذي‬\n‫يعمــل علــى الســيارة ويجــري عمليــة برمجــة لألجــزاء التــي يتوجــب عليــه‬\n‫عملــة بعــد االنتهــاء مــن كل عمليــة برمجــة للتأكيــد بــان هــذه الوحدات‬\n‫تعمــل تلقائــي مــع العميــل بعــد خــروج الســيارة مــن الورشــة لذلــك إن تلــك‬\n‫التقاريــر املطبوعــة يتــم طبعــا بصفــة أوامــر للفنيــن بإجــراء الفحوصــات‬\n‫التــي يجــب االنتهــاء منــه قبــل خــروج الســيارة وهــي ليســت حتذيــرات‬\n‫للعميــل أو أي شــخص آخــر‪ ،‬ومبراجعــة الصفحــة التاليــة لهــذا التقريــر‬\n‫جتــدو أيضــا أن التقاريــر تطالــب العامــل الفنــي بالتأكيــد يف النظــر إلــى‬\n‫كل مــا هــو مكتــوب عليهــا لتحذيــر مبــا فيهــا العبارتــن الســابقتني‪.‬‬\n‫وللتأكيــد ممــا ســبق ذكــره فــأن ليــس لدينــا مانــع مــن اطــاع‬\n‫فضيلتكــم علــى تقاريــر مماثلــه الســيارات أخــرى أو جميــع الســيارات‬\n\n\n                                                                                       ‫‪98‬‬\n\f     ‫التــي بداخــل الورشــة مــع عمــل شــرح مفصــل للتقاريــر الصــادرة مــن‬\n     ‫أجهــزة التحكــم يف الســيارة وطبيعــة عمــل الفنيــن يف التعامــل معهــا‪.‬‬\n     ‫رابعــا‪ :‬يرجــى العلــم واالحاطــة بــأن جميــع جنــوط ‪ ...‬واملســتوردة عــن‬\n     ‫طريــق شــركة االم مت فحصهــا باملختبــرات والتــي مت حتديهــا مــن وزارة‬\n     ‫التجــارة والتــي تفيــد بــان جميــع جنــوط ســيارات ‪ ...‬قــد اجتــازت جميــع‬\n     ‫االختبــارات األزمــة لتتحمــل الصدمــات الطبيعيــة للطــرق ومــع ذلــك مت‬\n     ‫تغيرهــا للعميــل بصفــة مجانيــة كنــوع مــن اخلدمــة اإلضافيــة تقديــرا‬\n     ‫لعمــاء ‪ ) ...‬مرفــق صــورة مــن نتيجــة االختبــارات والتــي تثبــت مــا ســبق‬\n                                                                                 ‫ذكــره‪.‬‬\n     ‫خامســا‪ :‬إلصــاح وضبــط الزوايــا مت تغييــر الــذراع األمامــي األميــن علمــا‬\n     ‫بــأن ضبــط الزوايــا يتــم يف ورشــة ‪ ...........‬بإشــراف مــن مؤسســة ‪..........‬‬\n     ‫للســيارات وأيضــا بصفــة مجانيــة مــن مؤسســة ‪................‬للســيارات‪.‬‬\n     ‫ومت فحــص الســيارة علــى الطريــق والتأكــد مــن صحــة إصــاح الزوايــا‬\n     ‫ومطابقتــه املوصفــات الفنيــة املطلوبــة مــن شــركة ‪ ...‬العامليــة‪ .‬علمــا أنــه‬\n     ‫أثناء وجود ســيارة العميل بالورشــة مت تســليمه ســيارة بديلة من املؤسســة‬\n     ‫وقــد مت إرجاعهــا مــن قبــل العميــل بعــد االنتهــاء مــن إصــاح ســيارته ولــم‬\n     ‫يقــوم العميــل باســتالم ســيارته علمــا بأنهــا جاهــزة لالســتالم‪ .‬هــذا مــا‬\n     ‫أردنــا توضيحــه لفضيلتكــم ‪ ،‬ونحــن علــى اســتعداد لإلجابــة عــن أي‬\n     ‫استفســارات قــد تطلبونهــا الحقــا‪ ».‬وبســؤال املدعــي قــال لــدي بينــات‬\n     ‫أخــرى وأريــد إحضارهــا يف اجللســة القادمــة ‪ ،‬عليــه رفعــت اجللســة ويف‬\n     ‫جلســة أخــرى حضــر املدعــي ‪ ..............‬املــدون هويتــه ســلفا كمــا حضــر‬\n     ‫املدعــى عليــه وكالــة ‪ ...................‬املــدون رقــم هويتــه ووكالتــه ســلفا‬\n     ‫‪ ،‬وبطلــب مــا اســتمهل ألجلــه املدعــي أبــرز مذكرتــه اجلوابيــة املؤرخــة‬\n\n\n‫‪99‬‬\n\f‫‪1434/4/15‬ه ـ وباالطــاع عليهــا وجــد مــا نصــه ‪ »:‬فإنــه وإشــارة‬\n‫إلــى املوضــوع أعالهــا وإلــى مذكــرة وكيــل املدعــى عليــه املقدمــة‬\n‫لفضيلتكــم واملؤرخــة بتاريــخ ‪1434/3/1‬ه ـ والتــي جــاءت مــن املدعــى‬\n‫عليــه رد ًا علــى التقريــر الفنــي املوضــح بخطــاب وزيــر التجــارة فإننــي‬\n‫أتقــدم ملقــام فضيلتكــم بالتعقيــب علــى مــا ذكــره وكيــل املدعــى عليــه‬\n                                                                        ‫مبــا يلــي ‪:‬‬\n‫اوالً‪ :‬فلقــد ورد يف اخلطــاب املقــدم رد ًا علــى خطــاب فضيلتكــم مــن‬\n‫قبــل وزارة التجــارة والصناعــة وكالــة الــوزارة لشــئون املســتهلك ويف‬\n‫مقدمــة اخلطــاب أن املدعــى عليــه قــد أقــر بالعيــوب التــي ســببها رفــع‬\n‫هــذه الدعــوى وذلــك مبــا نصــه ‪( :‬وبحضــور كل مــن املواطــن ‪.............‬‬\n‫والســيد ‪ ...............‬مديــر إقليمــي بشركة‪........‬والســيد ‪ .............‬مديــر‬\n‫الصيانــة بشــركة ‪ ............‬ومبراجعــة العيــوب التــي تقــدم بهــا املدعــي‬\n‫والتــي أقــرت الشــركة بهــا ) انتهــى ‪ 0‬إذ ًا فــإن املدعــى عليــه قــد اقــر‬\n‫بالعيــب يف املبــاع حســب تقريــر وكالــة الــوزارة لشــئون املســتهلك‬\n‫بــوزارة التجــارة والصناعــة وحيــث إنــه مــن املقــرر شــرع ًا ونظام ـ ًا بــان‬\n‫خيــار العيــب يثبــت دون احلاجــة إلــى اشــتراطه صراحــة وكــذا الســامة‬\n‫وذلــك مــن مقتضيــات العقــد ألنــه مــن عقــود املعاوضــات والتــي تبنــي‬\n‫علــى املســاواة حقيقــة وعــادة ‪ ،‬وبالرجــوع إلــى ضمــن مــا جــاء بتقريــر‬\n‫خطــاب وزارة التجــارة آنــف الذكــر فلقــد جــاء يف البنــد الثالــث منــه مــا‬\n‫نصــه ‪( :‬حســب التقريــر الفنــي الــوارد مــن الشــركة األم وحســب إفــادة‬\n‫الوكيــل ( ‪ ) ...‬وجــود فشــل يف الكمبيوتــر امللحــق بالســيارة يف إظهــار‬\n‫التحذيــرات وفشــل الذاكــرة يف قــراءة األخطــاء حيــث لــم يتــم تســجيل‬\n‫أي نــوع مــن األعطــال عــن مراجعــة وحــدات التحكــم وذاكــرة احلاســب‬\n\n\n                                                                                        ‫‪100‬‬\n\f      ‫اآللــي بالســيارة وخلــل يف النظــام الكهروميكانيكــي) انتهــى ‪ 0‬ممــا‬\n      ‫يشــير إلــى وجــود عيــوب يف الســيارة موضــوع الدعــوى ومنــه فشــل يف آلــة‬\n      ‫التنبيــه وعــدم عملهــا قبــل االســتالم وعيــب يف الكمبيوتــر وهــذا مقــرا‬\n      ‫بــه مــن قبــل املدعــى عليــه ممــا يؤكــد إنــه عيــب خفــي لــم يظهــر قبــل‬\n      ‫االســتعمال ولــم اعلــم بــه أنــا املشــتري ممــا يتعــن معــه فســخ عقــد البيــع‬\n      ‫واســترداد مــا دفعتــه مــن ثمــن أخــذه املدعــى عليــه وأن تســتلم الوكالــة‬\n      ‫( املدعــى عليــه ) ســيارتها وأن نصــار إلــى احلالــة التــي كنــا عليــه اقبــل‬\n      ‫التعاقــد ‪ ،‬حيــث إننــي مشــترى هــذه الســيارة بغــرض إنهــا ســليمة مــن‬\n      ‫العيــوب علم ـ ًا بــان هــذا العيــب اخلفــي مؤثــر ًا يف املبيــع ومــن شــأنه أن‬\n      ‫يجعــل البيــع غيــر صالــح للغــرض الــذي اعــد لــه حيــث أن هــذه العيــوب‬\n      ‫جميعهــا كانــت موجــودة وقــت البيــع وهــي عيــوب تنقــص مــن قيمــة‬\n      ‫املبــاع ومــن نفعــه وإننــي لــم أكــن أعلمهــا ولــو كنــت أعلمهــا ملــا أقدمــت‬\n                                                                    ‫علــى شــراء املبــاع ‪.‬‬\n      ‫ثاني ـ ًا ‪ :‬مــا يريــد إن ينفيــه وكيــل املدعــى عليــه يف البنــد الثانــي مــن‬\n      ‫مذكرتــه مبــا نصــه ‪ .... ( :‬يرجــى العلــم واإلحاطــة بــأن الســيارة لــم‬\n      ‫تتوقــف أثنــاء الســير مــع وجــود مهنــدس الورشــة ) انتهــى ‪ ،‬هــذا يتناقــض‬\n      ‫مــع مــا ذكــره املشــرف علــى الصيانــة الســيد ‪ ...‬يف أقوالــة لــدي وزارة‬\n      ‫التجــارة فهــو قــال يف ثانيــا ممــا جــاء بخطــاب وزارة التجــارة لفضيلتكــم‬\n      ‫مــا نصــه ( توقــف الســيارة عــن احلركــة وانطفائهــا فجــأة أفــاد املشــرف‬\n      ‫علــى الصيانــة الســيد ‪...‬عــن ذلــك أفــاد بــأن الســيارة املذكــورة قــد‬\n      ‫ســبق انطفــأت وهــو يقودهــا داخــل الورشــة ) انتهــى ‪ .‬ونفيــد فضيلتكــم‬\n      ‫بــان هــذا االنطفــاء املفاجــئ تكــرر عــدة مــرات لنــا ويف الطريــق العــام‬\n      ‫والســؤال الــذي يطــرح نفســه ملــاذا ســيارة جديــدة يحــدث لهــا مثــل ذلــك‬\n\n\n‫‪101‬‬\n\f‫؟؟؟ فــا بــد أن يكــون هنالــك عيــب مصنعــي لــم يعتــرف بــه املدعــى‬\n‫عليــه !!! واعترفــت بــه الشــركة األم مصنعــة ومصــدرة هــذه الســيارة يف‬\n‫تقريرهــا املرفــق صــورة منــه ‪ 0‬وإقــرار موظفهــا املشــرف علــى الصيانــة‬\n‫مــا هــو إال دليــل يعضــد ذلــك ‪ ،‬وبالتالــي فــإن ذلــك يــدل علــى أن املدعــى‬\n‫عليــه كان يعلــم بــكل تلــك العيــوب اخلفيــة وكتمهــا وقــت البيــع ‪ ،‬فعــن‬\n‫أبــي هريــرة رضــي اهلل عنــه ( أن النبــي صلــى اهلل عليــه وســلم مــر علــى‬\n‫صبــرة طعــام ‪ -‬يعنــي كومــة طعــام ‪ -‬فأدخــل يــده فيهــا‪ ،‬فنالــت أصابعــه‬\n‫بلــا فقــال ‪ :‬مــا هــذا يــا صاحــب الطعــام ؟ قــال ‪ :‬أصابتــه الســماء يــا‬\n‫رســول يعنــي املطــر قــال ‪ :‬أفــا جعلتــه فــوق الطعــام كــي يــراه النــاس‬\n‫‪ ،‬مــن غــش فليــس منــي ) أخرجــه مســلم يف كتــب اإلميــان ‪ ،‬بــاب قــول‬\n                    ‫النبــي صلــي اهلل عليــه وســلم ( مــن غشــنا فليــس منــا )‬\n‫ثالثــا ‪ :‬إن مــا ذكــره وكيــل املدعــى عليــه يف الفقــرة الثالثــة مــن‬\n‫مذكرتــه هــذه أقــوال مرســله إذا إننــا ال ندعــى بوجــود عيــب يف جميــع‬\n‫الســيارات التــي يبيعهــا املدعــى وإمنــا العيــب واخللــل املصنعــي املعتــرف بــه‬\n‫مــن قبــل الشــركة املصنعــة يف الســيارة موضــوع الدعــوى والتــي اســتلم‬\n‫موكلــه ثمنهــا عــد ًا نقــد ًا دون انتفاعــي باملبــاع وضيــاع وقتــي وجهــدي‬\n                                                                ‫مبــا هــو يعلــم بــه ‪0‬‬\n‫رابع ـ ًا ‪ :‬مــا أشــار إليــه وكيــل املدعــى عليــه يف مذكرتــه يف الفقــرة‬\n‫الرابعــة منهــا هــذا غيــر صحيــح حيــث إنــه يحــاول التهــرب مــن العيــب‬\n‫املصنعــي يف اجلنــوط األربعــة ثــم الكفــرات للســيارة املباعــة ولكــن‬\n‫ذلــك مــردودا عليــه ومجابــا عليــه مــن قبــل وزارة التجــارة والصناعــة يف‬\n‫خطابهــا فقرتــه الرابعــة مبــا نصــه ‪ .... ( :‬وهنــا ال ميكــن األخــذ بــرأي‬\n‫الشــركة إذا ال يوجــد حــادث أو مشــاكل طريــق تــؤدي إلــى تلــف‬\n\n\n                                                                                           ‫‪102‬‬\n\f      ‫األربعــة جنــوط مــرة واحــدة ‪،‬وأن الشــركة أوضحــت أنهــا تأخــرت‬\n      ‫بتبديــل اجلنــوط بســبب أن اجلنــوط اجلديــدة التــي وصلتلهــم مــن جــده‬\n      ‫كانــت غيــر صاحلــة لالســتعمال وهــذا يعنــي عيــب مصنعــي ‪ ) .‬انتهــى‪.‬‬\n      ‫وكذلــك إجابتــه بالفقــرة املذكــورة تتناقــض مــع مــا تضمنــه خطابــه‬\n      ‫املرســل لــي ( املرفــق صورتــه ) حيــث أشــار يف الفقــرة التاســعة منــه مــا‬\n      ‫نصــه ( ‪ .......‬لقــد قضــى العميــل أيــام عديــدة بانتظــار إصــاح عجــات‬\n      ‫الســيارة والســبب كان ال بــد مــن إعــادة طلــب بعــض العجــات مــن جــدة‬\n      ‫‪ .‬لقــد اســتلمنا العجــات ولكــن لألســف وجدناهــا معطوبــة ) انتهــى‬\n      ‫‪ ..‬والســؤال هنــا الذيــي طــرح نفســه ملــاذا ســيارة جديــدة الصنــع تتلــف‬\n      ‫جنوطهــا ؟؟؟؟ إال يــدل ذلــك علــى توفــر العيــب !!! ملــاذا يتــم تغيــر اجلنــوط‬\n      ‫؟؟؟؟ لســيارة لــم يكتمــل عمرهــا عــدة شــهور !!!! بالتالــي فــإن مــا ذكره‬\n      ‫وكيــل املدعــى عليــه بالفقــرة الرابعــة يرقــي بظــال مــن الشــك والريبــة‬\n      ‫حــول تقاريــر الفحــص باملختبــرات التــي ذكرهــا مــن صالحيــة اجلنــوط‬\n      ‫املســتوردة مــن قبلــه وان كان ذلــك ال يعنينــا يف شــيء وغيــر منتــج يف‬\n      ‫الدعــوى بكــون الســيارة موضــوع الدعــوى كان بهــا عيــب مصنعــي‬\n      ‫خفــي يتمثــل يف العيــب املصنعــي للجنــوط التــي مت تغيرهــا ولكــن دون‬\n      ‫فائــدة الســتمرار التوقــف املفاجــئ للســيارة نتيجــة تعطــل الكمبيوتــر‬\n      ‫الــذي يــؤدي إلــى حــدوث كــوارث يف األرواح مــن راكبيهــا ومســتخدمي‬\n      ‫الطريــق العــام وخســارة يف املمتلــكات ثــم الدخــول مــرة ثاني ـ ًا وثالثــة‬\n      ‫ورابعــة وهكــذا يف دوامــة تغيــر اجلنــوط !!!!! إذ ًا فمــا الهــدف مــن‬\n      ‫شــراء مثــل هكــذا ســيارة !!!!!! ‪ .‬هــل قيادتهــا آمنــه !!! أم تــؤدي إلــى‬\n      ‫التهلكــة ؟؟؟ التــي منهــي عنهــا شــرع ًا ‪ ،‬فليحضــر املدعــى عليــه تســجيل‬\n      ‫الكاميــرات إلثبــات عــدد املــرات التــي زرت فيهــا الشــركة مــن اجــل‬\n\n\n‫‪103‬‬\n\f‫إصــاح هــذه الســيارة ‪ ،‬وعــن عقبــة بــن عامــر رضــي اهلل عنــه قــال ‪:‬‬\n‫ســمعت النبــي صلــي اهلل عليــه وســلم يقــول ‪ ( :‬املســلم أخــو املســلم ‪ ،‬وال‬\n‫يحــل ملســلم بــاع مــن أخيــه بيعــا وفيــه عيــب فــا بينــه لــه ) (أخرجــه ابــن‬\n‫ماجــه يف أبــواب التجــارات بــاب بــاع عيبـ ًا فليبينــه برقــم ‪ 2246‬واحلاكــم‬\n‫يف مســتدركه ‪ 1/2‬وصححــه شــرطهما و وافقــه الذهبــي وقــواه ابــن‬\n‫تيميــة يف إقامــة الدليــل ص ‪121‬وإننــي لــم اعلــم بــكل تلــك العيــوب قبــل‬\n‫ا‬\n‫الشــراء ممــا يتعــن معــه احلكــم لــي بأخــذ الثمــن الــذي دفعتــه كامـ ً‬\n‫وإنــي ال ارغــب بغيــر ذلــك علمـ ًا بــأن الســيارة املباعــة يف يــد املدعــى عليــه‬\n‫مــن تاريــخ خطابهــم املوجهــة لــي ‪ ،‬ومحاولــة املدعــى عليــه إصالحهــا‬\n‫مــا هــو إال تهــرب مــن رد الثمــن وهــذا ظلــم منهــي عنــه بقولــه تعالــي‬\n‫( يــا أيهــا الذيــن آمنــوا ال تأكلــوا أموالكــم بينكــم بالباطــل إال أن‬\n‫تكــون جتــارة عــن تــراض منكــم ) اآليــة(‪ )29‬ســورة النســاء ‪ ،‬والظلــم‬\n‫يفســد الرضــا يف العقــد كمــا إنــه مــن أكل املــال بالباطــل والظلــم يف‬\n‫البيــع فهــو الغــش خامس ـ ًا ‪ :‬لقــد أورد وكيــل املدعــى عليــه بالفقــرة‬\n‫اخلامســة مــن مذكرتــه مــا نصــه ‪ ( :‬إلصــاح وضبــط الزوايــا مت تغيــر‬\n‫الــذراع األمامــي األميــن علم ـ ًا بــأن ضبــط الزوايــا يتــم يف ورشــة ‪...........‬‬\n‫بإشــراف مؤسســة ‪..........‬للســيارات ‪ ...‬ومت فحــص الســيارة علــى الطريــق‬\n‫والتأكــد مــن إصــاح الزوايــا ومطابقتهــا للمواصفــات الفنيــة املطلوبــة‬\n‫مــن شــركة ‪ ...‬العامليــة ‪ ....‬الــخ ) ‪ ،‬يــا صاحــب الفضيلــة إنــي أشــتري‬\n‫ســيارة جديــدة ثــم يحــدث لهــا كل ذلــك وهــى جديــدة ‪ ،‬إضافــة إلــى أن‬\n‫التقريــر الفنــي الصــادر مــن الشــركة التــي املدعــى عليــه هــو وكيلهــا‬\n‫( واملرفــق صــورة منــه مترجم ـ ًا ) يفيــد مــا نصــه ‪ ( :‬أن بالســيارة فشــل‬\n‫يف قــراءة األخطــاء ‪ -‬وبهــا خلــل يف نظــام القيــادة الكهروميكانيكــي‬\n\n\n                                                                                          ‫‪104‬‬\n\f      ‫‪ -‬ومبعاجلــة اخلطــأ أغلــق البرنامــج الدولــي لتطبيقــات الصيانــة الفنيــة‬\n      ‫وانتقــل إلــى التشــخيص للبحــث ضمــن اخلطــأ املوجــودة ‪ -‬لــم يتــم إجــراء‬\n      ‫مطابقــة تــوازن الســيارة ) انتهــى ‪ 0‬ممــا يعنــي أن املدعــى عليــه تعمــد‬\n      ‫تعطيــل الكمبيوتــر لعــدم ظهــور أيــة عيــوب علــى الســيارة وبعــد تقريــر‬\n      ‫الشــركة األم الــذي أوضــح تلــك العيــوب ملــاذا يصــر املدعــى عليــه بــان‬\n      ‫الســيارة ســليمة وخاليــة مــن العيــوب الصناعيــة والشــركة األم هــي‬\n      ‫ذات نفســها تقــر بذلــك فهــو ادخــل الســيارة إلــى ورشــة ‪ ............‬إلصــاح‬\n      ‫الزوايــا والشــركة املصنعــة للســيارة تقــر بأنــه لــم يجــري لهــا مطابقــة‬\n      ‫تــوازن حــن صنعهــا ‪ ،‬كمــا وان املدعــى عليهــا تقــر مبوجــب تقريــر‬\n      ‫وزارة التجــارة املوجهــة ملقــام فضيلتكــم بأنهــا لــم تقــوم باســتدعاء‬\n      ‫الســيارة موضــوع الدعــوى مــن قبــل الشــركة األم انظــر يف ذلــك إلــى‬\n      ‫الفقــرة اخلامســة مــن هــذا التقريــر مبــا نصــه ‪ ( :‬وبســؤال الشــركة عــن‬\n      ‫قيامهــم باســتدعاء الســيارة املعيبــة ماركــة ‪ ...‬الفئــة اخلامســة موديــل‬\n      ‫‪2011‬م أفــادوا عــن قيامهــم بإجــراء االســتدعاء لســيارات بحســب رقــم‬\n      ‫الهيــكل الــوارد لهــم عــن طريــق الشــركة األم وال يشــملها رقــم هيــكل‬\n      ‫هــذه الســيارة ) انتهــى سادس ـ ًا ‪ :‬الطلبــات ‪:‬احلكــم لــي بإلــزام املدعــى‬\n                             ‫عليــه بــرد ثمــن الســيارة وفســخ عقــد البيــع للعيــب ‪0‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه قــال‪ :‬أكتفــي مبــا قدمــت وال جديــد‬\n      ‫لــدي‪ .‬وبســؤال املدعــي عــن العيــب متــى حصــل فقــال‪ :‬لقــد حصــل‬\n      ‫العيــب مــن ثانــي يــوم اســتلمت فيــه الســيارة فآلــة التنبيــه ال تعمــل‬\n      ‫وجهــاز الكمبيوتــر لــم يبــن هــذا العيــب ( ثــم أرجعــت الســيارة لهــم ثــم‬\n      ‫قامــوا بإصــاح جهــاز التنبيــه ولكــن الكمبيوتــر ال يعمــل علــى الوجــه‬\n      ‫املطلــوب ‪ ،‬ثــم تعيبــت الفرامــل وقامــوا بإصالحهــا لــي ثــم حــدث عيــب‬\n\n\n‫‪105‬‬\n\f‫يف الكمبيوتــر جعــل الســيارة تنطفــئ مــن حالهــا ممــا ســبب حادثــا‬\n‫ثــم أرجعــت الســيارة لهــم وأصلحوهــا لــي ثــم صــرت أتــردد عليهــم شــبه‬\n‫يومــي فهــواء الكفــرات دائــم النقــص والكمبيوتــر ال يبــن ذلــك‬\n‫زيــادة علــى أن اخللــل صــار مــن اجلنــوط التــي تبــن أنهــا مكســرة وقــد‬\n‫أثبتــت وزارة التجــارة أنــه عيــب مصنعــي ‪ ،‬ثــم حــدث حــادث آخــر بنفــس‬\n‫املشــكلة الســابقة ثــم أعدتهــا لهــم وأصلحوهــا ثــم أخــذت الســيارة‬\n‫والزالــت املشــكلة قائمــة ثــم أرجعتهــا إليهــم ولــم آخذهــا حتــى اآلن ‪،‬‬\n‫وبســؤال املدعــي هــل هــو مســتعد ببــذل اليمــن علــى ذلــك فقــال نعــم ‪،‬‬\n‫وبســؤاله هــل لديــك مــا تقدمــه فقــال أكتفــي مبــا قدمــت ‪ ،‬وبســؤال‬\n‫املدعــى عليــه وكالــة قــال أكتفــي مبــا قدمــت لــذا جــرى قفــل بــاب‬\n‫املرافعــة ورفعــت اجللســة للدراســة والتأمــل ويف جلســة أخــرى ويف جلســة‬\n‫أخــرى حضــر املدعــي ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ……‪ ..‬وحضــر حلضــوره …‪ ..‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ، .............‬وبطلــب اليمــن املدعــي اســتعد بأدائهــا وبعــد‬\n‫أن بينــت لــه عاقبــة اليمــن الكاذبــة ومغبتهــا ‪ ،‬أذنــت لــه ببــذل اليمــن‬\n‫فقــال‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو احلــي القيــوم القــوي القاهــر‬\n‫أنــي اشــتريت ســيارة مــن نــوع ‪ 523 ...‬الفئــة اخلامســة صنــع عــام ‪2011‬‬\n‫م ذات اللوحــة رقــم ( ‪ )..............‬مببلــغ وقــدره مائتــان وخمســة عشــر‬\n‫ألــف ريــال مــن شــركة ‪ ...............‬للســيارات ‪ ،‬وأنــه قــد حصــل فيهــا‬\n‫عيــب مــن ثانــي يــوم اســتلمت فيــه الســيارة فآلــة التنبيــه ال تعمــل وجهــاز‬\n‫الكمبيوتــر لــم يبــن العيــب ‪ ،‬ثــم تعيبــت الفرامــل ثــم حــدث عيــب يف‬\n‫جهــاز الكمبيوتــر جعــل الســيارة تنطفــئ مــن حالهــا ممــا ســبب حادثــا ‪،‬‬\n‫ثــم حــدث عيــب يف هــواء الكفــرات و جهــاز الكمبيوتــر لــم يبــن هــذا‬\n\n\n                                                                                      ‫‪106‬‬\n\f      ‫العيــب ثــم حــدث حــادث آخــر بســبب انطفــاء الســيارة مــن حالهــا ‪ ،‬ولــم‬\n      ‫أرض بهــذه العيــوب ولــم تكــن العيــوب ناجتــة عــن اســتخدامي ‪ ،‬وقــد‬\n      ‫راجعــت الشــركة بعــد كل عيــب يف الســيارة واهلل العظيــم‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة واليمــن ولقولــه تعالــى (يــا أيهــا الذيــن‬\n      ‫آمنــوا ال تأكلــوا أموالكــم بينكــم بالباطــل) قــال ابــن العربــي‪« :‬يعنــي‬\n      ‫مبــا ال يحــل شــرعا و ال يفيــد مقصــودا» أحــكام القــرآن ‪ ، 97/1‬وجــاء‬\n      ‫يف تفســير املنــار ‪ 40/5‬يف معنــى الباطــل‪« :‬أنــه مــا لــم يكــن يف مقابلــة‬\n      ‫شــيء حقيقــي وهــو مــن الباطــل والبطــان أي الضيــاع واخلســار ‪ ،‬فقــد‬\n      ‫حرمــت الشــريعة أخــذ املــال بــدون مقابلــة حقيقيــة يعتــد بهــا ممــن يؤخــذ‬\n      ‫منــه» ‪ ،‬وملــا جــاء يف حديــث أبــي هريــرة رضــي اهلل عنــه أن النبــي صلــى‬\n      ‫اهلل عليــه وآلــه وســلم قــال (كل املســلم علــى املســلم حــرام دمــه ومالــه‬\n      ‫وعرضــه) رواه مســلم ‪ ،‬وملــا جــاء يف معنــى العيــب عنــد العلمــاء فقــد‬\n      ‫قــال ابــن تيميــه رحمــه اهلل‪« :‬إن كل مــا يوجــد باملبيــع ممــا ينقــص العــن‬\n      ‫أو القيمــة نقصــا يفــوت بــه غــرض صحيــح ‪ ،‬يثبــت بــه الــرد» حاشــية‬\n      ‫ابــن قاســم ‪ . 442/4‬وقــال الشــيرازي رحمــه اهلل يف املهــذب‪1/286« :‬‬\n      ‫والعيــب الــذي يــرد بــه املبيــع ممــا يعــده النــاس عيبــا فــإن خفــي منــه شــيء‬\n      ‫رجــع فيــه إلــى أهــل اخلبــرة بذلــك اجلنــس» وقــال املــرداوي يف اإلنصــاف‪»:‬‬\n      ‫العيبــه ومــا ينقــص قيمــة املبيــع نقيصــة يقتضــي العــرف ســامة املبيــع‬\n      ‫عنهــا غالبــا» ‪ ،‬وملــا قــرره الفقهــاء مــن أن خيــار العيــب يثبــت بــا اشــتراط‬\n      ‫قــال ابــن عابديــن يف حاشــيته ‪« : 3/5‬خيــار العيــب يثبــت بــا اشــتراط»‪.‬‬\n      ‫وملــا قــرره الفقهــاء مــن أن خيــار العيــب علــى التراخــي قــال البهوتــي يف‬\n      ‫شــرح منتهــى اإلرادات ‪« : 211/3‬وخيــار عيــب متــراخ ألنــه لدفــع ضــرر‬\n      ‫متحقــق فــا يســقط بالتأخيــر كالقصــاص ‪ ،‬إال إن وجــد دليــل رضــاه‬\n\n\n‫‪107‬‬\n\f‫أي املشــتري» ‪ ،‬وملــا قــرره الفقهــاء مــن أنــه إذا اختلــف البائــع واملشــتري‬\n‫يف عيــب املبيــع مــع االحتمــال فالقــول قــول املشــتري بيمينــه قــال البهوتــي‬\n‫رحمــه اهلل‪ » :‬وإن اختلفــا أي البائــع واملشــتري يف معيــب عنــد مــن حــدث‬\n‫العيــب مــع االحتمــال فقــول مشــتر بيمينــه إن لــم يخــرج عــن يــده « الروض‬\n‫املربــع ‪ ، 454 /4‬وملــا قــرره الفقهــاء مــن أنــه متــى علــم املشــتري بالعيــب‬\n‫فهــو باخليــار بــن اإلمســاك مــع األرش أو الــرد قــال ابــن قدامــة رحمــه‬\n‫اهلل يف املغنــي ‪ »:108/4‬ومتــى علــم ‪ ،‬يعنــي املشــتري‪ -‬باملبيــع عيبــا لــم‬\n‫يكــن عاملــا بــه فلــه اخليــار بــن اإلمســاك والفســخ ســواء كان البائــع‬\n‫علــم العيــب وكتمهــا ولــم يعلــم ‪ ،‬ال نعلــم بــن أهــل العلــم يف هــذا خالفــا»‬\n‫‪ ،‬ومبــا أن املشــتري رفــض اإلمســاك مــع األرش وطالــب بالثمــن مــع رد‬\n‫املبيــع ‪ ،‬ومبــا أن تقريــر وزارة التجــارة قــد صــدر مــن خبيــر واخلبيــر أمــن‬\n‫كمــا قــرر ذلــك الفقهــاء وملــا جــاء يف قــرار وزارة التجــارة مــن تأييــد‬\n‫كالم املدعــي مــع عــدم اجلــزم بالعيــوب هــل هــي مصنعيــة أو ال ممــا يعــد‬\n‫قرينــة تقــوي جانــب املدعــي خصوصــا مــع جــدة الســيارة ‪ ،‬وملــا جــاء يف‬\n‫تقريــر وزارة التجــارة مــن اجلــزم بوجــود عيــب مصنعــي يف اجلنــط ممــا يعد‬\n‫قرينــة أخــرى تقــوي جانــب املدعــي ‪ ،‬ومبــا أن املدعــي لــم يــرض بتلــك‬\n‫العيــوب ولــم يصــدر منــه أي فعــل يــدل علــى الرضــا بدليــل تــردده علــى‬\n‫مركــز الصيانــة بعــد كل عيــب يحــدث يف الســيارة ومــن ثــم تركــه‬\n‫للســيارة عندهــم ‪ ،‬ومبــا أن هــذا العيــب يعــد عيبــا مؤثــرا يف الســيارة‬\n‫ال يحقــق املقصــود مــن شــراءها ‪ ،‬وملــا جــاء يف ميــن املدعــي ‪ ،‬ومبــا أن‬\n‫املشــتري قــد بــذل الثمــن ليســلم لــه مبيــع ســليم ولــم يســلم لــه فثبــت لــه‬\n‫الرجــوع بالثمــن أو اإلمســاك مــع األرش ‪ ،‬لذلــك كلــه فقــد حكمــت‬\n‫علــى شــركة ‪ .........‬للســيارات بإعــادة ثمــن الســيارة املعيبــة وقــدره‬\n\n\n                                                                                        ‫‪108‬‬\n\f      ‫مائتــان وخمســة عشــر ألــف ريــال لصالــح املدعــي ‪ ،............‬وبعــرض‬\n      ‫احلكــم علــى املدعــي قــرر قناعتــه ‪ ،‬وبعرضــه علــى وكيــل الشــركة‬\n      ‫املدعــى عليــه قــرر عــدم القناعــة فجــرى تســليمه نســخة مــن احلكــم ‪،‬‬\n      ‫وأفهــم بــأن مــدة االعتــراض ثالثــون يومــا مــن تاريــخ هــذا اليــوم فــإن تقدم‬\n      ‫باعتراضــه وإال ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n      ‫ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                     ‫وســلم‪ .‬حــرر يف ‪1434/4/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬املــازم القضائــي لــدى الشــيخ‬\n      ‫‪ .........‬القاضــي يف احملكمــة العامــة بالريــاض وبناء على املعاملة احملالة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪33474401‬‬\n      ‫وتاريــخ ‪1433/07/19‬ه ـ املقيــدة باحملكمة برقــم ‪ 331356537‬وتاريخ‬\n      ‫‪1433/7/19‬ه ـ يف يــوم الســبت املوافق‪1434/07/01‬ه ـ عــادت إلينــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف بالريــاض رقــم ‪ 341370055‬وتاريــخ‬\n      ‫‪1434/6/18‬ه ـ املرفــق بهــا قــرار املالحظــة رقــم ‪ 34238979‬وتاريــخ‬\n      ‫‪1434/6/12‬ه ـ واملتضمــن مــا نصــه بعــد املقدمــة‪ »:‬لوحــظ بــأن فضيلتــه‬\n      ‫قــد ألــزم الشــركة بإعــادة ثمــن الســيارة قبــل أن يقــرر فســخ عقــد البيــع‬\n      ‫للعيــب والبــد مــن ذلــك كمــا أنــه لــم يقــرر بــأن ملكيــة الســيارة تعــود‬\n      ‫إلــى الشــركة وأن لهــا التصــرف بهــا مبــا تشــاء بعــد اكتســاب احلكــم‬\n      ‫القطعيــة فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم ‪ ،‬قاضــي‬\n      ‫اســتئناف ‪ .........‬توقيــع وختــم ‪ ،‬قاضــي اســتئناف ‪ ..........‬توقيــع وختــم ‪،‬‬\n      ‫رئيــس الدائــرة ‪ ............‬توقيــع وختــم ‪.‬اهــ‪ .‬عليــه أفيــد أصحــاب الفضيلــة‬\n      ‫بــأن مــا ذكــروا مــن مالحظــات قــد ســقطت ســهوا عليــه افتتحــت‬\n      ‫اجللســة وحضــر الطرفــان ‪ ،‬وذكــرت لهــم بــأن منطــوق احلكــم هــو‪:‬‬\n\n\n‫‪109‬‬\n\f‫لذلــك كلــه فقــد حكمــت بفســخ عقــد البيــع لوجــود العيــب املذكــور‬\n‫ومبوجبــه يتــم إعــادة ثمــن الســيارة املعيبــة وقــدره مائتــان وخمســة عشــرة‬\n‫ألــف ريــال لصالــح املدعــي ‪ ................‬وأفهمــت وكيــل الشــركة بــأن‬\n‫الســيارة تعــود مللكيــة الشــركة ولهــا أن تتصــرف بهــا مبــا تشــاء بعــد‬\n‫اكتســاب احلكــم القطعيــة ففهــم ذلــك ‪ .‬وأمــرت بإعــادة املعاملــة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/1‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬املــازم القضائــي لــدى‬\n‫فضيلــة الشــيخ‪..........‬القاضي يف احملكمــة العامــة بالريــاض ففــي‬\n‫يــوم الثالثاءاملوافــق‪ 1434/09/22‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n‫‪02‬وفيهــا حضــر ‪ .......‬املدونــة هويتــه ســابقا ‪ .‬وأفــاد بأنــه قد اســتلم شــيك‬\n‫مــن املدعــي برقــم ‪899879‬مــن البنــك ‪ ....‬مببلــغ وقــدره ( ‪) 215.000‬‬\n‫ريــال ‪ .‬وبذلــك تكــون املطالبــة منتهيــة بــن الطرفــن وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1434/9/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫باخلطــاب رقــم ‪ 341370055‬وتاريــخ ‪1434/7/3‬ه ـ املرفــق بهــا الصــك‬\n‫رقــم ‪34194877‬وتاريــخ ‪1434/4/22‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ............‬املتضمــن احلكــم يف الدعــوى املقامــة‬\n‫مــن‪ ...........‬ضــد ‪ ..........‬علــى النحــو املوضــح بالصــك واملتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وباالطــاع على ما أجاب بــه فضيلته‬\n\n\n                                                                                      ‫‪110‬‬\n\f      ‫وأحلقــه بالصــك وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪34238979‬‬\n      ‫وتاريــخ ‪1434/6/12‬ه ـ فقــد قــررت الدائــرة املصادقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":91,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0abd7b698bc92ce2c080ebeb45df8794b1bdc2bb746d9101cded133d040672b4","normalized_text_hash":"fde1c098d69eb5e4110e923e033e614c794c8970d3d132c782cb42ee71838aa0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p91-34194877"},{"id":"a06aeb97-2278-5159-87a5-d091b445fac5","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -خيار العيب -مطالبة برد ثمن سيارة معيبة -رد دعوى املدعي لقيامه ببيع العن املعيبة قبل املطالبة برد ثمنها -بيع املبيع بعد تلفه -مواجهة املدعى عليه بالدعوى -تقرير الدفاع املدني -تراخي يف املطالبة برد املببيع .","document_number":"33477956","case_number":"33490485","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/26","year":"1434","subject":"بيع -خيار العيب -مطالبة برد ثمن سيارة معيبة -رد دعوى املدعي لقيامه ببيع العن املعيبة قبل املطالبة برد ثمنها -بيع املبيع بعد تلفه -مواجهة املدعى عليه بالدعوى -تقرير الدفاع املدني -تراخي يف املطالبة برد املببيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/26 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33477956 :‬‬\n                    ‫َر ْق ُم الدعوى‪33490485 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34297931‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n ‫بيــع ‪ -‬خيــار العيــب ‪ -‬مطالبــة بــرد ثمــن ســيارة معيبــة ‪ -‬رد دعــوى‬\n ‫املدعــي لقيامــه ببيــع العــن املعيبــة قبــل املطالبــة بــرد ثمنهــا‪ -‬بيــع‬\n ‫املبيــع بعــد تلفــه ‪ -‬مواجهــة املدعــى عليــه بالدعــوى ‪ -‬تقريــر الدفــاع‬\n                               ‫املدنــي ‪ -‬تراخــي يف املطالبــة بــرد املببيــع ‪.‬‬\n\n\n\n\n ‫‪ .1‬نــص ابــن قدامــة يف املغنــى‪« :‬إذا اشــترى معيبـ ًا فباعــه ســقط رده ألنــه‬\n                                                    ‫قــد زال ملكــه عنه» ‪.242/6‬‬\n ‫‪ .2‬نــص املــرداوي يف اإلنصــاف‪« :‬وإن فعلــه عامل ـ ًا بعيبــه فــا شــيء لــه‬\n ‫وكــذا لــو تصــرف فيــه مبــا يــدل علــى الرضــا أو عرضــه للبيع أو اســتغله‬\n ‫وهــو املذهــب يف ذلــك كلــه وعليــه جماهيــر األصحــاب وقطــع بــه‬\n     ‫كثيــر منهــم»‪ 398/11‬اإلنصــاف مــع الشــرح الكبيــر علــى املقنــع ‪.‬‬\n\n\n\n\n ‫تقــدم املدعــي بدعــوى ضــد الشــركة املدعــى عليهــا ( الوكيــل التجاري‬\n ‫املعتمــد للســيارة املشــتراة ) بأنــه اشــترى مــن أحــد معــارض الســيارات‬\n ‫ســيارة جديــدة فتفاجــأ يومــا باحتراقهــا بالكامــل لعيــب مصنعــي ال‬\n ‫بفعــل فاعــل ممــا تعــذر االنتفــاع بهــا فباعهــا بالتشــليح «كومــة حديــد»‬\n ‫لــذا فيطلــب إلــزام املدعــى عليهــا بإعــادة مــا ســلمه مــن ثمــن ‪ ،‬فجــرى‬\n\n                                                                                     ‫‪112‬‬\n\f      ‫ســؤاله كيــف علــم بالعيــب املصنعــي وعــن ســبب تأخــره يف إقامــة‬\n      ‫الدعــوى فأجــاب بــأن الدفــاع املدنــي أخبــره بــأن ســببه عيــب مصنعــي‬\n      ‫وأنــه تقــدم بشــكوى لــدى الداخليــة ضــد صاحــب املعــرض فدفــع بأنــه‬\n      ‫ال عالقــة لــه بذلــك وأن عليــه أن يقيــم دعــواه ضــد الشــركة املــوردة‬\n      ‫‪،‬عليــه وإلقــرار املشــتري ببيعــه الســيارة محــل الدعــوى بعــد ســبعة أشــهر‬\n      ‫مــن تاريــخ شــرائها وألن املدعــي يطلــب إلــزام الشــركة املدعــى عليهــا‬\n      ‫بإعــادة ثمــن الســيارة وطلبــه وإن كان أحــد األمريــن املتاحــن للمشــتري‬\n      ‫العالــم بالعيــب (اإلمســاك مــع األرش أورد الثمــن) عليــه وحلصــر املدعــي‬\n      ‫دعــواه يف طلبــه رد الثمــن وألن الســيارة التــي تصــرف فيهــا املدعــي بالبيع‬\n      ‫هــي أحــد العوضــن وملــا قــرره أهــل العلــم يف هــذه املســألة قال ابــن قدامة‬\n      ‫يف املغنــى‪« :‬إذا اشــترى معيب ـ ًا فباعــه ســقط رده ألنــه قــد زال ملكــه‬\n      ‫عنــه» ‪ ، 242/6‬وقــال املــرداوي يف اإلنصــاف‪« :‬وإن فعلــه عامل ـ ًا بعيبــه‬\n      ‫فــا شــيء لــه وكــذا لــو تصــرف فيــه مبــا يــدل علــى الرضــا أو عرضــه‬\n      ‫للبيــع أو اســتغله وهــو املذهــب يف ذلــك كلــه وعليــه جماهيــر األصحــاب‬\n      ‫وقطــع بــه كثيــر منهــم»‪ 398/11‬اإلنصــاف مــع الشــرح الكبيــر علــى‬\n      ‫املقنــع ‪،‬عليــه فقــد قــررت الدائــرة صــرف النظــر عــن دعــوى املدعــي‬\n      ‫وأخلــت ســبيل املدعــى عليهــا ‪ ،‬بعــرض احلكــم عليــه قــرر االعتــراض‬\n              ‫فأفهــم بالتعليمــات ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n‫ـاء علــى أوراق املعاملــة احملالــة الينــا مــن فضيلــة‬\n                                                      ‫مبكــة املكرمــة وبنـ ً‬\n‫رئيــس هــذه احملكمــة برقــم ‪ 33490485‬يف ‪1433/7/27‬ه ـ واملقيــدة‬\n‫برقــم ‪ 331414585‬يف ‪1433/7/27‬ه ـ واملتعلقــة بدعــوى (‪ ).....‬ضــد‬\n‫ـاء علــى ذلــك فقــد حضــر لــدي يف هــذا اليــوم الثالثــاء‬\n                                                            ‫شــركة (‪ ).....‬بنـ ً‬\n‫‪1433/11/16‬هـ الســاعة ‪ 10‬املدعى (‪ ).....‬ســعودي اجلنســية برقم (‪).....‬‬\n‫وحضــر حلضــوره املدعــو (‪ ).....‬بالســجل املدنــي رقــم (‪ ).....‬بوكالتــه عــن‬\n‫(‪ ).....‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬و(‪ ).....‬ســعودي مبوجــب‬\n‫ســجل مدنــي رقــم (‪ ).....‬بصفتــه مديــر ًا ل(‪ ).....‬احملــدودة املخــول لــه‬\n‫فيهــا إقامــة وســماع الدعــاوى والشــكاوي والســير فيهــا إلــى أخــر‬\n‫درجــة مــن درجــات التقاضــي الصــادرة مــن كتابــة العــدل الثانيــة شــمال‬\n‫محافظــة جــدة برقــم ‪ 28070‬يف ‪1433/3/27‬ه ـ ثــم ادعــى املدعــي يف‬\n‫مواجهــة املدعــى عليــه وكالــة قائــا يف حتريــر دعــواه لقــد اشــتريت مــن‬\n‫الشــركة املدعــى عليهــا ســيارة نــوع ‪ ...‬موديــل ‪2006‬م طــراز ‪ ...‬وكان‬\n‫الشــراء بتاريــخ ‪2006‬م حيــث اشــتريتها بثمــن قــدره مائتــن ألــف ريــال‬\n‫دفعتهــا كاملــة وقــد مكثــت معــي تلــك الســيارة قرابــة ثالثــة أشــهر‬\n‫مــن تاريــخ الشــراء إال أنــي تفاجــأت باحتراقهــا بشــكل كامــل وذلــك‬\n‫االحتــراق لعيــب مصنعــي يف الســيارة أدى إلــى احتراقهــا وأفقدنــي‬\n‫االنتفــاع بهــا مــا جعلنــي أقــوم ببيعهــا يف التشــليح مببلــغ ســبعة عشــر ألــف‬\n‫ريــال لــذا فإنــي أطلــب احلكــم علــى الشــركة املدعــي عليهــا بإعــادة‬\n‫كامــل الثمــن الــذي بذلتــه والبالــغ مائتــن ألــف ريــال هــذه دعــواي‬\n\n                                                                                        ‫‪114‬‬\n\f      ‫وأســأل اجلــواب ثــم ســألته متــى بعــت الســيارة فأجــاب بقولــه لقــد بعتهــا‬\n      ‫بعــد ســبعة أشــهر مــن تاريــخ الشــراء ثــم ســألته عــن كيفيــة معرفتــه‬\n      ‫بــأن احتــراق الســيارة كان بســبب عطــل مصنعــي فأجــاب بقولــه ان‬\n      ‫تقريــر الدفــاع املدنــي والشــرطة والبحــث اجلنائــي أفادونــي بــأن عيب ـ ًا‬\n      ‫مصنعي ـ ًا كان الســبب يف احتراقهــا ثــم ســألته عــن ســبب تراخيــه يف‬\n      ‫مطالبتــه هــذه فأجــاب بقولــه إنــي تقدمــت بشــكاوى يف هــذا املوضــوع‬\n      ‫األولــى رفعتهــا لــوزارة الداخليــة ثــم تركــت متابعتهــا ثــم أقمــت دعــوى‬\n      ‫علــى صاحــب املعــرض الــذي اشــتريتها منــه فقــال انــي لســت مســئو ًال‬\n      ‫ـاء علــى‬‫عــن الســيارة وامنــا شــركة ‪ ...‬هــي املســئولة هكــذا قــال ‪ .‬فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى وال قــرار املشــتري ببيعــه الســيارة محــل الدعــوى‬\n      ‫بعــد ســبعة اشــهر مــن تاريــخ شــرائها وألن املدعــي يطلــب إلــزام الشــركة‬\n      ‫املدعــى عليهــا بإعــادة ثمــن الســيارة البالــغ مائتــن ألــف ريــال وألن طلبــه‬\n      ‫ذلــك وإن كان أحــد األمريــن املتاحــن للمشــتري العالــم بالعيــب وهــي‬\n      ‫امســاك املبيــع بأرشــه وهــو قســط مــا بــن قيمــة الصحــة والعيــب أورده‬\n      ‫وأخــذ الثمــن وحلصــر املدعــي دعــواه يف طلبه رد الثمن وألن الســيارة التي‬\n      ‫تصــرف فيهــا املدعــى بالبيــع هــي أحــد العوضــن وملــا قــرره أهــل العلــم‬\n      ‫يف هــذا اجلانــب حيــث قــال ابــن قدامــة يف املغنــى (( إذا اشــترى معيب ـ ًا‬\n      ‫فباعــه ســقط رده ألنــه قــد زال ملكــه عنــه ))‪ 242/6‬وقــال املــرداوي يف‬\n      ‫اإلنصــاف ( وإن فعلــه عاملـ ًا بعيبــه فــا شــيء لــه وكــذا لــو تصــرف فيــه‬\n      ‫مبــا يــدل علــى الرضــا أو عرضــه للبيــع أو اســتغله وهــو املذهــب يف ذلــك‬\n      ‫كلــه وعليــه جماهيــر األصحــاب وقطــع بــه كثيــر منهــم )‪398/11‬مــع‬\n      ‫ـاء علــى ذلــك فقــد صرفــت النظــر عــن‬  ‫الشــرح الكبيــر علــى املقنــع بنـ ً‬\n      ‫دعــوى املدعــي ‪..................‬أخليــت ســبيل املدعــى عليهــا وبذلــك حكمت‬\n\n\n‫‪115‬‬\n\f‫وبعرضــه علــى املدعــي قــرر اعتراضــه عليــه فأفهمتــه مبراجعــة احلكــم‬\n‫خــال عشــرة أيــام مــن تاريخــه الســتالم نســخة مــن هــذا احلكــم لتقــدمي‬\n‫مــا لديــه حيالــه مــن اعتــراض خــال ثالثــن يومـ ًا مــن تاريخ اســتالمه فإن‬\n‫لــم يفعــل خاللهــا فــإن حقــه يف االســتئناف يســقط ويكتســب احلكــم‬\n                      ‫القطعيــة وبــاهلل التوفيــق حــرر يف ‪1433/11/16‬ه ـ ‪.‬‬\n‫احلمد هلل وحده وبعد فقد عادت أوراق املعاملة من محكمة االستئناف‬\n‫برقــم ‪ 34515117‬يف ‪1434/4/7‬ه ــاملرفق بهــا قــرار مالحظــة الدائــرة‬\n‫احلقوقيــة الثانيــة ذو الرقــم ‪ 3457467‬يف ‪1434/3/8‬ه ـ ونــص احلاجــة‬\n‫منــه (بدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة إعادتهــا ملالحظــة مــا يلــي ‪ -1‬لــم جنــد فضيلــة عــرض دعــوى‬\n‫املدعــي علــى املدعــى عليــه وكالــة وإجــراء الــازم نحوهــا والبــد مــن‬\n‫ذلــك ‪ -2‬ذكــر املدعــي يف الئحتــه االعتراضيــة أمــور ينبغــي مناقشــتها‬\n‫بحضــور الطرفــن وإجــراء الوجــه الشــرعي نحوهــا) اهــ‪ .‬عليــه فإنــي‬\n‫أجيــب أصحــاب الفضيلــة وفقهــم اهلل تعالــى لــكل خيــر بــأن مــا أشــير‬\n‫إليــه يف املالحظــة األولــى فــا شــك أن جــواب املدعــى عليــه أثــر مــن‬\n‫اآلثــار الالزمــة لصحــة الدعــوى وذلــك ألن قطــع اخلصومــة واملنازعــة‬\n‫واجــب وال ميكــن القطــع إال باجلــواب فــكان واجبــا أمــا يف هــذه الدعوى‬\n‫فقــد صرفــت النظــر عــن دعــوى املدعــي ابتــداء لألســباب التــي ذكرتهــا‬\n‫وبالتالــي لــم أرى موجبــا لعرضهــا علــى املدعــى عليــه وكالــة وغيــر خاف‬\n‫علــى أصحــاب الفضيلــة مــا قــرره أهــل العلــم مــن أنــه إذا زال املوجــب‬\n‫زال املوجــب وأمــا املالحظــة الثانيــة فقــد أعــدت االطــاع علــى الالئحــة‬\n‫االعتراضيــة فلــم أرى فيهــا مــا يؤثــر علــى مــا حكمــت بــه وبالتالي الزلت‬\n‫عليــه وأمــرت بإعــادة أوراق املعاملــة حملكمــة االســتئناف لتدقيقهــا‬\n\n\n                                                                                   ‫‪116‬‬\n\f      ‫وبــاهلل التوفيــق وصــل اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                        ‫حتريــرا يف ‪1434/4/20‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامة مبكة‬\n      ‫املكرمــة القائــم بعمــل الشــيخ (‪ ).....‬خلــف فضيلة الشــيخ (‪ ).....‬القاضي‬\n      ‫األســبق بهــذه احملكمــة حيــث عــادت أوراق املعاملــة مــن محكمــة‬\n      ‫االســتئناف باخلطــاب رقــم ‪ 34515117‬يف ‪1434/9/3‬ه ـ رفقهــا الصــك‬\n      ‫الشــرعي رقــم ‪ 33477956‬يف ‪1433/12/26‬ه ـ مظهــر ًا عليــه بقــرار‬\n      ‫الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف رقــم ‪ 34297931‬يف‬\n      ‫‪1434/8/15‬ه ـ املتضمــن وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n      ‫االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ .‬قاضــي اســتئناف‬\n      ‫ختــم وتوقيــع (‪ ).....‬قاضــي اســتئناف ختــم وتوقيــع (‪ ).....‬قاضــي‬\n      ‫اســتئناف ختــم وتوقيــع (‪( ).....‬لــي وجهــة نظــر) ‪ .‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/10/11‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪34/515117‬وتاريــخ‬\n      ‫‪1434/7/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪).....‬‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33477956‬وتاريــخ‬\n      ‫‪1433/12/26‬هـ ‪ ،‬املتضمن دعوى (‪ ).....‬ضد (‪ ، ).....‬وبدراسة الصك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n‫‪117‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":112,"source_page_end":117,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c595041167de68f403926faf6e2c13942b4393846026b5dc4f56b698f6fa25e8","normalized_text_hash":"5ddf30296fae758a3430f2678a234829197e1f090995313e21652779787ab372","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p112-33477956"},{"id":"0f9f2c13-4392-518b-b666-2fd4cad2adca","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -طلب املدعي باقي ثمن املبيع -البينة شهادة الشاهد واليمن -اليمن تشرع يف جانب أقوى املتداعين -احلكم الغيابي بإلزام املدعى عليه أن يسلم للمدعي املبلغ املدعى به والغائب على حجته.","document_number":"34171137","case_number":"33526762","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف لدراسة احلكم وتدقيقه حسب املتبع وباهلل التوفيق","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/24","year":"1434","subject":"بيع -طلب املدعي باقي ثمن املبيع -البينة شهادة الشاهد واليمن -اليمن تشرع يف جانب أقوى املتداعين -احلكم الغيابي بإلزام املدعى عليه أن يسلم للمدعي املبلغ املدعى به والغائب على حجته.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/24 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34171137 :‬‬\n                    ‫َر ْق ُم الدعوى‪33526762 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34249959‬تاريخه‪1434/6/24 :‬هـ‬\n\n\n‫بيــع ‪ -‬طلــب املدعــي باقــي ثمــن املبيــع ‪ -‬البينــة شــهادة الشــاهد واليمــن‬\n‫‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬احلكــم الغيابــي بإلــزام‬\n‫املدعــى عليــه أن يســلم للمدعــي املبلــغ املدعــى بــه والغائــب على حجته‪.‬‬\n\n\n\n\n‫‪ .1‬حديــث ابــن عبــاس ( أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــاهد‬\n                                         ‫واليمني ) رواه مســلم يف صحيحه‪.‬‬\n‫‪ .2‬حديــث أبــي هريــرة قــال ( قضــى رســول اهلل صلــى اهلل عليــه وســلم‬\n‫باليمــن مــع الشــاهد الواحــد ) أخرجــه أبــو داود والترمــذي وابــن ماجــه‬\n                                                                      ‫والبيهقــي‪.‬‬\n‫‪ .3‬قــال ابــن قدامــة ‪ ( :‬وألن اليمــن تشــرع يف حــق مــن ظهــر صدقــه‬\n‫وقــوي جانبــه ولذلــك شــرعت يف حــق صاحــب اليــد لقــوة جنبتــه بهــا‬\n‫‪ ،‬ويف حــق املنكــر لقــوة جنبتــه فــإن األصــل بــراءة الذمــة‪ ،‬واملدعــي ههنــا‬\n‫( أي يف بــاب الشــاهد واليمــن ) قــد ظهــر صدقــه فوجــب أن تشـ ــرع‬\n                                 ‫اليمــن يف حقــه ) اهــ‪ .‬املغـ ــني ( ‪) 131/14‬‬\n‫‪ .4‬قــال ابــن القيــم ‪« :‬وليــس يف القــرآن مــا يقتضــي أنــه ال يحكــم إال‬\n‫بشــاهدين‪ ،‬أو شــاهد وامرأتــن فــإن اهلل ســبحانه إمنــا أمــر بذلــك‬\n‫أصحــاب احلقــوق أن يحفظــوا حقوقهــم بهــذا النصــاب ‪ ،‬ولــم يأمــر‬\n‫ا عــن أن يكــون قــد أمرهــم أال‬   ‫بذلــك احلــكام أن يحكمــوا بــه‪ ،‬فض ـ ً‬\n‫يقضــوا إال بذلــك ولهــذا يحكــم احلاكــم بالنكــول واليمــن املــردودة‬\n                                                                                     ‫‪118‬‬\n\f      ‫واملــرأة الواحــدة والنســاء املنفــردات ال رجــل معهــن ومبعاقــد القمــط‬\n      ‫ووجــوه اآلجــر وغيــر ذلــك مــن طــرق احلكــم التــي لــم تذكــر يف القــرآن‬\n      ‫‪ ....‬فطــرق احلكــم شــيء وطــرق حفــظ احلقــوق شــيء آخــر وليــس‬\n      ‫بينهمــا تــازم فتحفــظ احلقــوق مبــا ال يحكــم بــه احلاكــم ممــا يعلــم‬\n      ‫صاحــب احلــق أنــه يحفــظ بــه حقــه ‪ ،‬ويحكــم احلاكــم مبــا ال يحفــظ‬\n      ‫بــه صاحــب احلــق حقــه وال خطــر علــى بالــه مــن نكــول ورد ميــن وغيــر‬\n                                      ‫ذلــك ) أ ه ـ الطــرق احلكميــة ص (‪)145‬‬\n                  ‫‪ .5‬املادة اخلامسة واخلمسون من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم بعــد تبلغــه‬\n      ‫لشــخصه‪ ،‬أنــه اشــترى منــه ثالثــة رؤوس مــن األغنــام بثمــن إجمالــي‬\n      ‫قــدره ألفــان وســبعمائة وخمســون ريــاال ســلم منــه ثمامنائــة ريــال ولم يســلم‬\n      ‫املبلــغ املتبقــي وقــدره ألــف وتســعمائة وخمســون ريــاال وطلــب إلزامــه‬\n      ‫بتســليم مــا بقــي يف ذمتــه ‪،‬بطلــب البينــة مــن املدعــي علــى دعــواه أحضــر‬\n      ‫شــاهداً‪ ،‬ومت ســماع شــهادته وتعديلــه ‪،‬قــرر املدعــي أال بينــة لديــه ســوى‬\n      ‫الشــاهد ‪،‬بطلــب اليمــن مــن املدعــي املكملــة للشــاهد اســتعد ببذلهــا‪،‬‬\n      ‫ثــم حلفهــا ‪،‬مــن وســائل اإلثبــات التــي جــاءت بهــا الشــريعة اإلســامية‬\n      ‫القضــاء بالشــاهد وميــن الطالــب ‪،‬حديــث ابــن عبــاس رضــي اهلل عنــه‬\n      ‫(أن النبــي صلــى اهلل عليــه وســلم قضــى بالشــاهد واليمــن ) رواه مســلم‬\n      ‫‪،‬أكثــر أهــل العلــم يــرون ثبــوت املــال ملدعيــه بشــاهد وميــن ‪،‬اليمــن‬\n      ‫تكــون يف جانــب أقــوى املتداعيــن‪ ،‬وأقــوى املتداعيــن يف هــذا البــاب‬\n      ‫هــو املدعــي لوجــود الشــاهد ‪،‬لــذ ثبتــت صحــة دعــوى املدعــي فيمــا‬\n\n‫‪119‬‬\n\f‫يدعيــه‪ ،‬واحلكــم غيابيــا بإلــزام املدعــى عليــه أن يســلم للمدعــي املبلــغ‬\n‫املدعــى بــه وقــدره ألــف وتســعمائة وخمســون ريــا ًال ‪ ،‬ســيتم إكمــال مــا‬\n‫يلــزم حيــال إبــاغ املدعــى عليــه باحلكــم ‪،‬بعــد رفــع احلكــم حملكمــة‬\n                                           ‫االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬املــازم القضائــي لــدى‬\n‫فضيلــة الشــيخ ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة بالريــاض‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n‫بالريــاض برقــم ‪ 33526762‬وتاريــخ ‪1433/8/14‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 331539887‬وتاريــخ ‪ 1433/08/14‬ه ـ ففــي يــوم االثنــن‬\n‫املوافــق‪ 1434/03/23‬ه ـ افتتحــت اجللســة الســاعة ‪ ، 08 : 15‬وفيهــا‬\n‫‪ ................‬ســعودي اجلنســية مبوجــب الســجل رقــم ‪ ............‬وادعــى‬\n‫ا يف دعــواه عليــه ‪:‬‬  ‫علــى الغائــب عــن مجلــس احلكــم ‪ ...............‬قائ ـ ً‬\n‫اننــي قــد بعــت علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم ثالثــة‬\n‫مــن االغنــام اثنــان منهــا مــن نــوع جنــدي واالخــر مــن نــوع املاعــز بقيمــة‬\n‫اجماليــة قدرهــا ألفــان وســبعمائة وخمســون ريــال وقــد ســلم لــي مبلغــا‬\n‫قــدره ثمامنائــة ريــال ولــم يســلم املبلــغ املتبقــي وقــدره الــف وتســعمائة‬\n‫وخمســون ريــال أطلــب إلزامــه بتســديد املتبقــي يف ذمتــه وقــدره الــف‬\n‫وتســعمائة وخمســون ريــال هــذه دعــواي ‪ ،‬وقــد ســبق لنــا طلــب املدعــى‬\n‫عليــه املذكــور ملقابلــة خصمــه شــرع ًا وتبلــغ باملواعيــد نظامي ـ ًا ولــم‬\n‫يحضــر كمــا يتضــح مــن مرفقــات املعاملــة وقــد وردنــا خطــاب محضــر‬\n‫اخلصــوم يف هــذه احملكمــة برقــم ‪331942529‬بتاريــخ ‪1433/11/2‬‬\n                                                                                       ‫‪120‬‬\n\f      ‫ه ـ واملتضمــن تبلــغ املدعــى عليــه لشــخصه وملــا ســبق واســتناد ًا علــى‬\n      ‫املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ونصهــا ‪ (:‬إذا‬\n      ‫غــاب املدعــى عليــه عــن اجللســة األولــى فيؤجــل النظــر يف القضيــة إلــى‬\n      ‫جلســة الحقــة يبلــغ بهــا املدعــى عليــه ‪ ،‬فــإن غــاب عــن هــذه اجللســة أو‬\n      ‫غــاب عــن جلســة أخــرى دون عــذر تقبلــه احملكمــة فتحكــم احملكمــة‬\n      ‫يف القضيــة ويعــد حكمهــا يف حــق املدعــى عليــه غيابي ـ ًا مــا لــم يكــن‬\n      ‫غيابــه بعــد قفــل بــاب املرافعــة يف القضيــة فيعــد احلكــم حضوريـ ًا ) ا‪.‬ه ـ‬\n      ‫‪،‬فلــذا قــررت الســير يف نظــر الدعــوى وطلبــت مــن املدعــي بينــة علــى‬\n      ‫صحــة مــا ادعــى بــه فأجــاب قائــا أنــه ليــس لــدي بينــة علــى البيعــة اال‬\n      ‫شــاهد واحــد فقــط وهــو هــذا احلاضــر وأطلــب ســماع شــهادته فأذنــت‬\n      ‫لــه فأحضــر للشــهادة ‪ .................‬ســعودي اجلنســية مبوجــب الســجل رقــم‬\n      ‫‪ ................‬ولــدى استشــهاده شــهد قائــا أشــهد هلل تعالــى أن للمدعــي‬\n      ‫يف ذمــة املدعــى عليــه ‪ ...............‬مبلغــا قــدره الــف وتســعمائة وخمســون‬\n      ‫ريــال وذلــك الباقــي مــن قيمــة االغنــام التــي باعهــا املدعــي للمدعــى‬\n      ‫عليــه هكــذا شــهد فجــرى تعديــل الشــاهد التعديــل الشــرعي مــن قبــل‬\n      ‫‪ ...............‬ســعودي اجلنســية مبوجــب الســجل رقــم ‪ ...............‬و‪..............‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل رقــم ‪ ...............‬مت طلبــت زيــادة بينــة‬\n      ‫مــن املدعــي فأجــاب قائــا أنــه ال بينــة لــدي ســوى هــذا الشــاهد فجــرى‬\n      ‫ا ‪ ( :‬واهلل‬   ‫طلــب اليمــن مــن املدعــي مــع الشــاهد فاســتعد وحلــف قائ ـ ً‬\n      ‫العظيــم أننــي قــد بعــت علــى املدعــى عليــه ‪ ...............‬ثالثــة مــن االغنــام‬\n      ‫مببلــغ قــدره الفــان وســبعمائة وخمســون وصــل منهــا مبلغــا قــدره ثمامنائــة‬\n      ‫ريــال والباقــي الــف وتســعمائة وخمســون لــم اســتلمها حتــى االن واهلل‬\n      ‫ـاء علــى مــا تقــدم وملــا كان مــن وســائل اإلثبــات التــي جــاءت‬   ‫العظيــم فبنـ ً‬\n\n‫‪121‬‬\n\f‫بهــا الشــريعة اإلســامية القضــاء بالشــاهد وميــن الطالــب ‪ ،‬وألن أكثــر‬\n‫أهــل العلــم يــرون ثبــوت املــال ملدعيــه بشــاهد وميــن فقــد روي ذلــك عــن‬\n‫ابــي بكــر وعمــر وعثمــان وعلــي رضــي اهلل عنهــم وهــو قــول الفقهــاء‬\n‫الســبعة وعمــر بــن عبدالعزيــز واحلســن وشــريح وايــاس وعبــداهلل بــن‬\n‫عتبــة وابــي ســلمة بــن عبدالرحمــن وربيعــة ومالــك وابــن أبــي ليلــى وابــي‬\n‫الزنــاد والشــافعي ‪ ،‬ودليــل ذلــك حديــث أبــي هريــرة قــال ( قضــى رســول‬\n‫اهلل صلــى اهلل عليــه وســلم باليمــن مــع الشــاهد الواحــد ) أخرجــه أبــو‬\n‫داود والترمــذي وابــن ماجــه والبيهقــي ‪ ،‬وحديــث ابــن عبــاس ( أن النبــي‬\n‫صلى اهلل عليه وســلم قضى بالشــاهد واليمني ) رواه مســلم يف صحيحه‬\n‫وقــال النســائي ‪ :‬اســناده جيــد ( انظــر حتفــة االشــراف ‪ ) 187/5‬وألن‬\n‫ا عــن ثبوتــه‬\n             ‫القضــاء بالشــاهد واليمــن موافــق ألصــول الشــريعة ‪ -‬فضـ ً‬\n‫بالدليــل ‪ -‬مــن حيــث أن اليمــن تكــون يف جانــب أقــوى املتداعيــن‪،‬‬\n‫وأقــوى املتداعيــن يف هــذا البــاب هــو املدعــي لوجــود الشــاهد ‪ ،‬قــال‬\n‫ابــن قدامــة ‪ ( :‬وألن اليمــن تشــرع يف حــق مــن ظهــر صدقــه وقــوي جانبــه‬\n‫ولذلــك شــرعت يف حــق صاحــب اليــد لقــوة جنبتــه بهــا ‪ ،‬ويف حــق املنكر‬\n‫لقــوة جنبتــه فــإن األصــل بــراءة الذمــة‪ ،‬واملدعــي ههنــا ( أي يف بــاب‬\n‫الشــاهد واليمــن ) قــد ظهــر صدقــه فوجــب أن تشـ ــرع اليمــن يف حقــه )‬\n‫أه ـ املغـ ــني ( ‪ ) 131/14‬وقــال ابــن القيــم ‪ ( :‬وليــس يف القــرآن مايقتضــي‬\n‫أنــه ال يحكــم إال بشــاهدين ‪ ،‬أو شــاهد وامرأتــن فــإن اهلل ســبحانه‬\n‫إمنــا أمــر بذلــك أصحــاب احلقــوق أن يحفظــوا حقوقهــم بهــذا النصــاب ‪،‬‬\n‫ا عــن أن يكــون قــد‬    ‫ولــم يأمــر بذلــك احلــكام أن يحكمــوا بــه ‪ ،‬فضـ ً‬\n‫أمرهــم أال يقضــوا اال بذلــك ولهــذا يحكــم احلاكــم بالنكــول واليمــن‬\n‫املــردودة واملــرأة الواحــدة والنســاء املنفــردات ال رجــل معهــن ومبعاقــد‬\n\n\n                                                                                    ‫‪122‬‬\n\f      ‫القمــط ووجــوه اآلجــر وغيــر ذلــك مــن طــرق احلكــم التــي لــم تذكــر يف‬\n      ‫القــرآن ‪ ....‬فطــرق احلكــم شــيء وطــرق حفــظ احلقــوق شــيء آخــر وليــس‬\n      ‫بينهمــا تــازم فتحفــظ احلقــوق مبــا ال يحكــم بــه احلاكــم ممــا يعلــم‬\n      ‫صاحــب احلــق أنــه يحفــظ بــه حقــه ‪ ،‬ويحكــم احلاكــم مبــا ال يحفــظ بــه‬\n      ‫صاحــب احلــق حقــه وال خطــر علــى بالــه مــن نكــول ورد ميــن وغيــر ذلــك)‬\n      ‫أ ه ـ (الطــرق احلكميــة ص (‪ )145‬وعلــى هــدى مــا تقــدم وحيــث ان‬\n      ‫املدعــي قــد تقــوى جانبــه فيمــا يتعلــق بدعــواه لــذا فقــد ثبــت لــدي صحــة‬\n      ‫دعــوى املدعــي فيمــا يدعيــه وحكمــت علــى املدعى عليــه ‪ ............‬غيابيا‬\n      ‫بــأن يدفــع للمدعــي املبلــغ املدعــى بــه وقــدره الــف وتســعمائة وخمســون‬\n      ‫ريــا ًال وبعــد ذلــك يخلــى ســبيله مــن هــذه الدعــوى وهــو علــى دعــواه متــى‬\n      ‫حضــر ‪ ،‬وبعرضــه علــى املدعــي قنــع باحلكــم وقــررت إكمــال مــا يلــزم‬\n      ‫حيــال إبــاغ املدعــى عليــه الغائــب باحلكــم حســب التعليمــات ‪ ،‬ثــم رفــع‬\n      ‫كامــل املعاملــة حــال اإلقتضــاء إلــى محكمــة االســتئناف لدراســة‬\n      ‫احلكــم وتدقيقــه حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالريــاض برقــم‬\n      ‫‪ 331539887‬وتاريــخ ‪1434/06/14‬ه ـ ملرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ .............‬املســجل برقــم ‪34171137‬‬\n                 ‫وتاريــخ ‪1434/3/24‬ه ـ اخلــاص بدعــوى ‪ ...........‬ضــد ‪...........‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه لــم يظهــر مــا يوجــب املالحظــة واهلل‬\n                                 ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n‫‪123‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":118,"source_page_end":123,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"019f6442e3142